var e={"azure-foundations":{title:`Azure: foundations`,short:`Foundations`,description:`Resource hierarchy, subscriptions, resource groups, regions and tools (portal, CLI, PowerShell, ARM/Bicep).`,topics:[`Hierarchy`,`Regions`,`Tools`,`ARM and Bicep`]},"azure-admin":{title:`Azure: administration and architecture`,short:`Admin and architecture`,description:`Networking (NSG, Bastion, peering, Private Link), storage redundancy and governance (Azure Policy, locks).`,topics:[`NSG and Bastion`,`Peering`,`Storage`,`Policy and locks`]},"identity-security":{title:`Identity and security`,short:`Identity and security`,description:`RBAC and least privilege, Conditional Access (report-only, emergency accounts) and privileged access with PIM.`,topics:[`RBAC`,`Conditional Access`,`PIM`,`Emergency accounts`]},observability:{title:`Observability and collection`,short:`Log collection`,description:`Log Analytics workspaces, diagnostic settings, agents, collection rules and troubleshooting missing data.`,topics:[`Log Analytics`,`Diagnostics`,`Agents`,`DCR`]},sentinel:{title:`Microsoft Sentinel`,short:`Sentinel`,description:`Components, scheduled rules, incident triage, automation rules, playbooks and watchlists.`,topics:[`Scheduled rules`,`Incidents`,`Automation`,`Watchlists`]},kql:{title:`KQL Academy`,short:`KQL`,description:`The query language of Sentinel and Log Analytics, from filters to joins, with a local engine and fictional data.`,topics:[`Filter`,`Aggregate`,`Time`,`Joins`]},soc:{title:`SOC investigations`,short:`Investigations`,description:`Multi-evidence investigation scenarios: password spray, exfiltration, phishing, privilege escalation.`,topics:[`Triage`,`Pivot`,`Timeline`,`Conclusion`]}},t={"az-hierarchy":{name:`Azure hierarchy`,description:`Management groups, subscriptions, resource groups, resources.`},"az-core-services":{name:`Core Azure services`,description:`Regions, availability zones, compute, storage and redundancy.`},"az-tools":{name:`Azure tools`,description:`Portal, CLI, PowerShell, ARM and Bicep.`},"az-network":{name:`Azure networking`,description:`Virtual networks, subnets, network security groups.`},"az-governance":{name:`Governance`,description:`Tags, locks, policies.`},"id-rbac":{name:`RBAC and least privilege`,description:`Roles, scopes and minimal assignments.`},"id-privileged":{name:`Privileged access`,description:`PIM, emergency accounts, privileged roles.`},"id-entra":{name:`Microsoft Entra ID`,description:`Users, groups, Conditional Access.`},"obs-collection":{name:`Log collection`,description:`Diagnostic settings, agents, DCRs.`},"obs-workspace":{name:`Log Analytics workspaces`,description:`Design, retention, tables.`},"sen-onboarding":{name:`Sentinel onboarding`,description:`Connectors and go-live.`},"sen-automation":{name:`Sentinel automation`,description:`Automation rules, playbooks, watchlists.`},"sen-detection":{name:`Sentinel detection`,description:`Analytics rules and incidents.`},"kql-filter":{name:`KQL: filter and project`,description:`where, project, extend, take, sort.`},"kql-aggregate":{name:`KQL: aggregate`,description:`summarize, count, dcount, make_set, arg_max.`},"kql-time":{name:`KQL: time`,description:`ago, bin, datetime_diff, time windows.`},"kql-join":{name:`KQL: joins and unions`,description:`join, union, let, datatable.`},"kql-reading":{name:`KQL: reading and fixing`,description:`Read a result, fix an error.`},"soc-triage":{name:`SOC triage`,description:`Tell a true positive from a false positive.`},"soc-investigation":{name:`SOC investigation`,description:`Pivot, rebuild a timeline, conclude.`}},n={"labo-rg-etiquettes-verrou":{title:`Resource group, tags and lock`,summary:`Create a resource group, add a tag and a CanNotDelete lock to it, then confirm that deletion is refused.`,prerequisites:[`A test Azure subscription (a free account is enough) where you are Owner`,`Azure CLI installed and signed in with az login (no secret is entered in this platform)`,`Complete exercises az-001 to az-005`],licenses:`No additional license: an Azure subscription is enough.`,cost:`No billable resource is created. Resource groups, tags and locks are free.`,steps:[`Choose a region and a name: az group create --name rg-labo-verrou --location canadacentral --tags Env=labo Responsable=vous`,`Show the group and check the tag: az group show --name rg-labo-verrou --query tags`,`Add the lock: az lock create --name pas-de-suppression --resource-group rg-labo-verrou --lock-type CanNotDelete`,`Try to delete the group: az group delete --name rg-labo-verrou --yes. The operation must fail because of the lock.`,`List the locks of the group: az lock list --resource-group rg-labo-verrou`],checks:[`The tag Env=labo appears in the output of az group show`,`The deletion attempt is refused with a message that mentions the lock`,`az lock list shows the lock pas-de-suppression of type CanNotDelete`],cleanup:[`Remove the lock: az lock delete --name pas-de-suppression --resource-group rg-labo-verrou`,`Delete the group: az group delete --name rg-labo-verrou --yes`,`Check that it no longer exists: az group exists --name rg-labo-verrou (expected result: false)`]},"labo-nsg-regles":{title:`Network security group rules`,summary:`Create an NSG, add a high-priority deny rule and observe the evaluation order and the default rules.`,prerequisites:[`A test Azure subscription where you are Contributor or Owner`,`Azure CLI signed in with az login`,`Complete exercises az-019 to az-021`],licenses:`No additional license.`,cost:`A network security group is free. This lab creates no virtual machine and no public IP address.`,steps:[`Create a resource group: az group create --name rg-labo-nsg --location canadacentral`,`Create the NSG: az network nsg create --resource-group rg-labo-nsg --name nsg-labo`,`Add a rule that denies RDP from the Internet: az network nsg rule create --resource-group rg-labo-nsg --nsg-name nsg-labo --name refuser-rdp --priority 200 --direction Inbound --access Deny --protocol Tcp --source-address-prefixes Internet --destination-port-ranges 3389`,`Add a lower-priority allow rule for the same port: priority 300, access Allow. Note which one wins.`,`List the custom rules and then the default rules: az network nsg rule list --resource-group rg-labo-nsg --nsg-name nsg-labo --include-default --output table`],checks:[`The priority 200 rule (Deny) comes before the priority 300 rule (Allow) and wins`,`The default rules appear with priorities 65000, 65001 and 65500`,`You can explain why the priority 300 Allow rule has no effect on RDP traffic from the Internet`],cleanup:[`Delete everything: az group delete --name rg-labo-nsg --yes`,`Check: az group exists --name rg-labo-nsg (expected result: false)`]},"labo-politique-audit":{title:`Azure Policy: evaluate without enforcing`,summary:`Assign a policy in DoNotEnforce mode on a test resource group and read the compliance evaluation.`,prerequisites:[`A test Azure subscription where you can assign policies (Owner or Resource Policy Contributor)`,`Azure CLI signed in with az login`,`Complete exercises az-029 to az-033`],licenses:`No additional license: Azure Policy is a governance service with no evaluation charges of its own.`,cost:`No billable resource is required. The lab can be done on an empty resource group. Confirm current pricing in the documentation if you extend it to other services.`,steps:[`Create a test resource group: az group create --name rg-labo-policy --location canadacentral`,`In the portal, open Azure Policy, Definitions, and search for the built-in definition “Inherit a tag from the resource group if missing”.`,`Assign it to the group rg-labo-policy, choosing the enforcement mode “Disabled” (DoNotEnforce) and the tag name Env. A managed identity is required for the modify effect: let the portal create it.`,`Set the tag Env=labo on the group, then create a free resource (for example a virtual network) without a tag.`,`Wait for the evaluation (it can take a moment) then open Compliance. Note the state of the resource and the reason.`],checks:[`The assignment shows the enforcement mode DoNotEnforce`,`The resource without a tag appears as non-compliant, without the tag having been added to it automatically`,`You can explain the difference between DoNotEnforce, an exclusion and an exemption`],cleanup:[`Delete the policy assignment from Azure Policy, Assignments`,`Delete the group: az group delete --name rg-labo-policy --yes`,`Check that no assignment from the lab remains in Azure Policy`]},"labo-diagnostic-activite":{title:`Send the activity log to Log Analytics`,summary:`Create a workspace, export the subscription activity log and find your own operations with KQL.`,prerequisites:[`A test Azure subscription where you are Owner`,`Azure CLI signed in with az login`,`Complete exercises obs-001 to obs-004`],licenses:`No additional license.`,cost:`A Log Analytics workspace bills ingestion and retention. The volume in this lab is low, but not zero: check current Azure Monitor pricing before you start and delete the resources at the end.`,steps:[`Create a group and a workspace: az group create --name rg-labo-logs --location canadacentral, then az monitor log-analytics workspace create --resource-group rg-labo-logs --workspace-name law-labo`,`In the portal, open Monitor, Activity log, Diagnostic settings and add a setting that sends the Administrative and Security categories to law-labo.`,`Perform a visible operation: create then delete an empty resource group.`,`After a few minutes, open the workspace logs and run: AzureActivity | where Caller has "your-account" | project TimeGenerated, OperationNameValue, ResourceGroup | order by TimeGenerated desc`,`Compare your result with the detection in exercise kql-063 (deletion of diagnostic settings).`],checks:[`The AzureActivity table contains your create and delete operations`,`The Caller field matches your account`,`You can explain why deleting a diagnostic setting deserves an alert`],cleanup:[`Delete the activity log diagnostic setting`,`Delete the group: az group delete --name rg-labo-logs --yes (the workspace is deleted with it)`,`Check that no Log Analytics resource from the lab remains`]},"labo-sentinel-regle":{title:`Sentinel: connect a source and create a scheduled rule`,summary:`Enable Microsoft Sentinel on a test workspace, connect the Azure activity log and create a scheduled rule.`,prerequisites:[`A test Azure subscription and a test Log Analytics workspace (see the previous lab)`,`Sufficient rights to enable Sentinel (Contributor on the group) and to manage the connector`,`Complete exercises sen-001 to sen-007`],licenses:`No Microsoft 365 license is needed for the Azure activity connector. Identity connectors have their own license requirements: check them in the documentation before adding them.`,cost:`Sentinel bills the ingestion of analyzed data on top of Log Analytics. Check current pricing and any trial offers before you start; limit the lab to a few days and a low volume.`,steps:[`In the portal, add Microsoft Sentinel to the test workspace.`,`Open Data connectors and connect “Azure Activity” to your test subscription.`,`Create a scheduled rule (Analytics, Create) named “Diagnostic setting deletion”.`,`Paste the query from exercise sen-007, set the frequency to 5 minutes and the lookback period to 10 minutes (see sen-004), and enable grouping of alerts into incidents.`,`Trigger the detection by creating then deleting a diagnostic setting on a test resource, then wait for the incident.`],checks:[`The rule is enabled and runs at the chosen frequency`,`An incident appears after the diagnostic setting is deleted`,`The Caller field of the incident identifies you`],cleanup:[`Disable then delete the analytics rule`,`Disconnect the Azure activity connector`,`Remove Microsoft Sentinel from the workspace, then delete the lab resource group`]},"labo-acces-conditionnel-rapport":{title:`Conditional Access in report-only mode`,summary:`In a test tenant, create a location-based block policy in report-only mode, exclude an emergency account and read the impact.`,prerequisites:[`A TEST Microsoft Entra tenant. Never use a production tenant for this lab`,`A role that lets you manage Conditional Access in this test tenant`,`A test emergency account already created and protected`,`Complete exercises id-010 to id-012`],licenses:`Conditional Access requires a suitable Microsoft Entra ID license. Check the current licensing page for your test tenant before you start.`,cost:`No Azure infrastructure cost. Any cost is that of the test tenant licenses.`,steps:[`Open Entra, Protection, Conditional Access, and create a new policy named “Block outside Canada (test)”.`,`Target “All users” and exclude your test emergency account.`,`Choose all cloud apps and a location condition: any location except Canada.`,`Choose the “Block access” control and set the state to “Report-only”. Do not enable the policy.`,`Sign in a few times with a test account, then open the policy impact report.`],checks:[`The policy state is “Report-only”`,`The emergency account is in the exclusion list`,`The report shows the effect the policy would have had without having applied it`],cleanup:[`Delete the test policy`,`Check that no policy from the lab remains in the test tenant`]}},r={"cours-az-hierarchie":{title:`The Azure hierarchy and scopes`,summary:`Management groups, subscriptions, resource groups, resources: where to place a role, a policy or a lock.`,body:`Everything in Azure lives in a four-level hierarchy. A setting applied at one level is **inherited** by every level below it. This is the foundation of governance: you set a rule once, in the right place.

## The four scopes

- **Management group**: groups subscriptions. Each group has a single parent, and you can nest up to six levels.
- **Subscription**: the billing and access boundary.
- **Resource group**: a logical container. A resource belongs to a single group and can be moved.
- **Resource**: a virtual machine, a storage account, a key vault.

## What is inherited and what is not

Role assignments, policies and locks are inherited downward. **A resource group's tags are not**: a resource does not automatically receive the tags of its group, you need a policy to do that.

Deleting a resource group deletes all its contents. That is handy for cleaning up a lab, and dangerous if you pick the wrong group.

> Rule of thumb: set access at the smallest scope that meets the need, and compliance rules at the broadest level that justifies them.

## The path of a request

Every request (portal, CLI, template) goes through Azure Resource Manager. It authenticates, checks permissions, then forwards the request to the relevant resource provider. That is why the portal and the CLI give the same results: they talk to the same interface.`},"cours-az-outils":{title:`Tools, declarative templates and availability zones`,summary:`Portal, CLI, PowerShell, Bicep, and the difference between zonal, zone-redundant and non-zonal.`,body:`Choosing a tool is not just a matter of taste: it determines what is **reproducible**.

## Tools

- **Azure portal**: exploration and diagnostics.
- **Azure CLI and Azure PowerShell**: scriptable actions, useful in a pipeline.
- **ARM templates and Bicep**: a **declarative** approach. You describe the desired state and Azure does what is needed to reach it. Replaying the same template gives the same result.

## Availability zones

An Azure region can have several zones, which are physically separate locations. A resource can be:

- **zonal**: pinned to one zone, and you manage replication and failover yourself;
- **zone-redundant**: Microsoft manages distribution, replication and failover;
- **non-zonal**: placed in any zone, which means a zone outage can make it unavailable.

Logical zone numbers are mapped to physical zones differently for each subscription. Do not assume that zone 1 in two subscriptions is the same building.

> A deployment that says nothing about zones is not protected against a zone outage. Resilience is a design choice.`},"cours-az-reseau":{title:`Azure networking: NSG, Bastion and peering`,summary:`Network security rules, administration access without exposure, hub-and-spoke and Private Link.`,body:`## Network security groups (NSG)

An NSG is a list of rules evaluated by **increasing priority** (from 100 to 4096). As soon as a rule matches, processing stops. Each NSG contains default rules with high priority numbers (65000 and above) that cannot be deleted, but that you can **override** with a rule of lower priority number.

- Inbound: traffic from the virtual network and from the Azure load balancer is allowed, the rest is denied.
- Outbound: traffic to the virtual network and to the Internet is allowed, the rest is denied.

> Never expose 22 or 3389 to 0.0.0.0/0. Use Azure Bastion or a VPN.

## Azure Bastion

Bastion provides RDP and SSH over TLS (port 443) directly from the portal, **without a public IP address** on the virtual machine. It is deployed in a subnet named \`AzureBastionSubnet\` of at least /26.

## Hub-and-spoke and shared gateway

The "hub" network hosts shared services. The "spoke" networks connect to it through peering. To share the hub's VPN gateway: **Allow gateway transit** on the hub side, **Use remote gateways** on the spoke side. A spoke can use only one remote gateway, and the Basic tier is not supported.

## Private access to PaaS services

A **service endpoint** still uses a public address, and is free. A **private endpoint** creates an interface with a private address in your network, targets a specific instance, requires DNS and has a cost. For a new production design, the private endpoint is generally preferred.

## Storage redundancy

LRS: three copies in one datacenter. ZRS: three zones. GRS and GZRS: add a secondary region with asynchronous copy. Redundancy protects against an outage, **not against a deletion**: all copies reflect the current state.`},"cours-az-gouvernance":{title:`Governance: Azure Policy, locks and RBAC`,summary:`Three tools, three questions: who can act, what must be complied with, what must be protected.`,body:'Three tools are easy to confuse. Ask yourself the right question:\n\n- **RBAC**: who can do what?\n- **Azure Policy**: what must be complied with?\n- **Lock**: what must be protected against an accidental action?\n\n## Azure Policy\n\nEach definition has an effect. The evaluation order is: `disabled`, `append` and `modify`, `deny`, `audit`, then the related-resource effects such as `auditIfNotExists`. To introduce a policy in an existing environment, start with **audit**: you measure the impact without breaking anything.\n\n- `deployIfNotExists` and `modify` need a **managed identity** with the required rights.\n- The assignment does not fix existing resources: you need a **remediation task**.\n- `enforcementMode = DoNotEnforce` evaluates without applying the effect, which is useful for testing.\n- An **exclusion** (`notScopes`) removes resources from the calculation; an **exemption** waives them while keeping them visible, with an optional expiration.\n\n## Locks\n\n`CanNotDelete` prevents deletion, `ReadOnly` also prevents modification. They are inherited, the most restrictive wins, and they only target the **management plane**: they do not protect the contents of a storage account.\n\n> A ReadOnly lock placed "to be safe" can block legitimate operations, such as scaling. Choose the lightest one that meets the need.'},"cours-id-rbac":{title:`RBAC and least privilege`,summary:`Principal, role, scope: how to assign minimal access and keep it readable.`,body:`An Azure role assignment combines three elements: **who** (the security principal), **what** (the role definition) and **where** (the scope).

## Basic roles

- **Owner**: everything, including assigning roles.
- **Contributor**: creates and manages resources, but **cannot assign roles**.
- **Reader**: view only.
- **User Access Administrator**: manages access without managing resources.

This separation limits privilege escalation: a compromised Contributor cannot grant themselves Owner.

## Applying least privilege

1. Start from the real need, not the most convenient role.
2. Choose the narrowest role that covers it, including data roles (for example reading blobs).
3. Assign at the **lowest scope** that is enough: the assignment is inherited.
4. Assign to **groups**, not individuals: joiners and leavers are handled through membership.

## Microsoft Sentinel roles

Reader reads, Responder manages incidents, Contributor builds rules and workbooks, Playbook Operator runs playbooks. Give Responder to the tier 1 analyst, not Azure Contributor.

> An assignment command with \`--role "Owner"\` on an entire subscription is almost always a red flag in code review.`},"cours-id-acces-conditionnel-pim":{title:`Conditional Access and privileged access`,summary:`Deploy a policy without locking yourself out, protect emergency accounts and reduce standing privileges with PIM.`,body:`## Conditional Access

A Conditional Access policy is evaluated **after** first-factor authentication. To deploy safely:

1. define the policy and its **exclusions for emergency accounts**;
2. enable it in **report-only** mode;
3. analyze the impact in the reports;
4. enable it.

An emergency (break-glass) account is the last escape hatch if a misconfigured policy locks everyone out. It is excluded from blocking policies, heavily protected, rarely used, and **every use triggers an alert**.

Policies aimed at users **do not cover** service principals. Workload identities have their own Conditional Access.

## Privileged Identity Management (PIM)

PIM requires Microsoft Entra ID P2 or ID Governance. It replaces standing privilege with **on-demand** privilege:

- **eligible**: the user can activate the role;
- **active**: the role is available without activation;
- **activation** can require MFA, a justification and approval, and it is time-limited.

For Azure resource roles, only **Owner** and **User Access Administrator** can manage assignments in PIM.

> The controls complement each other: RBAC sets the scope, PIM limits it in time, Conditional Access frames the sign-in, and the emergency account guarantees a fallback.`},"cours-obs-collecte":{title:`Log collection: diagnostics, AMA and collection rules`,summary:`Where logs come from, how they reach Log Analytics and how to diagnose silent collection.`,body:`## Three families of logs

- **Azure activity log**: management-plane operations of a subscription (who created, changed or deleted what).
- **Resource logs**: what a resource does, collected **only** if you create a diagnostic setting.
- **Microsoft Entra logs**: sign-ins and directory audit.

A diagnostic setting sends to a Log Analytics workspace (queries, alerts, Sentinel), a storage account (archiving) or an Event Hub (stream to an external tool).

## Machines: the agent and the rule

The **Azure Monitor Agent (AMA)** collects on the machine. A **data collection rule (DCR)** describes what to collect, how to transform it and where to send it. An **association** links the rule to the machine. Without an association, the agent collects nothing.

An ingestion transformation lets you **filter rows**, remove sensitive columns or normalize, before storage. It never modifies what is already stored.

## Diagnosing silent collection

First check that the agent is communicating, using the \`Heartbeat\` table.

\`\`\`kql
Heartbeat
| summarize DernierePulsation = max(TimeGenerated) by Computer
| where DernierePulsation < ago(30m)
| order by DernierePulsation asc
\`\`\`

If heartbeats arrive but \`SecurityEvent\` stays empty, look at the rule, its XPath filters and the association.

> Deleting a diagnostic setting creates a blind spot. Create an alert on the \`DIAGNOSTICSETTINGS/DELETE\` operations of the activity log.`},"cours-obs-espace-travail":{title:`Workspaces: table plans and retention`,summary:`Choose a plan per table, size interactive and total retention, and know when to split workspaces.`,body:`## Table plans

The plan is chosen **table by table**:

- **Analytics**: full analysis, alerts and detections.
- **Basic**: high volume, reduced cost, limited queries (30-day window).
- **Auxiliary**: very low cost for rarely used data; **alerts do not work**.

A table that feeds a detection rule stays in Analytics. Changing the plan is limited to once a week per table.

## Retention

- Default value: 30 days (90 with Sentinel).
- Analytics interactive retention: from 4 to 730 days.
- Total retention: up to 12 years. The part beyond interactive is long-term, cheaper, and accessible through a **search** (search job).

Example: 90 days of fast search and 2 years of retention for \`SigninLogs\` is set as 90 days interactive and 730 days total.

## One workspace or several?

A single workspace simplifies detection and hunting. Split for data residency, strict access separation or governance constraints, not out of habit.

> Before building a rule on a table: the data arrives, the table is in Analytics, and retention covers the search period.`},"cours-sen-detection":{title:`Sentinel: components, scheduled rules and triage`,summary:`From collection to incident, how to size a scheduled rule and classify the closure of an incident.`,body:`## The chain

A **connector** brings the logs in, an **analytics rule** runs a query and generates alerts, an **incident** groups alerts and entities, and the response goes through an **automation rule** or a **playbook**.

## Scheduled rule: the parameters that matter

- Frequency and lookback period range from 5 minutes to 14 days.
- Events are evaluated by their timestamp but can **arrive late**: the documentation mentions an ingestion delay of up to 5 minutes. A lookback period equal to the frequency lets events slip through.
- A lookback margin creates overlaps, which are absorbed by grouping alerts into incidents.

Example of a rule query, one row per address to flag:

\`\`\`kql
SigninLogs
| where ResultType != "0"
| summarize Echecs = count() by IPAddress
| where Echecs >= 20
| project IPAddress, Echecs
\`\`\`

## Triage and closure

Overview (severity, tactics, alerts), entities, timeline in the logs, decision, response, closure. Always classify:

- **true positive**: real malicious activity;
- **benign positive**: real but authorized (penetration test);
- **false positive**: the rule got it wrong;
- **undetermined**: insufficient evidence.

These classifications guide rule tuning.

> After March 31, 2027, Sentinel is no longer available in the Azure portal: management is done in the Defender portal. Plan the transition.`},"cours-sen-automatisation":{title:`Automation and watchlists`,summary:`Automation rule or playbook, muting with an expiration, and enrichment with a reference list.`,body:`## Automation rule or playbook

An **automation rule** acts on the incident itself: assign, tag, change severity, close. It can also launch a playbook. A **playbook** is a Logic Apps flow for complex responses: calling an external API, asking for approval in a messaging app, disabling an account.

- Prefer the **incident creation** trigger: the incident groups the alerts and offers more actions.
- Rules run in the defined **order**.
- A rule can have an **expiration date**: perfect for a temporary mute during maintenance, which does not become permanent by oversight.

## Watchlists

A watchlist is **reference data** (VIPs, critical assets, known IP ranges) available in KQL with \`_GetWatchlist('alias')\`. The **SearchKey** column optimizes joins. Up to 10 million items, and it is not a telemetry store.

\`\`\`kql
let vip = _GetWatchlist('VIP') | project SearchKey;
SigninLogs
| where UserPrincipalName in (vip)
| where ResultType == "0"
\`\`\`

(This block cannot be run in our playground, which has no watchlist: it illustrates the shape.)

## Two data contexts

In Log Analytics and Sentinel, the time column is \`TimeGenerated\`. In the Defender XDR Advanced Hunting tables, it is \`Timestamp\`. The Defender portal shows both: know which table you are querying.`},"cours-kql-bases":{title:`KQL: read, filter and project`,summary:`The pipe model, where, project, take, sort and ago: the basic moves of every query.`,body:'A KQL query is a **pipe**: a table on the left, operators separated by `|`, each one receiving the result of the previous one.\n\n```kql\nSigninLogs\n| where ResultType != "0"\n| project TimeGenerated, UserPrincipalName, IPAddress, ResultType\n| order by TimeGenerated desc\n| take 10\n```\n\n## The starter operators\n\n- `where` filters. Combine with `and` and `or`. Compare with `==` (not `=`).\n- `project` keeps or creates columns and removes the others.\n- `take N` takes N **arbitrary** rows; for the N most recent or largest, use `top N by column` or `sort` then `take`.\n- `distinct`, `count` and `extend` complete the toolkit.\n\n## Text: `==`, `has`, `contains`\n\n`==` compares exactly. `has` looks for a **whole term** and is faster than `contains`, which looks for any substring. `=~` ignores case.\n\n## Time\n\n`ago(24h)` gives the moment 24 hours before now. In our playground, the clock is simulated at March 12, 2026 at 12:00 UTC. Put the time condition **first**: in Log Analytics it reduces the data read.\n\n## Types: a frequent trap\n\n`ResultType` is a **string** in SigninLogs: write `"0"`, not `0`. In SecurityEvent, `EventID` is an integer.\n\n> Filter first, project after. After a `project`, the columns you did not keep no longer exist.'},"cours-kql-agreger":{title:`KQL: aggregate with summarize`,summary:`count, dcount, countif, min, max, make_set, bin and top: turn events into indicators.`,body:'`summarize` turns many rows into few rows: one per group.\n\n```kql\nSigninLogs\n| where ResultType != "0"\n| summarize Echecs = count(), Comptes = dcount(UserPrincipalName) by IPAddress\n| order by Echecs desc\n```\n\n## Useful aggregations\n\n- `count()`: number of rows; `countif(condition)`: number of rows that meet a condition.\n- `dcount(col)`: **distinct** values. This is what separates a spray (many accounts) from a brute force (one account, many attempts).\n- `min`, `max`, `sum`, `avg`, `percentile(col, 95)`.\n- `make_set(col)`: list of distinct values.\n- `arg_max(TimeGenerated, *)`: the most recent row of each group.\n\n## Group by time\n\n`bin(TimeGenerated, 1h)` rounds a date to the hour. Group on it to get an hourly series.\n\n```kql\nSigninLogs\n| where ResultType != "0"\n| summarize Echecs = count() by Heure = bin(TimeGenerated, 1h)\n| order by Heure asc\n```\n\n## Order matters\n\nFilter **before** summarizing: `summarize` processes fewer rows. Apply a threshold on an aggregate **after** the `summarize` (`where Echecs >= 20`), not before.\n\n> The column name of `count()` without an alias is `count_`; that of the `| count` operator is `Count`.'},"cours-kql-jointures":{title:`KQL: let, join, union and reference lists`,summary:`Reuse intermediate results, link sources and compare the expected to the observed.`,body:`## let: naming a result

\`\`\`kql
let sources = SigninLogs
| where ResultType == "50126"
| summarize Comptes = dcount(UserPrincipalName) by IPAddress
| where Comptes > 10
| project IPAddress;
SigninLogs
| where IPAddress in (sources)
| where ResultType == "0"
| project TimeGenerated, UserPrincipalName, IPAddress
\`\`\`

\`in (name)\` accepts a table with **a single column**. It is the most readable form for "a success from an address that did a spray".

## join: linking two tables

Choose the **type** according to the question:

- \`inner\`: rows that have a match on both sides;
- \`leftanti\`: left rows **without** a match (machines without a heartbeat);
- \`leftouter\`: all the left rows, with or without a match.

Reduce and **aggregate the right side** before joining: a non-unique key multiplies the rows. When the column names differ, write \`on $left.Caller == $right.UserPrincipalName\`.

## union: stacking sources

Align the column names before the \`union\`.

\`\`\`kql
union
  (SecurityEvent | where EventID == 4625 | project Machine = Computer),
  (Syslog | where SyslogMessage has "Failed password" | project Machine = Computer)
| summarize Echecs = count() by Machine
| order by Echecs desc
\`\`\`

## datatable: an inline list

\`datatable(Computer:string)["SRV-DC01", "SRV-FILE01"]\` creates a small reference table. Columns always have a **type**. It is the equivalent of a watchlist, directly in the query.

> Comparing an expected inventory to the observed machines with \`leftanti\` is one of the most worthwhile logging coverage checks.`},"cours-kql-temps":{title:`KQL: time, sequences and correlation`,summary:`Time bounds, gaps with datetime_diff, hourly windows and chains of events.`,body:`Detection is mostly a question of **sequence**: a success after failures, an account creation followed by an addition to a group, silence after activity.

## Gap between two events

\`\`\`kql
let creations = SecurityEvent
| where EventID == 4720
| project Computer, Creation = TimeGenerated;
SecurityEvent
| where EventID == 4732
| project Computer, Ajout = TimeGenerated
| join kind=inner creations on Computer
| extend Minutes = datetime_diff("minute", Ajout, Creation)
| where Minutes between (0 .. 10)
\`\`\`

Two rules: **rename** the time columns on both sides so they do not overwrite each other, and **bound the gap** (here from 0 to 10 minutes) so you do not join distant events. \`datetime_diff(unit, end, start)\`: reversing the dates gives a negative number.

## Hourly windows

A spray is detected within a window: group by address **and** by \`bin(TimeGenerated, 1h)\`, then apply the threshold on distinct accounts. Without a window, failures over several days add up wrongly.

## Compare to the normal

\`toscalar\` turns a single-value result into a scalar. You compute the average in a \`let\`, then keep the hours above three times that average.

## Silent machines

Summarize the last heartbeat per machine **then** filter: filtering before summarizing would make the machines that went quiet disappear.

> In this playground, the clock is fixed (March 12, 2026, 12:00 UTC). In production, \`ago()\` is relative to execution: a scheduled rule must always be bounded in time.`},"cours-kql-contextes":{title:`KQL: Sentinel and Defender XDR, two distinct contexts`,summary:`Tables, time column and usages specific to Log Analytics and to Advanced Hunting.`,body:'The same language serves two platforms, with **different schemas**. Mixing the two is a common mistake.\n\n## Log Analytics and Microsoft Sentinel\n\nTables such as `SigninLogs`, `AuditLogs`, `AzureActivity`, `SecurityEvent`, `Syslog`, `Heartbeat` and `CommonSecurityLog`. Time column: **`TimeGenerated`**.\n\n## Advanced Hunting (Defender XDR)\n\nTables such as `DeviceProcessEvents`, `DeviceNetworkEvents`, `DeviceLogonEvents`, `EmailEvents` and `EmailUrlInfo`. Time column: **`Timestamp`**.\n\n```kql\nDeviceProcessEvents\n| where InitiatingProcessFileName =~ "WINWORD.EXE"\n| where FileName =~ "powershell.exe"\n| project Timestamp, DeviceName, AccountName, ProcessCommandLine\n```\n\n## Practical consequences\n\n- A query that uses `TimeGenerated` on an Advanced Hunting table fails (and vice versa).\n- The Defender portal shows both worlds. Knowing where the table comes from saves you from looking for the wrong column.\n- Sentinel data can be queried from the Defender portal in advanced hunting; the reverse depends on the integration configuration.\n\n> Our playground separates the two contexts: choose the context before writing the query.'},"cours-soc-methode":{title:`SOC investigation method`,summary:`Hypothesis, evidence, correlation, containment and classification: a simple framework for any investigation.`,body:`A good investigation follows the same movement, whatever the alert.

## 1. Qualify

What does the alert say, on which source, with which entity (account, address, machine)? Measure the scale before concluding: how many accounts, how many attempts.

## 2. Look for the success

A spray or brute force **without a success** is noise to watch. A success from the same source is an incident.

\`\`\`kql
SigninLogs
| where IPAddress == "203.0.113.45"
| summarize Echecs = countif(ResultType != "0"), Succes = countif(ResultType == "0")
\`\`\`

## 3. Follow the attacker

Once an account is compromised, follow it: privilege escalations in the directory, service account creations, management operations, deletion of logging, outbound transfers. Link the sources with **the attacker's address** and the **accounts created**.

## 4. Contain without destroying evidence

Reset credentials, revoke sessions, disable the accounts created, isolate machines, block destinations. **Do not delete** the accounts or the workspace: you would lose evidence.

## 5. Distinguish

An impossible travel can be a VPN. An encoded PowerShell launched by a configuration management agent is not an encoded PowerShell launched by Word. **Context** decides; corroborate before concluding.

## 6. Classify and improve

Close with the right classification, then ask which detection would have cut the chain earlier: success after spray, privileged role outside PIM, deletion of a diagnostic setting, growing outbound volume to a rare destination.

> Avoid alerting on every individual failure: the noise drowns the team without helping it.`}},i={"kql-001":{title:`Failed sign-ins`,objective:`Filter a table with where on an exact value.`,statement:'In `SigninLogs`, the `ResultType` column is `"0"` for a successful sign-in. Write a query that returns **all rows** whose sign-in failed, that is, whose `ResultType` is not `"0"`.',hints:['The "not equal to" operator is written `!=`.',`ResultType is a string: put the value in quotes.`],explanation:'`where` keeps the rows for which the expression is true. `ResultType` is text, so `"0"` is written with quotes. `!=` excludes the successful sign-ins.',commonMistakes:["Using `=` instead of `==` or `!=`.","Writing `ResultType != 0` without quotes while the column is text."]},"kql-002":{title:`How many sign-ins per account?`,objective:`Count rows per group with summarize count() by.`,statement:"Return the number of sign-ins (successful or not) **per account** (`UserPrincipalName`). Name the count column `Total`.",hints:["`summarize` groups the rows with `by`.","`Total = count()` names the column."],explanation:"`summarize Total = count() by UserPrincipalName` produces one row per account with the number of rows in that group.",commonMistakes:["Forgetting `by`: the result becomes a single row.","Naming the column something other than `Total`: the comparison is on column names."]},"kql-003":{title:`The three most targeted accounts`,objective:`Combine filter, aggregation and top.`,statement:'Among the **failed sign-ins** (`ResultType` different from `"0"`), find the 3 accounts with the most failures. Expected columns: `UserPrincipalName` and `Echecs`. The result must be sorted from the highest to the lowest number of failures.',hints:["Filter first with `where`, then count.","`top 3 by Echecs desc` sorts and limits in a single step."],explanation:"Filtering early reduces the work of `summarize`. `top N by column desc` returns the N largest values, already sorted.",commonMistakes:["Using `take 5`: it does not sort.",`Counting all the sign-ins instead of only the failures.`],check:{rules:[{message:"Filter before summarizing: `summarize` then processes fewer rows."}]}},"kql-004":{title:`Distinct IP addresses`,objective:`Count distinct values with dcount.`,statement:"How many **distinct** IP addresses (`IPAddress`) appear in `SigninLogs`? Return a single row with a column `IPDistinctes`.",hints:["`dcount()` counts distinct values.","No `by`: we want a single total."],explanation:"`dcount` is an estimate in real KQL for large volumes. In this local engine, the calculation is exact.",commonMistakes:["Using `count()`: it counts rows, not distinct values."]},"kql-005":{title:`Last 24 hours`,objective:`Filter on a time window with ago().`,statement:"Return the failed sign-ins from the **last 24 hours** (`TimeGenerated`). The playground clock is simulated at 2026-03-12 12:00 UTC.",hints:["`ago(24h)` gives the moment 24 hours before now.","Filter on the `TimeGenerated` column."],explanation:`Putting the time condition first is a good habit: in Log Analytics, it reduces the data read.`,commonMistakes:[`Writing a fixed date: the query no longer applies to new data.`],check:{rules:[{message:"Use a relative time window (`ago`) rather than hard-coded dates."}]}},"kql-006":{title:`A Heartbeat sample`,objective:`Take a few rows with take to discover a table.`,statement:"You are discovering the `Heartbeat` table. Return **10 arbitrary rows** to see what it looks like.",hints:["`take` (or its synonym `limit`) takes a number of rows.",`No sorting is requested: the rows returned can be any rows.`],explanation:"`take 10` returns 10 rows, but **with no guarantee of order**. It is perfect for exploring the schema, not for a detection rule: for reproducible results, you need to sort before limiting.",commonMistakes:["Using `take` thinking you get the most recent rows: that is not the case without `sort`.","Forgetting the number: `take` requires a value."]},"kql-007":{title:`Keep only four columns`,objective:`Reduce the result to the useful columns with project.`,statement:"In `SigninLogs`, return only the columns `TimeGenerated`, `UserPrincipalName`, `IPAddress` and `ResultType` for **all** the rows.",hints:["`project` lists the columns to keep.",`Column names are separated by commas.`],explanation:"`project` chooses (and orders) the columns of the result. Reducing columns early makes the query more readable and lightens the transfer of results.",commonMistakes:["Using `project-away` while listing the columns to keep: that operator removes what you give it.",`Forgetting a comma between two column names.`]},"kql-008":{title:`Failed logons on the file server`,objective:`Combine two conditions with and.`,statement:"In `SecurityEvent`, return the **4625** events (Windows logon failure) that occurred on the **SRV-FILE01** computer.",hints:["`EventID` is an integer: no quotes.","Two conditions combine with `and`, or with two chained `where`."],explanation:'Both conditions must be true. `EventID` is numeric (`== 4625`), `Computer` is text (`== "SRV-FILE01"`). Two successive `where` give exactly the same result.',commonMistakes:["Putting `4625` in quotes: the text/number comparison is useless and misleading.","Writing the machine name in lowercase with `==`: the comparison is case-sensitive."]},"kql-009":{title:`Count the Windows failures`,objective:`Count the filtered rows and name the column.`,statement:"How many **4625** events does `SecurityEvent` contain in total? Return a single row with a column named `Echecs`.",hints:["`summarize` without `by` produces a single row.","`Echecs = count()` names the output column."],explanation:"A `summarize` without a `by` clause aggregates all the rows into one. The filter comes **before** so that only the 4625 events are counted.",commonMistakes:["Using `| count`: the column is then called `Count`, not `Echecs`.","Filtering after the `summarize`: the `EventID` column no longer exists."]},"kql-010":{title:`Which applications are used?`,objective:`List the distinct values of a column.`,statement:"List the **distinct values** of `AppDisplayName` in `SigninLogs`.",hints:[`There is an operator dedicated to unique values.`,`A single column is enough.`],explanation:"`distinct` returns the unique combinations of the given columns. It is the compact equivalent of `summarize by AppDisplayName`.",commonMistakes:["Doing a `count()` when you want the list, not the number.","Forgetting that `distinct *` deduplicates whole rows, rarely useful."]},"kql-011":{title:`The five latest sign-ins`,objective:`Get the most recent rows with top.`,statement:"Return the timestamps (`TimeGenerated` only) of the **5 most recent sign-ins** in `SigninLogs`, from most recent to oldest.",hints:["`top N by column desc` sorts then limits in one step.","End with a `project` to keep only the timestamp."],explanation:"`top 5 by TimeGenerated desc` is equivalent to `sort by TimeGenerated desc | take 5`. A `take` placed **before** the sort would give 5 arbitrary rows.",commonMistakes:["Writing `take 5` then `sort`: the 5 rows are chosen before the sort.","Forgetting `desc`: by default, `top` sorts in descending order, but it is better to write it explicitly."]},"kql-012":{title:`Flag server events`,objective:`Create a computed column with extend.`,statement:"For Windows successful logons (`EventID` 4624), add a boolean column `EstServeur` that is true if `Computer` **starts with** `SRV-`. Return `TimeGenerated`, `Computer` and `EstServeur`.",hints:["`extend` adds columns without removing the others.","`startswith` returns a boolean."],explanation:"`extend` computes a new column row by row. The final `project` sets the requested columns and their order.",commonMistakes:["Using `project` instead of `extend`: the columns not listed disappear.",'Using `contains`: "contains" is not "starts with".']},"kql-013":{title:`Refused SSH passwords`,objective:`Search for a term with the has operator.`,statement:"In `Syslog`, return the rows whose `SyslogMessage` contains the term **Failed password**.",hints:["`has` looks for a whole term and runs fast.","`has` is not case-sensitive."],explanation:'`has` searches for an indexed **term** and is more efficient than `contains` (substring). The term "Failed password" is found even when surrounded by other words.',commonMistakes:["Using `==`: the full message also contains the user and the address.","Using `contains`: the result is correct but more expensive on large volumes."]},"kql-014":{title:`Workstations that send a heartbeat`,objective:`Filter on a prefix then deduplicate.`,statement:"List the **distinct** computer names in `Heartbeat` that start with `PC-`.",hints:["Filter first with `startswith`.","Then deduplicate with `distinct`."],explanation:"Each machine emits a regular heartbeat: without `distinct`, you would get thousands of rows. Filtering before deduplicating reduces the work.",commonMistakes:["Forgetting `distinct`: the list contains one row per beat.",'Using `has "PC-"`: the hyphen changes how the term is split.']},"kql-015":{title:`Account creations and additions to a local group`,objective:`Test several values with in.`,statement:"Return the `SecurityEvent` events whose `EventID` is **4720** (account created) **or** **4732** (member added to a local security group).",hints:["Rather than two conditions joined by `or`, use `in`.",`The list of values goes in parentheses.`],explanation:"`in (a, b)` is the compact form of `== a or == b`. It reads better as the list grows.",commonMistakes:["Writing `EventID == 4720 or 4732`: the second part is not a comparison.","Using `and`: an event cannot have two identifiers."]},"kql-016":{title:`Ignore the noise of invalid passwords`,objective:`Exclude values with !in.`,statement:'In `SigninLogs`, return the sign-ins whose `ResultType` is **neither** `"0"` (success) **nor** `"50126"` (invalid password). These are the "unusual" failures that deserve a second look.',hints:["`!in` excludes a list of values.","`ResultType` is text."],explanation:"`!in` is the negation of `in`. Excluding the known noise brings out the rarer error codes, such as 50074 (strong authentication required) or 50053 (account locked).",commonMistakes:["Using `!=` with two values: a condition that is true for one and false for the other filters nothing.",`Writing the codes without quotes while the column is text.`]},"kql-017":{title:`Windows failures from the last 24 hours`,objective:`Bound a query in time with ago().`,statement:"Return the **4625** events from `SecurityEvent` for the **last 24 hours** (relative to the simulated playground clock).",hints:['`ago(24h)` returns the moment 24 hours before "now".',"Compare `TimeGenerated` to that result."],explanation:"Filtering time first is the right habit: on a real workspace, the time range first reduces the amount of data read. `ago(1d)` and `ago(24h)` are equivalent.",commonMistakes:[`Forgetting the time filter: the query reads the entire retention.`,"Using `<` instead of `>`: you would get everything except the last day."],check:{rules:[{message:`A detection query must always be bounded in time with TimeGenerated.`}]}},"kql-018":{title:`Failed Azure operations, from oldest to most recent`,objective:`Sort in ascending order.`,statement:'In `AzureActivity`, return the timestamp (`TimeGenerated` only) of the operations whose `ActivityStatusValue` is `"Failed"`, **from oldest to most recent**.',hints:["`sort by` sorts in descending order by default.","Add `asc` for ascending order."],explanation:"The default order of `sort` is **descending**. For chronological order, you must write `asc` explicitly.",commonMistakes:["Forgetting `asc`: the sort is descending.",`Sorting before filtering: the result is correct, but you sort useless rows.`]},"kql-019":{title:`First and last recorded sign-in`,objective:`Use min() and max() in the same summarize.`,statement:"Return, in a single row, the oldest (`Premiere`) and the most recent (`Derniere`) value of `TimeGenerated` in `SigninLogs`.",hints:["`min()` and `max()` also work on dates.",`Several aggregates are separated by commas.`],explanation:"A single `summarize` can compute several aggregates. Knowing the range covered by a table is the first reflex before interpreting a result.",commonMistakes:[`Running two separate queries rather than a single summarize.`,"Using `sort` + `take 1`: longer and less readable."]},"kql-020":{title:`Failures and total in one pass`,objective:`Use countif() to count according to a condition.`,statement:'In a single row, return the number of failed sign-ins (`Echecs`, `ResultType` different from `"0"`) and the total number of sign-ins (`Total`).',hints:["`countif(condition)` counts the rows where the condition is true.","Do not filter with `where`: you would lose the total."],explanation:"`countif` avoids running two queries: the same pass over the data computes the total and the subset. It is the basis of a failure rate.",commonMistakes:["Using `where` before the `summarize`: the total becomes equal to the number of failures.",`Forgetting that the result must contain a single row.`]},"kql-021":{title:`How many distinct accounts targeted per machine?`,objective:`Count unique values with dcount() per group.`,statement:"Among the 4625 failures in `SecurityEvent`, compute for each `Computer` the number of distinct accounts targeted (`Comptes`, from `Account`).",hints:["`dcount(column)` counts distinct values.","Group by computer with `by Computer`."],explanation:`Many accounts targeted from the same machine or the same source is the signature of a **password spray**, unlike a brute force that targets a single account.`,commonMistakes:["Using `count()`: you count events, not accounts.",`Forgetting the filter on 4625: the successful logons skew the number.`]},"kql-022":{title:`Sign-ins per day`,objective:`Group by time interval with bin().`,statement:"Return the number of sign-ins (`Total`) per **day** (`Jour`) in `SigninLogs`.",hints:["`bin(TimeGenerated, 1d)` rounds each timestamp to the start of its day.","The result of `bin` can be named directly in the `by`."],explanation:"`bin()` (or `floor()`) creates regular time buckets. It is the basis of any time series, including `render timechart` charts.",commonMistakes:["Grouping by raw `TimeGenerated`: each row becomes its own group.","Using `1h` instead of `1d`: the result would be hourly."]},"kql-023":{title:`Outbound volume by source address`,objective:`Add up a numeric column with sum().`,statement:"In `CommonSecurityLog`, compute for each `SourceIP` the sum of `SentBytes` in a column `OctetsEnvoyes`.",hints:["`sum()` adds up the values of a column.",`Group by source address.`],explanation:`Adding up bytes per source is the basis of exfiltration detection: a machine that sends abnormally more than its peers stands out immediately.`,commonMistakes:["Using `count()`: you count flows, not bytes.","Confusing `SentBytes` and `ReceivedBytes`."]},"kql-024":{title:`Remove the bulky columns`,objective:`Remove columns with project-away.`,statement:"Return all the rows of `SigninLogs` **without** the columns `UserAgent`, `DeviceDetail` and `LocationDetails`.",hints:["There is a variant of `project` that removes rather than keeps.",`List only the columns to remove.`],explanation:"`project-away` is handy when you want to keep everything except a few columns. Listing 10 columns to keep would be longer and more fragile.",commonMistakes:["Using `project`: you would keep only the three columns to remove.","Forgetting the hyphen in `project-away`."]},"kql-025":{title:`Fix: equality with a single sign`,objective:`Recognize the most frequent syntax error of the where operator.`,statement:`This query should return the **successful** sign-ins, but it fails. Fix it.`,hints:[`Read the error message carefully.`,`In KQL, comparison is done with a two-character operator.`],explanation:"The `=` sign alone is used for assignment (`extend X = ...`). Equality comparison is written `==`.",commonMistakes:["Replacing `=` with `=~`: that operator compares without regard to case and is slower.",'Removing the quotes around `"0"`.']},"kql-026":{title:`Fix: filter after the aggregation`,objective:`Understand that summarize replaces the available columns.`,statement:'We want the number of failures (`ResultType` different from `"0"`) per account, but the query reports a column not found. Fix it while keeping the columns `UserPrincipalName` and `Echecs`.',hints:["After a `summarize`, only the `by` columns and the aggregates remain.","Move the filter to where `ResultType` still exists."],explanation:"`summarize` produces a new table: only the grouping columns and the aggregates survive. The filter on `ResultType` must come **before**, which is also faster.",commonMistakes:["Adding `ResultType` to the `by`: the result changes completely.","Using `countif` but keeping the final `where`."]},"kql-027":{title:`Fix: string without quotes`,objective:`Wrap text literals in quotes.`,statement:"We are looking for the sign-ins of the account `l.bouchard@nordlys.example`. The query fails. Fix it.",hints:[`Without quotes, KQL reads a column name.`,`A text literal goes in double or single quotes.`],explanation:"Without quotes, `l.bouchard@nordlys.example` is not a text literal. Always wrap values in quotes.",commonMistakes:["Using `has` without quotes.",`Putting quotes around the column name rather than the value.`]},"kql-028":{title:`Assemble: the noisiest addresses`,objective:`Put the clauses back in the right order: filter, aggregate, rank.`,statement:"Assemble the blocks to get the **3 IP addresses** (`IPAddress`) with the most sign-in failures (`Echecs`). One block is not part of the solution.",hints:[`Every query starts with its data source.`,`The filter comes before the aggregation, and the ranking comes last.`],explanation:"Filter → aggregate → rank. The `take 3` block would limit arbitrary rows instead of keeping the three highest values.",commonMistakes:["Placing `top` before `summarize`: the `Echecs` column does not exist yet.","Using `take 3` instead of `top 3`."]},"kql-029":{title:`Read a result: the most targeted machine`,objective:`Interpret a result table without rewriting the query.`,statement:`This query counts Windows failures per computer. Read the result.`,hints:[`The rows are already sorted from the highest value to the lowest.`,`Look at the first row.`],explanation:"SRV-FILE01 clearly dominates. A value this high on a single server is typical of an RDP brute-force attack, to be confirmed with the source (`IpAddress`) and a possible 4624 success that follows.",commonMistakes:[`Reading the last row rather than the first.`,`Answering with the number of failures rather than the name.`],question:`Which computer suffered the most logon failures?`},"kql-030":{title:`Read a result: how many distinct accounts?`,objective:`Read a number in a single-row table.`,statement:`This query measures the extent of a suspicious source.`,hints:[`The result fits on one row.`,"The `Comptes` column contains the value of `dcount`."],explanation:"Several accounts targeted by the same address with few attempts per account is the signature of a password spray. Do not confuse it with `Tentatives`, which counts all the rows.",commonMistakes:["Answering with `Tentatives`, which is the number of rows.","Counting the accounts by hand rather than reading `Comptes`."],question:`How many distinct accounts did the address 203.0.113.45 target?`},"kql-031":{title:`Classify the result codes`,objective:`Turn a code into a readable category with case().`,statement:'For each row of `SigninLogs`, add a column `Categorie` with the value:\n\n- `"Succes"` if `ResultType` is `"0"`\n- `"MotDePasse"` if `"50126"`\n- `"MFA"` if `"50074"`\n- `"Autre"` for everything else\n\nReturn `UserPrincipalName`, `ResultType` and `Categorie`.',hints:["`case(condition1, value1, condition2, value2, ..., defaultValue)`.",`The last value, without a condition, serves as the default.`],explanation:"`case()` evaluates its conditions in order and returns the first value whose condition is true. The last odd argument is the default value. `iff()` is enough for only two outcomes.",commonMistakes:["Forgetting the final default value: `case` requires an odd number of arguments.","Chaining unreadable nested `iff` when `case` fits."]},"kql-032":{title:`Sign-ins by country`,objective:`Read a property of a dynamic column.`,statement:"The `LocationDetails` column is of type `dynamic` and contains a property `countryOrRegion`. Return the number of sign-ins (`Total`) per country (`Pays`).",hints:["A property of a dynamic object is reached with a dot: `LocationDetails.countryOrRegion`.","Convert the value with `tostring()` before grouping."],explanation:"`dynamic` values are untyped: convert explicitly with `tostring()`, `toint()`, etc. before comparing or grouping, otherwise the behavior is unpredictable.",commonMistakes:["Forgetting `tostring()`: the grouping is on an untyped value.",'Writing `LocationDetails["countryOrRegion"` without closing the bracket.']},"kql-033":{title:`Device operating systems`,objective:`Use bracket notation on a dynamic object.`,statement:"For **successful** sign-ins, return the number of distinct devices (`Appareils`, from `UserPrincipalName`) per operating system (`OS`, property `operatingSystem` of `DeviceDetail`). Use bracket notation for the property.",hints:['`DeviceDetail["operatingSystem"]` is equivalent to `DeviceDetail.operatingSystem`.',`Filter the successes first, then aggregate.`],explanation:`Brackets are essential when the property name contains special characters or comes from a variable. Here the two notations are equivalent.`,commonMistakes:[`Using parentheses instead of brackets.`,`Forgetting to filter the successes.`]},"kql-034":{title:`The latest sign-in of each account`,objective:`Retrieve the most recent row per group with arg_max().`,statement:"For each `UserPrincipalName`, return the row of its **most recent sign-in** with the columns `UserPrincipalName`, `TimeGenerated` and `IPAddress`.",hints:["`arg_max(sortColumn, columnsToReturn)` returns the values of the maximum row.","Grouping is done with `by`."],explanation:"`arg_max(TimeGenerated, IPAddress)` returns `TimeGenerated` (the maximum value) and `IPAddress` from **the same row**. Doing `max(TimeGenerated)` and `max(IPAddress)` separately would mix different rows.",commonMistakes:["Computing two independent `max()`: the IP address no longer matches the last sign-in.","Using `top 1`: it does not apply per group."]},"kql-035":{title:`How many IP addresses per account?`,objective:`Collect values with make_set() and measure the size of the result.`,statement:"For each account in `SigninLogs`, compute the number of **distinct** IP addresses (`NbIP`) using `make_set()` and `array_length()`.",hints:["`make_set()` returns an array of distinct values.","`array_length()` gives the size of the array."],explanation:"`make_set` produces an array of distinct values whose **order is not guaranteed**: you must never compare two arrays by their order, but rather by their size or sorted content. For a simple count, `dcount` is enough.",commonMistakes:["Using `make_list`: duplicates are kept.",`Assuming a stable order of the array elements.`]},"kql-036":{title:`A reusable threshold with let`,objective:`Declare a constant with let and use it in a filter.`,statement:"Declare `seuil = 10` with `let`, then return the IP addresses (`IPAddress`) with **more than `seuil` sign-in failures** (`Echecs`).",hints:["A `let` statement ends with a semicolon.","The filter on `Echecs` comes after the `summarize`."],explanation:"Isolating thresholds in `let` at the top of the query makes them easy to adjust in an analytics rule. The filter on the aggregate is done **after** `summarize`, because the column does not exist before.",commonMistakes:["Forgetting the semicolon after the `let`.","Placing `where Echecs > seuil` before the `summarize`."]},"kql-037":{title:`A named subquery`,objective:`Name a tabular expression with let.`,statement:"Define `echecs` as the failed sign-ins of `SigninLogs`, then return the number of failures (`Total`) per country (`Pays`, property `countryOrRegion` of `LocationDetails`).",hints:["`let name = <query>;` defines a reusable expression.","Then use `name` as the data source."],explanation:"A tabular `let` makes the query more readable and lets you reuse the same subquery several times. It is evaluated at each use, unless you use `materialize()`.",commonMistakes:["Leaving a blank line inside the `let` statement.",`Forgetting the semicolon after the definition.`]},"kql-038":{title:`Last heartbeat of the attacked servers`,objective:`Join two summaries with join kind=inner.`,statement:"For each `Computer` with 4625 failures in `SecurityEvent`, return `Computer`, the number of failures (`Echecs`) and the date of the last heartbeat (`Dernier`, from `Heartbeat`).",hints:[`Summarize each side **before** the join to reduce the volume.`,"The join key is `Computer`, present on both sides."],explanation:"Putting the smaller table on the left and reducing each side before joining is the golden rule of performance. The `inner` type keeps only the machines present on both sides.",commonMistakes:[`Joining the raw tables: thousands of rows multiply needlessly.`,"Forgetting that `join` without `kind` is `innerunique`, which deduplicates the left side."]},"kql-039":{title:`Machines with no 4625 failure`,objective:`Find the absence with join kind=leftanti.`,statement:"List the computers (`Computer`) that send heartbeats but that **never** have a 4625 event in `SecurityEvent`.",hints:["`leftanti` returns the left rows without a match on the right.",`Deduplicate each side before the join.`],explanation:'`leftanti` answers the question "who is in A but not in B?". It is the basic pattern for detecting absences: silent machines, accounts without MFA, etc.',commonMistakes:["Using `rightanti`: the sides are reversed.","Using `kind=leftouter` then forgetting to filter the null values."]},"kql-040":{title:`A single table of failures`,objective:`Combine tables with different schemas using union.`,statement:'Combine into a single table:\n\n- the failed sign-ins of `SigninLogs` (columns `TimeGenerated`, `Compte` = `UserPrincipalName`, `Source` = `"SigninLogs"`)\n- the 4625 events of `SecurityEvent` (columns `TimeGenerated`, `Compte` = `Account`, `Source` = `"SecurityEvent"`)',hints:["First harmonize the columns of each table with `project`.","`union (query1), (query2)` stacks the results."],explanation:"`union` stacks rows. By harmonizing the columns beforehand, the result is usable for a unified view of identities coming from different sources.",commonMistakes:[`Forgetting the parentheses around each subquery.`,"Confusing `union` (stacks) and `join` (associates)."]},"kql-041":{title:`Who received a role?`,objective:`Expand a dynamic array with mv-expand.`,statement:'In `AuditLogs`, for the operation `"Add member to role"`, the `TargetResources` column is an array. Return `TimeGenerated` and the targeted account (`Cible`, property `userPrincipalName` of each element).',hints:["`mv-expand` creates one row per element of the array.","Name the expanded element, for example `t = TargetResources`."],explanation:"`mv-expand` turns an array into several rows. An empty array gives **zero** rows; a null value gives one. Audit logs use many arrays in `TargetResources`.",commonMistakes:["Forgetting `mv-expand`: a property of an array is not directly accessible.","Using `t[0]`: only the first element is read."]},"kql-042":{title:`Extract the Windows user name`,objective:`Split a string with split().`,statement:"The `Account` column of `SecurityEvent` contains `DOMAINE\\utilisateur`. For successful logons (4624), return the number of events (`Total`) per user (`Utilisateur`, without the domain).",hints:["`split(text, separator)` returns an array.",`The separator is a backslash, which is written doubled in a string.`],explanation:'In a KQL text literal, the backslash is an escape character: to get one backslash, you write `"\\\\"`. With a verbatim string `@"\\"`, the backslash is literal.',commonMistakes:['Writing `"\\"`: the backslash escapes the following quote.',"Indexing `[0]`: you get the domain."]},"kql-043":{title:`Build an account@machine key`,objective:`Assemble strings with strcat().`,statement:'For the 4625 events, add a column `Cle` equal to `Account` followed by `" sur "` then `Computer` (e.g. `NORDLYS\\sam sur PC-001`), then return the **distinct** values of `Cle`.',hints:["`strcat(a, b, c)` concatenates several values.","End with `distinct`."],explanation:"`strcat` concatenates text and converted values. Building a composite key is useful for detecting rare combinations, for example an account that signs in on an unusual machine.",commonMistakes:["Using `+`: it adds numbers, it does not concatenate text.",`Forgetting the spaces around the joining word.`]},"kql-044":{title:`Successes in the middle of the night`,objective:`Filter on the hour of the day with hourofday().`,statement:"Return the **successful** sign-ins of `SigninLogs` that occurred between 0:00 and 5:00 (UTC), that is, those where `hourofday(TimeGenerated)` is less than 5.",hints:["`hourofday()` returns an integer from 0 to 23.",`Timestamps are in UTC.`],explanation:`Hours are in **UTC**: a "night" range must be shifted according to the organization's time zone. A successful sign-in in the middle of the night, especially after failures, deserves a check.`,commonMistakes:[`Forgetting that the logs are in UTC.`,"Using `dayofweek` instead of `hourofday`."]},"kql-045":{title:`Accounts with several IP addresses`,objective:`Filter on the result of a dcount.`,statement:"Return the accounts (`UserPrincipalName`) that signed in from **more than 3** distinct IP addresses (`NbIP`).",hints:["Compute `dcount` per account.",`Then filter on the resulting column.`],explanation:`An unusual number of addresses per account can signal a stolen token or account sharing. You then need to compare to a normal baseline (remote work, mobile) before alerting.`,commonMistakes:["Filtering before the `summarize`.",'Comparing with `>=` when the statement says "more than".']},"kql-046":{title:`The biggest outbound flows`,objective:`Rank destinations by volume.`,statement:"In `CommonSecurityLog`, return the 3 destinations (`DestinationIP`) that received the largest single flow (`Max`, maximum of `SentBytes`), from largest to smallest.",hints:[`First compute the maximum per destination.`,"Then rank with `top`."],explanation:`A single flow of several tens of MB to an unusual address is an exfiltration signal to investigate. The ranking must be done after the aggregation.`,commonMistakes:["Doing `top 3 by SentBytes` without aggregating: several flows from the same destination.","Using `sum`: the statement asks for the largest single flow."]},"kql-047":{title:`Blocked messages`,objective:`Query a Defender XDR table (Advanced Hunting).`,statement:'In Advanced Hunting, the `EmailEvents` table describes emails. Return the **blocked** emails (`DeliveryAction` equal to `"Blocked"`) with the columns `Timestamp`, `SenderFromDomain` and `Subject`.',hints:["In Advanced Hunting, the time column is called `Timestamp`.","Filter on `DeliveryAction`."],explanation:"In the Defender portal, XDR tables use `Timestamp`, whereas Log Analytics tables use `TimeGenerated`. This difference is the first source of errors when transposing a query from one context to the other.",commonMistakes:["Using `TimeGenerated` in Advanced Hunting.",'Looking for `DeliveryAction == "Block"`: the exact value is `Blocked`.']},"kql-049":{title:`Fix: TimeGenerated in Advanced Hunting`,objective:`Adapt a Sentinel query to the Advanced Hunting schema.`,statement:'This query, written for Sentinel, is pasted into Advanced Hunting. It should return the failed logons (`ActionType` equal to `"LogonFailed"`) of the last day. Fix it.',hints:[`What is the name of the time column in XDR tables?`,`Only one column name changes.`],explanation:"Advanced Hunting tables expose `Timestamp`. When the same tables are streamed to Log Analytics, the column becomes `TimeGenerated`, sometimes with both present: check according to the context.",commonMistakes:["Replacing `TimeGenerated` with `Time` or `Date`.",`Removing the time filter.`]},"kql-050":{title:`Fix: join on the wrong key`,objective:`Fix a join whose keys have different names.`,statement:"We want to associate each blocked message with its URLs, but the query fails. `EmailUrlInfo` shares `NetworkMessageId` with `EmailEvents`. Return `Timestamp`, `SenderFromDomain` and `Url`.",hints:[`Which column is common to both tables?`,`The join key must exist on both sides.`],explanation:"A join key must have the same name on both sides; otherwise use `$left.A == $right.B`. Note: `Timestamp` exists in both tables, which creates a column renamed to `Timestamp1` for the right side.",commonMistakes:["Inventing a `MessageId` column.",`Forgetting that homonymous columns are renamed by the join.`]},"kql-051":{title:`Assemble: detect a password spray`,objective:`Compose a spray detection: many accounts, few attempts per account.`,statement:"Assemble the query that returns the IP addresses (`IPAddress`) that failed on **more than 10 distinct accounts** (`Comptes`). Two blocks are decoys.",hints:[`You need to count **distinct** accounts.`,`The threshold is applied after the aggregation.`],explanation:"A spray is recognized by the **diversity of accounts** targeted by the same source, not by the raw number of attempts. `count()` would count attempts and confuse spray with brute force.",commonMistakes:["Using `count()` instead of `dcount()`.",`Placing the threshold before the aggregation.`]},"kql-052":{title:`Read a result: brute force or spray?`,objective:`Interpret figures to qualify a behavior.`,statement:`This query summarizes two suspicious sources. Compare the profiles.`,hints:["Find the row where `IPAddress` is 203.0.113.77.","Read the `Comptes` column."],explanation:`A single account targeted many times: this is a targeted **brute force**. The other address targets several accounts a few times each: this is a **spray**. The two call for different responses (locking the account vs blocking the source).`,commonMistakes:["Reading `Tentatives` instead of `Comptes`.",`Mixing up the two rows.`],question:`How many distinct accounts did the address **203.0.113.77** target?`},"kql-053":{title:`Success after a spray`,objective:`Reuse an intermediate result in an in filter.`,statement:'Define `sources` as the IP addresses (`IPAddress`) that failed with code `"50126"` on **more than 10 distinct accounts**. Then return the **successful** sign-ins (`ResultType == "0"`) coming from these addresses, with `TimeGenerated`, `UserPrincipalName` and `IPAddress`.',hints:["`in (letName)` accepts a table with a single column.","End the `let` with `project IPAddress` to keep only one column."],explanation:`This is the core of a compromise detection: a **success** that follows a spray means a password was guessed. The query links two observations (spray, then success from the same source) without an expensive join.`,commonMistakes:["Forgetting `project IPAddress`: `in` requires a single column.",`Looking for successes without linking the source to the spray: you would retrieve all the successful sign-ins.`]},"kql-054":{title:`RDP brute force followed by a success`,objective:`Link Windows failures and successes by machine and source address.`,statement:"In `SecurityEvent`, find the successful logons (**4624**) coming from an address (`IpAddress`) that already had **at least 20 failures** (4625) on the same machine (`Computer`), and that occurred **after** the last failure. Return `TimeGenerated`, `Computer`, `Account`, `IpAddress` and `NbEchecs`.",hints:[`First compute, per machine and address, the number of failures and the date of the last one.`,`Join the successes on **both** keys, then compare the dates.`],explanation:"Comparing the date of the success with the last failure avoids the false positives of a success that predates the attack. The double key (`Computer`, `IpAddress`) precisely isolates the attacker/target pair.",commonMistakes:[`Joining on a single key: different attacks get mixed.`,`Forgetting the date comparison: an old success would be included.`]},"kql-055":{title:`Accounts seen in several countries`,objective:`Detect a potential impossible travel with dcount on a dynamic field.`,statement:"Among the **successful** sign-ins, return the accounts (`UserPrincipalName`) seen in **more than one country** (`NbPays`, from `LocationDetails.countryOrRegion`).",hints:["Extract the country into a column with `extend` before counting.",`Keep only the successes.`],explanation:`This test does not prove an impossible travel: you must also compare the **times** of the sign-ins. But it is the first quick filter, to be followed by an analysis of distance and delay.`,commonMistakes:[`Including the failures: foreign attackers would skew the list.`,"Counting the rows with `count()` instead of distinct countries."]},"kql-056":{title:`Peak hours of failures`,objective:`Detect an hourly spike.`,statement:"Return the hours (`Heure`, by one-hour `bin`) in which there were **more than 20 sign-in failures** (`Echecs`) in `SigninLogs`.",hints:[`Group by one-hour bucket.`,`Filter on the aggregated result.`],explanation:`Hourly spikes reveal a one-off attack drowned in the daily noise. The threshold must be calibrated on the organization's normal baseline.`,commonMistakes:[`Grouping by day: the spike disappears into the day.`,"Filtering the threshold before the `summarize`."]},"kql-057":{title:`New addresses in the last two days`,objective:`Detect a first appearance with min() and ago().`,statement:"Return the IP addresses (`IPAddress`) whose **first appearance** (`Premiere`) in `SigninLogs` is less than 2 days old, with their number of rows (`Total`).",hints:[`Compute the first appearance per address.`,"Compare it to `ago(2d)`."],explanation:`The "first appearance" is a classic detection pattern (new element): it requires comparing against a history. Note that a short retention makes simply old addresses look new.`,commonMistakes:["Filtering `TimeGenerated > ago(2d)` before `min`: every recently active address looks new.",`Confusing first and last appearance.`]},"kql-058":{title:`Success from a never-before-seen address`,objective:`Compare a recent window with a history using leftanti.`,statement:"Define `connues` as the IP addresses seen **before** the last 2 days. Then return the distinct addresses (`IPAddress`) that had a **successful** sign-in in the last 2 days and that do not appear in `connues`.",hints:[`Separate the history and the recent window with two time filters.`,"`leftanti` keeps what has no match in `connues`."],explanation:`This structure (history, window, anti-join) is the basis of many "new element" rules. It requires a history window long enough not to trigger at every data rotation.`,commonMistakes:["Using `inner`: you keep the already known addresses.",`Overlapping the two time windows.`]},"kql-059":{title:`Duration of an attack per address`,objective:`Measure a duration with datetime_diff().`,statement:'For the failed sign-ins, compute per IP address: the number of attempts (`Tentatives`), the start (`Debut`) and the end (`Fin`), then the duration in minutes (`DureeMin`, with `datetime_diff("minute", Fin, Debut)`). Keep only the addresses with more than 10 attempts.',hints:["First aggregate `min` and `max` of `TimeGenerated`.",'`datetime_diff("minute", end, start)` returns an integer.'],explanation:`Duration and rate distinguish a slow attack from a burst. A slow spray (one attempt every few minutes) escapes a per-minute threshold but not an analysis over several hours.`,commonMistakes:["Reversing `Fin` and `Debut`: the duration becomes negative.","Using `Fin - Debut` without conversion: the result is a duration, not a number of minutes."]},"kql-060":{title:`Which roles were assigned?`,objective:`Extract a nested value from a JSON string.`,statement:'In `AuditLogs`, for the operation `"Add member to role"`, each element of `TargetResources` has `modifiedProperties[0].newValue`, which is a **JSON text** containing an array (e.g. `["Global Administrator"]`). Return `TimeGenerated`, `Cible` (`userPrincipalName`) and `Role` (the first element of the array).',hints:["Expand `TargetResources` with `mv-expand`.","`parse_json(tostring(...))` turns the JSON text into an array."],explanation:"Audit logs often store values as **JSON strings**. You must first convert them to `string`, then parse them with `parse_json`, before you can index.",commonMistakes:["Indexing the JSON text directly without `parse_json`.","Forgetting the `mv-expand`: `t.userPrincipalName` is then not found."]},"kql-061":{title:`What the created account did in Azure`,objective:`Link an identity event to resource activity.`,statement:'In `AuditLogs`, the `"Add user"` operation creates an account (`TargetResources[0].userPrincipalName`). Return the Azure operations (`AzureActivity`) performed by these accounts: `Compte`, `Cree` (creation date), `TimeGenerated`, `OperationNameValue`.',hints:["The keys have different names: use `$left.` and `$right.`.",`Extract the created account into a column before the join.`],explanation:`An account created at 3:12 AM that acts on production VMs at 3:40 AM is a persistence scenario. Linking identity and cloud activity is the essence of investigation in an Azure environment.`,commonMistakes:[`Joining on the display name rather than on the UPN.`,"Forgetting that `AzureActivity.Caller` contains the UPN for a user."]},"kql-062":{title:`What is svc-backup2 doing?`,objective:`Summarize an account's activity across Azure operations.`,statement:"For the account whose `Caller` contains `svc-backup2`, return the number of operations (`Nb`) per `OperationNameValue`, from most to least frequent.",hints:["`has` works for a UPN that contains a name.",`Sort the final result.`],explanation:`Four VM creations within a few minutes, a role assignment and the deletion of a diagnostic setting tell a story: privileges obtained, resources deployed, traces erased.`,commonMistakes:["Forgetting that `has` only finds whole terms.",'Looking for `Caller == "svc-backup2"` without the domain.']},"kql-063":{title:`Deleting diagnostic settings`,objective:`Recognize defense evasion in AzureActivity.`,statement:"Return the Azure operations whose `OperationNameValue` contains the term `DIAGNOSTICSETTINGS` **and** ends with `DELETE`. Columns: `TimeGenerated`, `Caller`, `CallerIpAddress`, `ResourceGroup`.",hints:["`has` looks for a **complete term**: `DIAG` is not enough.","The operation is a value of the form `PROVIDER/TYPE/ACTION`."],explanation:"Deleting a diagnostic setting cuts the log flow to Log Analytics: it is a defense evasion technique. This rule is useful in production, especially if it targets `rg-sec`.",commonMistakes:['Searching `has "DIAG"`: the whole term is `DIAGNOSTICSETTINGS`.','Forgetting `endswith "DELETE"`: you would also get the writes.']},"kql-064":{title:`Machines silent for more than a day`,objective:`Detect an absence of telemetry.`,statement:"Return the computers (`Computer`) whose **last** heartbeat (`Dernier`) is more than one day old (relative to the simulated clock).",hints:[`Compute the last date per machine.`,`An absence is detected **after** the aggregation, not before.`],explanation:`You cannot detect an absence by filtering the rows of a window: there are precisely no rows. You aggregate the history, then compare the last signal to the expected window.`,commonMistakes:["Filtering `TimeGenerated < ago(1d)` before the `summarize`: every active machine also has old heartbeats.","Using `min` instead of `max`."]},"kql-065":{title:`Failed SSH addresses`,objective:`Extract an IP address from a message with extract().`,statement:"In `Syslog`, the `Failed password ... from <IP> port ...` messages contain the source address. Return the number of failures (`Echecs`) per extracted address (`SourceIP`), excluding rows without an address.",hints:["`extract(regex, group, text)` returns the captured group.",'Use a verbatim string `@"..."` for the regex.'],explanation:'`extract` applies a regular expression with a capture group. A verbatim string (`@"..."`) avoids doubling the backslashes.',commonMistakes:[`Forgetting the group number (1).`,"Writing the regex without `@` and losing the `\\`."]},"kql-066":{title:`SSH: success after failures`,objective:`Link SSH failures and acceptances on the same source address.`,statement:'Define `sources` as the addresses (extracted from the "Failed password" messages) with **at least 20 failures**. Then return the `Syslog` rows containing `Accepted` whose extracted address is in `sources`. Columns: `TimeGenerated`, `Computer`, `SyslogMessage`.',hints:[`Extract the address in both queries.`,"End the `let` with a `project SourceIP`."],explanation:"Same pattern as for RDP or Entra ID: many failures, then a success from the same source. A `root` accepted by password from the Internet is an incident to handle.",commonMistakes:[`Forgetting to factor out the extraction in both queries.`,"Leaving several columns in `sources`."]},"kql-067":{title:`Denied traffic by destination`,objective:`Analyze the firewall with CommonSecurityLog.`,statement:'In `CommonSecurityLog`, compute per `SourceIP` and per `DestinationPort` the number of **denied** flows (`DeviceAction == "Deny"`, column `Refus`), then keep only the pairs with more than one denial.',hints:[`Group on **two** columns.`,`Filter after the aggregation.`],explanation:`Grouping by source and port highlights a repetition (scan, port sweep) rather than isolated denials. One denial is noise; twenty is a pattern.`,commonMistakes:[`Grouping only by source: you lose the port.`,"Filtering `Refus > 1` before the aggregation."]},"kql-068":{title:`Sources whose volume exceeds 5 times the average`,objective:`Compare to a global value computed with toscalar().`,statement:"Compute the total bytes sent per `SourceIP` (`Total`). Return the sources whose total exceeds **5 times the average of the totals**. Use `toscalar()` for the average.",hints:["Name the per-source summary with a `let` to reuse it.","`toscalar()` converts a one-cell table into a value."],explanation:"Comparing each entity to the population is more robust than a fixed threshold. `toscalar` computes the average once; without it, `moyenne` would not be a usable value in the `where`.",commonMistakes:["Using a `let` without `toscalar` for the average.",`Comparing to the average of the rows rather than of the totals per source.`]},"kql-069":{title:`PowerShell launched by Word, then a network connection`,objective:`Correlate a suspicious process with the network on the same device and within a time window.`,statement:"In Advanced Hunting, find the executions of `powershell.exe` launched by `WINWORD.EXE` (`InitiatingProcessFileName`). Join them to the `DeviceNetworkEvents` connections of the **same device** that occurred within the **10 minutes following** the launch. Return `DeviceName`, `Lancement` (the `Timestamp` of the process) and `RemoteUrl`.",hints:[`Rename the time columns on each side to avoid ambiguity.`,"`between (start .. end)` bounds a value."],explanation:`Word launching PowerShell is suspicious in itself; a network connection in the following minutes confirms the execution. Joining on the device alone is broad, it is the time window that makes it precise.`,commonMistakes:[`Joining without a time bound: you associate any connection of the device.`,"Forgetting that `Timestamp` exists in both tables."]},"kql-070":{title:`Assemble: first appearance of an address`,objective:`Order a new-element detection.`,statement:"Assemble the query that returns the IP addresses (`IPAddress`) whose first appearance is less than 2 days old. One block is a decoy.",hints:[`The first-appearance date is computed over the whole history.`,`The time filter applies to the aggregated column.`],explanation:'Filtering on `TimeGenerated` before the aggregation would make every recently active address look "new", including the oldest ones.',commonMistakes:["Placing the time filter before `summarize`.",`Not aggregating at all.`]},"kql-071":{title:`Fix: a join that loses rows`,objective:`Understand that the default join (innerunique) deduplicates the left table.`,statement:"We want **every** 4625 event of `SecurityEvent` along with the last heartbeat (`Dernier`) of its `Computer`. However, the number of rows returned is too small. Fix the query to keep all the events.",hints:["Which `kind` is used when none is specified?",`This type keeps a single left row per key value.`],explanation:"Without `kind`, KQL applies `innerunique`: the **left** table is deduplicated on the key before the join. Rows are therefore lost, which is a silent trap. Always specify `kind=inner` (or another) explicitly.",commonMistakes:["Believing that `join` without `kind` is a classic inner join.",`Putting the big table on the right to work around it.`]},"kql-072":{title:`Fix: take before sort`,objective:`See why limiting before sorting gives an arbitrary result.`,statement:"We want the 5 **largest** flows (`SentBytes`) of `CommonSecurityLog`, with `SourceIP` and `SentBytes`. This query gives wrong results. Fix it.",hints:[`The order of operators matters: which one limits before sorting?`,"`top N by` does both in the right order."],explanation:"`take 5` picks 5 **arbitrary** rows that are then sorted: the result has nothing to do with the 5 largest flows. `top 5 by SentBytes desc` or `sort | take` is correct.",commonMistakes:[`Only reversing the sort direction.`,"Believing that `take` returns the first rows of the table."],check:{rules:[{message:`take placed before sort picks arbitrary rows before the sort.`}]}},"kql-073":{title:`Read a result: how many failures before the success?`,objective:`Read the result of a failure/success correlation.`,statement:`This query links the RDP failures and the success that follows.`,hints:[`The result fits on very few rows.`,"Read the `NbEchecs` column."],explanation:`Sixty failures, then a success on SRV-FILE01 from the same address: this is a probable compromise by brute force. The logical next step is to look for events 4672, 4720 and 4732 on the machine.`,commonMistakes:[`Reading another column.`,`Not seeing that the join filtered out earlier successes.`],question:`How many failures precede this success?`},"kql-074":{title:`Read a result: which machine is silent?`,objective:`Interpret an absence detection.`,statement:`This query lists the machines with no heartbeat for more than a day.`,hints:[`The sort is descending on the date of the last signal.`,`The first row has the most recent signal.`],explanation:`SRV-WEB01 is a web server: a sudden silence can be an outage, a planned shutdown or an agent disabled by an attacker. You need to correlate with recent changes and account activity.`,commonMistakes:[`Reading the last row (the oldest silence).`,`Confusing the last signal and the duration of the silence.`],question:`Which machine became silent most recently?`},"kql-075":{title:`Success rate per address`,objective:`Compute a ratio with countif and round, then filter on a minimum volume.`,statement:'For each address (`IPAddress`) of `SigninLogs` with at least **20 sign-ins**, return `IPAddress`, `Total`, `Succes` (sign-ins with `ResultType == "0"`) and `Taux`, the success percentage rounded to one decimal. Sort by `Taux` ascending.',hints:["`countif` counts the rows that meet a condition.","Multiply by `100.0` to avoid an integer division."],explanation:`A low success rate with a large volume reveals sources that almost always fail: spray, brute force or bot. The volume threshold avoids ranking addresses seen only once.`,commonMistakes:[`Forgetting the volume threshold and getting 0% rates on a single row.`,"Computing the percentage without `100.0`."]},"kql-076":{title:`Locked accounts`,objective:`Isolate a specific result code and summarize per account.`,statement:'Return the accounts (`UserPrincipalName`) of `SigninLogs` whose sign-in was denied because the account is **locked** (`ResultType == "50053"`), with `Verrouillages`, the number of events, and `Derniere`, the most recent date.',hints:[`Code 50053 means the account is locked.`,"Two aggregations in the same `summarize`."],explanation:`A lockout is the result of a brute force or spray that is visible to the legitimate user. It is useful for prioritizing the protection of targeted accounts.`,commonMistakes:["Using `ResultType == 50053` without quotes: the column is a string.","Forgetting `by UserPrincipalName`."]},"kql-077":{title:`Where strong authentication is required`,objective:`Group related result codes with in.`,statement:'Count, per application (`AppDisplayName`), the sign-ins where multifactor authentication is required (`ResultType` equal to `"50074"` or `"50076"`). Return `AppDisplayName` and `Exigences`, sorted from largest to smallest.',hints:["`in` accepts a list of values.",`Sort after the aggregation.`],explanation:`These two codes indicate that multifactor authentication is requested. The applications where it is required most often are the ones targeted first for conditional access policies.`,commonMistakes:["Repeating `or` instead of `in`, which is harder to read.","Sorting before the `summarize`."]},"kql-078":{title:`Who launches PowerShell?`,objective:`Profile the parent processes of an executable in Defender XDR.`,statement:"In `DeviceProcessEvents`, count the launches of `powershell.exe` per parent process (`InitiatingProcessFileName`). Return `InitiatingProcessFileName` and `Lancements`, from most to least frequent.",hints:["`=~` compares without case sensitivity.","The parent process is in `InitiatingProcessFileName`."],explanation:`Knowing the usual parents of a dual-use tool makes it possible to spot rare parents: a PowerShell launched by Word stands out from a PowerShell launched by a management agent.`,commonMistakes:["Using `==` and missing case variations.","Using `TimeGenerated` in this table."]},"kql-079":{title:`Oversized command lines`,objective:`Use strlen to spot unusually long commands.`,statement:"Return the launches in `DeviceProcessEvents` whose command line is **longer than 100 characters**, with `Timestamp`, `DeviceName`, `FileName` and `Longueur` (the length of `ProcessCommandLine`). Sort by `Longueur` descending.",hints:["`strlen` returns the length of a string.","Create the column with `extend` before filtering."],explanation:`Very long commands are often encoded or obfuscated payloads. Length alone is not proof, but it is a good sort criterion to focus attention.`,commonMistakes:["Filtering on `Longueur` before creating it.","Forgetting that `project` removes the other columns."]},"kql-080":{title:`Blocked emails and their links`,objective:`Join EmailEvents and EmailUrlInfo on NetworkMessageId.`,statement:'For each **blocked** email (`DeliveryAction == "Blocked"`) in `EmailEvents`, return `Timestamp`, `RecipientEmailAddress` and the URLs it contains (`Url` from `EmailUrlInfo`). Both tables share `NetworkMessageId`.',hints:[`Filter the blocked emails first to shrink the join.`,"Join on `NetworkMessageId`."],explanation:`The URL table links an email to its links. Filtering before the join keeps the left side small, which is faster.`,commonMistakes:[`Joining all the tables before filtering.`,"Joining on `Timestamp`, which differs between the tables."]},"kql-081":{title:`Most active external senders`,objective:`Exclude the internal domain and rank the senders.`,statement:"Among the emails in `EmailEvents` whose sender domain is **not** `nordlys.example`, return the **5** domains (`SenderFromDomain`) that send the most, with `Courriels`.",hints:[`Exclude the internal domain first.`,"`top 5 by ... desc` replaces `sort` then `take`."],explanation:`The main sender domains form a baseline: a domain that looks like the company's but appears at the bottom of the ranking deserves a closer look.`,commonMistakes:[`Forgetting the filter on the internal domain.`,"Putting the `top` before the `summarize`."]},"kql-082":{title:`Hosts contacting the most destinations`,objective:`Use dcount per host on the network.`,statement:"In `DeviceNetworkEvents`, return for each device (`DeviceName`) the number of distinct destinations (`RemoteUrl`) under the name `Destinations`. Keep the **3** devices that contact the most.",hints:["`dcount` counts distinct values.","End with `top 5`."],explanation:`A device that contacts far more destinations than its peers may be scanning or doing automated communication. It is a starting indicator, to be cross-checked with context.`,commonMistakes:["Using `count` instead of `dcount` and measuring volume rather than diversity."]},"kql-083":{title:`Failed network connections per device`,objective:`Filter on an action type and summarize.`,statement:'Return the devices with at least **one** failed network connection (`ActionType == "ConnectionFailed"`), with `Echecs`, and the list of distinct destinations attempted in `Destinations` (array built with `make_set(RemoteUrl)`).',hints:["`make_set` gathers the distinct values into an array.","A single `summarize` pass is enough."],explanation:`Connection failures reveal attempts blocked by the firewall or a nonexistent domain. The list of destinations gives the context immediately.`,commonMistakes:["Using `make_list`: duplicates appear.","Forgetting the filter on `ActionType`."]},"kql-084":{title:`RDP sessions per account`,objective:`Filter on the Windows session type and summarize per account.`,statement:"In `SecurityEvent`, for the successful logons (**4624**) of type **10** (RemoteInteractive, RDP), return the number of sessions per account (`Account`) in `Sessions` and the number of distinct machines in `Machines`. Sort by `Sessions` descending.",hints:["`LogonType` is an integer.","Two aggregations in the same `summarize`."],explanation:`An account that opens RDP sessions on many different machines may indicate lateral movement. Type 10 identifies remote interactive logons.`,commonMistakes:['Putting `"10"` in quotes for an integer column.']},"kql-085":{title:`The rarest processes on Windows`,objective:`Sort by ascending frequency to find the unusual.`,statement:"In `SecurityEvent`, for the process creation events (**4688**), return the **3** **least frequent** processes (`ProcessName`), with `Executions`. In case of a tie, keep the alphabetical order of `ProcessName`.",hints:[`Sort ascending so the rare ones come first.`,`Two sort keys separated by a comma.`],explanation:`Rarity is a classic signal: what runs only once across a fleet deserves a look, even if most cases are legitimate.`,commonMistakes:[`Forgetting the secondary sort key and getting an unstable result.`]},"kql-086":{title:`Linux logs by machine and severity`,objective:`Group on two columns.`,statement:"In `Syslog`, count the events per machine (`Computer`) and per severity level (`SeverityLevel`) in `Evenements`. Sort by `Computer` then by `Evenements` descending.",hints:[`Several grouping columns are separated by commas.`,`Two sort keys with different directions.`],explanation:`Grouping on two dimensions gives a cross-tab in long format, ideal before a chart or a comparison between machines.`,commonMistakes:["Using two separate `summarize` operators."]},"kql-087":{title:`Ports targeted by denied traffic`,objective:`Profile the destination ports blocked by the firewall.`,statement:'In `CommonSecurityLog`, for the denied actions (`DeviceAction == "Deny"`), count per destination port (`DestinationPort`) in `Refus`. Keep the ports with **more than 5** denials, sorted by `Refus` descending.',hints:["The threshold applies after the `summarize`.",`Sort at the end.`],explanation:`The most denied ports show what is being scanned or attempted: 22, 3389 or 445 often come first when exposure is poorly controlled.`,commonMistakes:[`Applying the threshold before the aggregation.`]},"kql-088":{title:`Directory operations by category`,objective:`Count successes and failures in one pass on AuditLogs.`,statement:'In `AuditLogs`, return per `OperationName` the number of successes (`Result == "success"`) in `Succes` and of failures (`Result == "failure"`) in `Echecs`. Keep only the operations with **at least one failure**.',hints:["Two `countif` in the same `summarize`.","Filter on `Echecs` after the aggregation."],explanation:"In `AuditLogs`, a failure of a privileged operation is valuable: it indicates a blocked attempt. The one-pass summary avoids reading the events one by one.",commonMistakes:["Filtering `Result` before counting, which erases the other category."]},"kql-089":{title:`Failed Azure operations by caller`,objective:`Identify who runs into denials in Azure.`,statement:'In `AzureActivity`, return the callers (`Caller`) with failed operations (`ActivityStatusValue == "Failed"`), with `Echecs` and the list of distinct operations in `Operations` (`make_set(OperationNameValue)`).',hints:["The status is in `ActivityStatusValue`.","`make_set` produces distinct values."],explanation:`A caller running into repeated denials may be exploring their rights, which is a behavior to watch after a compromise.`,commonMistakes:["Confusing `ActivityStatusValue` and `CategoryValue`."]},"kql-090":{title:`Hours above three times the average`,objective:`Compare an hourly series to its overall average with toscalar.`,statement:'In `SigninLogs`, count the failures (`ResultType != "0"`) per hour (`bin(TimeGenerated, 1h)`) in `Echecs`. Return `Heure` and `Echecs` for the hours where `Echecs` exceeds **three times** the hourly average of failures across all hours. Sort by `Heure`.',hints:["Compute the hourly series in a `let`.","`toscalar` turns a single-value result into a scalar."],explanation:`Comparing to the overall average highlights the spikes. The attack hours stand out clearly from the ordinary noise.`,commonMistakes:[`Computing the average on the original rows rather than on the hourly series.`]},"kql-091":{title:`Windows and Linux failures together`,objective:`Unify two heterogeneous sources with union.`,statement:"Count the authentication failures of all machines: the **4625** events of `SecurityEvent` and the `Failed password` messages of `Syslog`. Return `Machine` and `Echecs`, sorted by `Echecs` descending.",hints:["Align the column names before the `union`.","`union` accepts subqueries in parentheses."],explanation:`In a SOC, the same attack hits several platforms. Unifying the sources gives a ranking regardless of the platform.`,commonMistakes:[`Doing the union before projecting to common columns.`]},"kql-092":{title:`Unified attacker timeline`,objective:`Build a timeline from several tables.`,statement:'Build the timeline of the address `203.0.113.45`: the rows of `SigninLogs` (`IPAddress`) and of `AzureActivity` (`CallerIpAddress`). Return `TimeGenerated`, `Source` (`"Entra"` or `"Azure"`) and `Detail` (`ResultType` for Entra, `OperationNameValue` for Azure). Sort by `TimeGenerated`.',hints:[`The three columns must exist in each subquery.`,'A constant can serve as a column value: `Source = "Entra"`.'],explanation:`A multi-source timeline turns isolated alerts into a story. Here you read the spray, the success, then the Azure operations from the same address.`,commonMistakes:["Forgetting the `Source` column and no longer knowing where a row comes from."]},"kql-093":{title:`Fix: invalid time unit`,objective:`Recognize the valid syntax of an interval.`,statement:`This query should return the number of failures of the **last 3 days**, but it produces an error. Fix it.`,hints:[`Time units are written in abbreviated form.`,"Days: `d`, hours: `h`, minutes: `m`."],explanation:'`ago(3d)` is the correct form. The full word "hours" is not recognized as a suffix of a timespan literal.',commonMistakes:["Writing `ago(3 days)` as in natural language."]},"kql-094":{title:`Fix: column removed too early`,objective:`Understand that a project removes the following columns.`,statement:"This query should return `UserPrincipalName` and `IPAddress` for the successful sign-ins, but it fails. Fix it without changing its final columns.",hints:["`project` drops all the other columns.",`Filter before projecting.`],explanation:"After `project`, `ResultType` no longer exists. The natural order of a query: filter first, project afterwards.",commonMistakes:["Adding `ResultType` to the `project`: the result would contain one column too many."]},"kql-095":{title:`Fix: sum on a string`,objective:`Spot an incorrect type in an aggregation.`,statement:`This query should return the total volume sent per source address, but it fails. Fix it.`,hints:[`Which column contains a volume?`,"`sum` applies to a numeric column."],explanation:"`SourceIP` is a string. The volume is in `SentBytes`. The grouping variable stays `DestinationIP`.",commonMistakes:["Converting `SourceIP` to a number to make the query pass."]},"kql-096":{title:`Fix: a join that duplicates rows`,objective:`Shrink the right side of a join before joining.`,statement:"This query should return one row per successful sign-in, with the number of earlier failures from the same address (`NbEchecs`). As written, it returns one row per failure. Fix it.",hints:[`Aggregate the right side before joining.`,`There must be a single row per join key.`],explanation:"Joining on a non-unique key multiplies the rows. Aggregating the right side by `IPAddress` guarantees one row per key.",commonMistakes:["Leaving a constant `NbEchecs = 1` instead of the real count."]},"kql-097":{title:`Assemble: accounts seen in more than one country`,objective:`Put the blocks back in logical order.`,statement:"Assemble the query that returns the successful accounts seen in **more than one country**, with `UserPrincipalName` and `Pays`. Three blocks are not used.",hints:[`Filter the successes before summarizing.`,"`dcount` counts distinct values; the threshold comes after the `summarize`."],explanation:"The blocks form the sequence filter, aggregation, threshold. `count` would measure sign-ins, not geographic diversity, and a `top` does not set a threshold.",commonMistakes:["Choosing `count` instead of `dcount`.",`Placing the threshold before the aggregation.`]},"kql-098":{title:`Assemble: silent machines timeline`,objective:`Order a query that computes a silence duration.`,statement:"Assemble the query that returns, for each machine, the last heartbeat and the number of hours of silence (`Silence`) since the reference date `datetime(2026-03-12T12:00:00Z)`. Two blocks are not used.",hints:[`Summarize before computing the duration.`,'`datetime_diff("hour", end, start)`.'],explanation:`You summarize first to get the last heartbeat, then compute the duration. The 24-hour filter is not part of the request.`,commonMistakes:["Reversing the two dates of `datetime_diff` and getting a negative number."]},"kql-099":{title:`Read a result: who is the most distinct?`,objective:`Read a two-column aggregation result.`,statement:`Read the query result and answer the question.`,hints:[`The first row is the one with the most accounts.`,"Read the `Comptes` column, not `Echecs`."],explanation:"The `top` sorts by number of accounts descending: the first row is the address that targeted the most accounts. This is the mark of a spray, because `Echecs` is close to `Comptes`.",commonMistakes:["Reading `Echecs` instead of `Comptes`."],question:`How many distinct accounts did the first address in the result target?`},"kql-100":{title:`Read a result: the lowest rate`,objective:`Interpret a computed ratio.`,statement:`Look at this ranking of addresses by success rate, then identify the most problematic one.`,hints:["The sort is ascending on `Taux`.",`The first row has the lowest rate.`],explanation:`With an ascending sort, the first row has the lowest rate. An address with a low rate and a high volume almost always fails: this is the profile of a brute force.`,commonMistakes:[`Reading the last row believing the sort is descending.`],question:`Which address has the lowest success rate?`},"kql-101":{title:`Spray per one-hour window`,objective:`Detect a spray by bounding the window with bin.`,statement:'In `SigninLogs`, for the credential failures (`ResultType == "50126"`), return the pairs (`IPAddress`, `Heure` = `bin(TimeGenerated, 1h)`) where the address targeted **at least 10 distinct accounts** (`Comptes`) within the same hour.',hints:[`Group on the address **and** on the hour.`,`The threshold applies after the aggregation.`],explanation:`Bounding the spray in a window avoids accumulating unrelated failures over several days. This is the usual form of a scheduled spray rule.`,commonMistakes:[`Grouping only by address and mixing different days.`,"Placing the threshold before the `summarize`."]},"kql-102":{title:`Success within 30 minutes after failures`,objective:`Join two observations and bound the time gap with datetime_diff.`,statement:"Find the accounts (`UserPrincipalName`) that had a **successful** sign-in from an address (`IPAddress`) within the **30 minutes following** at least **one failure** of the same account from the same address. Return `UserPrincipalName`, `IPAddress` and `Echecs` (number of failures in the window), without duplicates per account and address.",hints:["Rename the failures' time so you do not overwrite `TimeGenerated`.","`between (0 .. 30)` bounds the difference in minutes."],explanation:`A success close to failures of the same account/address pair describes an attacker who finally finds the right password, but also a user who makes a typo before succeeding. The number of failures helps tell them apart.`,commonMistakes:[`Forgetting to rename the time column on the failures side.`,`Joining on the account alone and mixing several addresses.`]},"kql-103":{title:`Destinations seen by a single device`,objective:`Isolate rare values with dcount then find the device.`,statement:"In `DeviceNetworkEvents`, return the destinations (`RemoteUrl`) contacted by **a single** device, with that device (`DeviceName`) in `Appareil` and the number of connections in `Connexions`.",hints:["`dcount(DeviceName)` measures how many devices contacted the destination.","`any()` returns one value of the group, useful when there is only one."],explanation:`The rarity of a destination across a fleet is an indicator of relative value: it focuses the review, it proves nothing. Here the exfiltration destination stands out.`,commonMistakes:["Forgetting to filter on `Appareils == 1`.","Using `max` in place of `any` on a string without thinking about it."]},"kql-104":{title:`Sent to received ratio`,objective:`Compare two aggregated volumes and filter on a ratio.`,statement:"In `CommonSecurityLog`, compute per pair (`SourceIP`, `DestinationIP`) the sum of `SentBytes` (`Envoye`) and of `ReceivedBytes` (`Recu`). Return the pairs where `Envoye` is **more than 5 times** `Recu`, with `Ratio` (rounded to one decimal).",hints:["Protect against a division by zero with `Recu > 0`.","Multiply by `1.0` for a real division."],explanation:`A flow that sends much more than it receives looks like an upload, whereas web browsing does the opposite. It is a signal complementary to the raw volume.`,commonMistakes:[`Dividing by a zero total.`,`Comparing volumes row by row instead of aggregating them.`]},"kql-105":{title:`95th percentile of transfers`,objective:`Use percentile to describe the tail of a distribution.`,statement:"In `CommonSecurityLog`, return per source address (`SourceIP`) the number of transfers `Nb`, the median value `P50` and the 95th percentile `P95` of `SentBytes`. Sort by `P95` descending.",hints:["`percentile(column, 95)`.","Several percentiles in the same `summarize` are allowed."],explanation:`The 95th percentile describes the heavy tail of a behavior, more informative than the average when a few extreme values dominate. The median gives the usual behavior.`,commonMistakes:[`Using the average and hiding an exfiltration tail.`]},"kql-106":{title:`Unauthorized addresses with datatable`,objective:`Use a datatable as an allow list.`,statement:'Define the trusted address list `confiance` with `datatable(IPAddress:string)["192.0.2.10", "198.51.100.12"]`. Return the addresses of `SigninLogs` that are **absent** from this list and had **successful** sign-ins, with `Connexions`, sorted by `Connexions` descending. Keep the first **3**.',hints:["`!in` accepts a one-column table name.","End with `top 3`."],explanation:`An inline trusted list illustrates the principle of watchlists: it remains reference data to keep up to date, separate from the query logic.`,commonMistakes:["Forgetting to declare the column type in the `datatable`."]},"kql-107":{title:`Account created then added to a group`,objective:`Correlate two Windows events on the same machine within a window.`,statement:"In `SecurityEvent`, find the machines (`Computer`) where an account was **created** (4720) then a member was **added to a local group** (4732) within the following **10 minutes**. Return `Computer`, `Creation` (time of the 4720), `Ajout` (time of the 4732) and `Minutes`, the gap between the two.",hints:[`Give different column names to the two times.`,`Compute the gap in minutes before filtering.`],explanation:`The sequence of creation then addition to a privileged group in a short time is a persistence signature. The two isolated events are common; their chaining is not.`,commonMistakes:[`Forgetting to bound the time gap and joining distant events.`,`Not checking the order (addition before creation).`]},"kql-108":{title:`Expected servers with no heartbeat at all`,objective:`Compare an expected inventory to the observed machines with leftanti.`,statement:'Here is the expected inventory: `datatable(Computer:string)["SRV-DC01", "SRV-FILE01", "SRV-WEB01", "LNX-APP01", "LNX-DB01", "SRV-FANTOME01"]`. Return the inventory machines that have **no** row in `Heartbeat`.',hints:["`leftanti` keeps the left rows with no match on the right.","Shrink the right side with `distinct`."],explanation:`Comparing the expected to the observed reveals machines that were never onboarded. It is one of the most profitable logging coverage checks.`,commonMistakes:[`Reversing the sides of the join.`,"Using `inner` and getting the machines that are present."]},"kql-109":{title:`Malicious addresses seen in Azure`,objective:`Reuse a list from one source to filter another.`,statement:'Define `suspectes` as the addresses (`IPAddress`) of `SigninLogs` with **at least 20 failures** (`ResultType != "0"`). Return the `AzureActivity` operations whose `CallerIpAddress` is in this list, with `TimeGenerated`, `Caller` and `OperationNameValue`.',hints:["The list must be a single column for `in`.",`The two tables do not have the same address column name.`],explanation:`Moving from one source to the other through the address is the basis of incident correlation: an address identified as hostile in identity is searched for in the management operations.`,commonMistakes:["Keeping more than one column in the `let`."]},"kql-110":{title:`Rare actors in AuditLogs`,objective:`Extract a dynamic field and profile the actors.`,statement:'In `AuditLogs`, create `Acteur` = `tostring(InitiatedBy.user.userPrincipalName)`. Return per `Acteur` the number of operations (`Operations`) and of failures (`Echecs`, `Result == "failure"`). Keep the actors with **fewer than 5 operations**.',hints:[`A nested field is accessed with dot notation.`,"`tostring` converts the dynamic value to a string."],explanation:`Rare actors are those that appear little in the directory: service accounts, recent or compromised accounts. It is a hunting starting point, not a conclusion.`,commonMistakes:["Forgetting `tostring` and grouping on a dynamic value."]},"kql-111":{title:`Operations targeting service accounts`,objective:`Expand a dynamic array with mv-expand then filter.`,statement:"In `AuditLogs`, expand `TargetResources` with `mv-expand`, extract `Cible = tostring(TargetResources.userPrincipalName)` and keep the rows where the target **starts with** `svc-`. Return `TimeGenerated`, `OperationName`, `Result` and `Cible`.",hints:["`mv-expand` turns each element of the array into a row.",`Extract the target before filtering on it.`],explanation:`Service accounts targeted by directory operations (creation, role assignment) deserve a review: they are rarely modified legitimately.`,commonMistakes:["Filtering before the `mv-expand`.","Forgetting `tostring`."]},"kql-112":{title:`Share of each destination in the outbound volume`,objective:`Compute a share of the total with toscalar.`,statement:"In `CommonSecurityLog`, compute per destination (`DestinationIP`) the total volume `Volume` (sum of `SentBytes`) and its share `Part` of the overall volume, as a percentage rounded to one decimal. Return the **3** destinations with the largest share.",hints:["Compute the overall total in a `let` with `toscalar`.","Use `100.0` for a real division."],explanation:`The share tells whether a destination dominates the traffic. An unknown destination that monopolizes a large share of the outbound volume is an exfiltration signal.`,commonMistakes:[`Computing the share with a per-group total rather than the overall one.`]},"kql-113":{title:`Session type profile per machine`,objective:`Build a cross-tab with several countif.`,statement:"In `SecurityEvent`, for the successful logons (**4624**), return per machine (`Computer`): `Interactives` (`LogonType == 2`), `Reseau` (`LogonType == 3`) and `RDP` (`LogonType == 10`). Keep the machines with **at least one** RDP session, sorted by `RDP` descending.",hints:["One `countif` per type in the same `summarize`.","Filter on `RDP` after the aggregation."],explanation:`A cross-tab by session type describes how each machine is logged into. A server where RDP dominates although it should not be administered remotely deserves a review.`,commonMistakes:["Running three separate queries instead of a single `summarize`.",`Filtering on the session type before counting the other types.`]},"kql-114":{title:`Silent machines that still fail`,objective:`Cross an agent's silence with another source's activity.`,statement:"Return the machines (`Computer`) whose **last heartbeat** is earlier than `datetime(2026-03-12T00:00:00Z)` and that have **at least one 4625 failure** in `SecurityEvent`. Columns: `Computer`, `DernierePulsation`, `Echecs`.",hints:["Compute both sides separately, then join on `Computer`.",`Filter the silent machines before the join.`],explanation:`A silent agent can hide activity: the point is to spot machines that still have recent failures elsewhere. It is a cross of collection health and detection.`,commonMistakes:["Using `ago()`: the reference date is fixed in this playground."]},"kql-115":{title:`Fix: join columns with different names`,objective:`Join with $left and $right when the keys have different names.`,statement:"This query should associate each Azure operation with its caller in `SigninLogs` (column `UserPrincipalName`), but the join fails. Fix it.",hints:[`The two tables name the key differently.`,"Use `$left.column == $right.column`."],explanation:"When the names differ, `on Caller` looks for a `Caller` column on both sides. The `$left.X == $right.Y` form specifies the match.",commonMistakes:["Renaming a column with `extend` without keeping the other one."]},"kql-116":{title:`Fix: datatable without types`,objective:`Declare the columns of a datatable correctly.`,statement:"This query should count the sign-ins of the two addresses in the list, but the `datatable` declaration is invalid. Fix it.",hints:["Each column of a `datatable` has a type.",`The type is written after a colon.`],explanation:"A `datatable` requires explicit types: `name:type`. Without a type, the engine cannot interpret the literal values.",commonMistakes:[`Putting the types in quotes.`]},"kql-117":{title:`Fix: threshold on the wrong set`,objective:`Apply a threshold on distinct accounts and not on rows.`,statement:"We want the addresses that targeted **at least 10 distinct accounts** with code `50126`. The query returns addresses that targeted only one account, because it counts rows. Fix it.",hints:[`Which function counts distinct values?`,`A brute force on a single account must not meet the criterion.`],explanation:"Spray and brute force are told apart by the number of **accounts** targeted, not by the number of attempts. `dcount` separates the two profiles.",commonMistakes:["Keeping `count()` while lowering the threshold."]},"kql-118":{title:`Assemble: share of the outbound volume`,objective:`Order a query with let, toscalar and extend.`,statement:"Assemble the query that returns the share (`Part`, in %) of each destination in the overall outbound volume. Two blocks are not used.",hints:["The `let` comes first.",`Compute the volume per destination before the share.`],explanation:"The overall total is computed once in the `let`, then reused after the aggregation by destination.",commonMistakes:[`Computing the share before the aggregation.`]},"kql-119":{title:`Read a result: the quietest actor`,objective:`Read an actor profile and spot the unusual.`,statement:`This profile sorts the AuditLogs actors from least to most active. Spot the quietest one.`,hints:[`The sort is ascending.`,"Read the `Acteur` column of the first row."],explanation:`The ascending sort puts the rarest actors first. In our data, it is l.bouchard: only three operations, all during the incident, whereas the legitimate administrators have dozens.`,commonMistakes:[`Reading the last row instead of the first.`],question:`Which actor has the fewest operations (first row)?`},"kql-120":{title:`Read a result: who is missing from the inventory?`,objective:`Interpret the result of a leftanti join.`,statement:`Read the result of a query that compares a server inventory to the machines sending heartbeats.`,hints:["`leftanti` keeps the left rows with no match.",`A single row is returned.`],explanation:`This machine is in the inventory but never in the heartbeats: it was never onboarded, or its name is wrong in the inventory. Both cases deserve an action.`,commonMistakes:[`Believing the result lists the machines that are present.`],question:`Which inventory machine never sent a heartbeat?`}},a={"az-001":{title:`Sort the items into the hierarchy`,objective:`Place an item among the four Azure scope levels.`,statement:`Azure organizes its items into four scope levels. Place each Nordlys Technologies item in the level it belongs to.`,hints:[`A management group contains subscriptions, never resources directly.`,`A virtual machine and a storage account are resources, not containers.`],explanation:`The four levels, from broadest to narrowest: management group, subscription, resource group, resource. Settings applied at one level (access, policies, locks) are inherited by the levels below.`,commonMistakes:[`Placing a resource group under "Resource" because it is itself an ARM resource.`,`Confusing subscription and resource group.`],items:[{id:`e1`,text:`mg-nordlys-racine`},{id:`e2`,text:`Sub-Production`},{id:`e3`,text:`rg-prod-web`},{id:`e4`,text:`vm-web-01 (virtual machine)`},{id:`e5`,text:`stnordlyslogs (storage account)`},{id:`e6`,text:`rg-securite`},{id:`e7`,text:`Sub-Laboratoire`},{id:`e8`,text:`mg-plateforme`}],zones:[{id:`mg`,label:`Management group`,description:`Groups subscriptions`},{id:`sub`,label:`Subscription`,description:`Billing and management boundary`},{id:`rg`,label:`Resource group`,description:`Container for related resources`},{id:`res`,label:`Resource`,description:`Single managed item`}]},"az-002":{title:`From the broadest scope to the narrowest`,objective:`Order the scope levels.`,statement:`Put the scope levels back in order, **from broadest to narrowest**.`,hints:[`The broadest level contains the subscriptions.`,`The resource is the final item, at the very bottom.`],explanation:`A setting applied higher up is inherited by everything below it: a policy applied to the subscription applies to all its resource groups and to all their resources.`,commonMistakes:[`Reversing subscription and resource group.`,`Forgetting the "management group" level, optional in practice but present in the hierarchy.`],items:[{id:`o1`,text:`Management group`},{id:`o2`,text:`Subscription`},{id:`o3`,text:`Resource group`},{id:`o4`,text:`Resource`}]},"az-003":{title:`The Azure Resource Manager vocabulary`,objective:`Match an ARM term to its definition.`,statement:`Match each term to its definition.`,hints:[`Microsoft.Compute and Microsoft.Storage are examples of providers.`,`Two definitions describe a declarative syntax: one of them is JSON.`],explanation:`ARM is the Azure management layer. ARM templates and Bicep are two ways of declaratively describing what you want to get, without writing the sequence of commands.`,commonMistakes:[`Confusing resource provider and resource.`,`Assigning the JSON definition to Bicep.`],items:[{id:`m1`,text:`Resource`},{id:`m2`,text:`Resource group`},{id:`m3`,text:`Resource provider`},{id:`m4`,text:`ARM template`},{id:`m5`,text:`Bicep file`}],options:[{id:`p1`,text:`Manageable item in Azure (virtual machine, storage account, virtual network, etc.)`},{id:`p2`,text:`Container of related resources that share the same lifecycle`},{id:`p3`,text:`Service that supplies a resource type, such as Microsoft.Compute`},{id:`p4`,text:`Declarative JSON file that defines the resources to deploy`},{id:`p5`,text:`Declarative language designed to deploy Azure resources`},{id:`p6`,text:`Billing boundary of an organization`}]},"az-004":{title:`Why the portal and the CLI give the same results`,objective:`Understand that every tool goes through Azure Resource Manager.`,statement:`You create a virtual machine once through the Azure portal and once with Azure CLI. The result is identical. Why?`,hints:[`Think about the common management layer.`,`Every request, whatever the tool, goes through a single entry point.`],explanation:`Resource Manager receives the request from any tool or SDK, authenticates it, authorizes it, then forwards it to the relevant service. This common layer guarantees consistent results.`,commonMistakes:[`Imagining separate interfaces per tool.`,`Believing the portal is a simple wrapper around Azure CLI.`],choices:[{id:`c1`,text:`All requests are handled by the same Azure Resource Manager API, which authenticates and authorizes them before forwarding them to the service`},{id:`c2`,text:`The portal always calls Azure CLI in the background`},{id:`c3`,text:`Azure CLI automatically copies the portal actions`},{id:`c4`,text:`Each Azure service implements its own interface for each tool`}]},"az-005":{title:`Same lifecycle, same resource group`,objective:`Decide which resources go in the same resource group based on their lifecycle.`,statement:`The **Billing** application is deployed, updated and deleted as a whole. The platform components are shared and follow a different pace. Place each resource in the right group.`,hints:[`What will be deleted the day the application disappears?`,`A shared resource must not disappear with a single application.`],explanation:`All the resources in a group should share the same lifecycle: they are deployed, updated and deleted together. Deleting the group deletes all its content, hence the value of isolating what is shared.`,commonMistakes:[`Grouping everything in a single "prod" group.`,`Placing the shared network with the application: deleting it would break the others.`],items:[{id:`e1`,text:`Virtual machine of the Billing application`},{id:`e2`,text:`Billing database`},{id:`e3`,text:`Billing web application`},{id:`e4`,text:`Hub virtual network shared by all applications`},{id:`e5`,text:`Central Log Analytics workspace`},{id:`e6`,text:`Key vault common to several teams`}],zones:[{id:`rg-fact`,label:`rg-facturation`,description:`Lifecycle specific to the application`},{id:`rg-plat`,label:`rg-plateforme`,description:`Shared and independent lifecycle`}]},"az-006":{title:`Lab cleanup: the dangerous line`,objective:`Spot a delete command that targets the wrong resource group.`,statement:`This script creates a lab environment then cleans it up. **Spot the dangerous line** and choose the right fix.`,hints:[`Which resource group did the script create?`,`Deleting a resource group deletes **all** its resources.`],explanation:"The deletion targets `rg-prod` whereas the script only created `rg-lab-kql`. Since deleting a group deletes its entire content, this is one of the costliest mistakes. Always check the group name before `--yes`.",commonMistakes:["Thinking `--no-wait` protects against the mistake.","Believing `--yes` only confirms the deletion of the workspace."],lines:[{id:`l1`,text:`az group create --name rg-lab-kql --location canadacentral`},{id:`l2`,text:`az monitor log-analytics workspace create --resource-group rg-lab-kql --workspace-name law-lab-kql --location canadacentral`},{id:`l3`,text:`az group delete --name rg-prod --yes --no-wait`,faulty:{remedies:[{id:`r3-1`,text:`Replace rg-prod with rg-lab-kql`},{id:`r3-2`,text:`Add the --force option`},{id:`r3-3`,text:`Remove --yes to confirm each resource`}]}}]},"az-007":{title:`First command-line deployment`,objective:`Order the basic steps of a deployment with Azure CLI.`,statement:`Put the steps of a first command-line deployment back in order.`,hints:[`You must authenticate before any command.`,`The resource group must exist before the deployment.`],explanation:`Authentication, choice of the active subscription, creation of the container (resource group), deployment, then verification. Choosing the subscription avoids deploying to the wrong one.`,commonMistakes:[`Forgetting to select the subscription when you have several.`,`Deploying before creating the group.`],items:[{id:`o1`,text:"Sign in with `az login`"},{id:`o2`,text:"Choose the subscription with `az account set --subscription`"},{id:`o3`,text:"Create the resource group with `az group create`"},{id:`o4`,text:`Deploy the template in this group`},{id:`o5`,text:`Verify the created resources`}]},"az-008":{title:`Zonal, zone-redundant or non-zonal`,objective:`Match a deployment mode to its behavior during a zone outage.`,statement:`Match each deployment mode to what it implies when an availability zone fails.`,hints:[`Who is responsible for the failover in each case?`,`A resource not configured for zones has no distribution guarantee.`],explanation:`An availability zone is a group of separate datacenters with independent power, cooling and network. Zonal: you manage everything. Zone-redundant: Microsoft manages it. Non-zonal: arbitrary placement, therefore exposed.`,commonMistakes:[`Believing an unconfigured resource is automatically spread out.`,`Confusing availability zone and region.`],items:[{id:`m1`,text:`Zonal resource`},{id:`m2`,text:`Zone-redundant resource`},{id:`m3`,text:`Non-zonal deployment`},{id:`m4`,text:`Multi-region deployment`}],options:[{id:`p1`,text:`Pinned to a chosen zone: you manage replication and failover`},{id:`p2`,text:`Spread across several zones: Microsoft manages distribution and failover`},{id:`p3`,text:`Can be placed in any zone: a zone outage can make it unavailable`},{id:`p4`,text:`Resources in several regions to withstand a regional outage`},{id:`p5`,text:`Always automatically protected against any datacenter outage`}]},"az-009":{title:`A zone outage without configuration`,objective:`Reason about the impact of a zone outage on a non-zonal deployment.`,statement:`A web application was deployed in a region that supports zones, **without** zone configuration. One zone of the region goes down. Which statement is the most accurate?`,hints:[`What happens to a resource that was not configured for zones?`,`Placement is not guaranteed.`],explanation:`Without configuration, Azure treats the resource as non-zonal and may place it in any zone of the region: an outage of that zone can make it unavailable. For resilience, you choose a zone-redundant approach.`,commonMistakes:[`Assuming high availability is implicit.`,`Confusing zone failover and region failover.`],choices:[{id:`c1`,text:`The application can become unavailable, because Azure may have placed it in the affected zone`},{id:`c2`,text:`The application is always available, because Azure automatically spreads any resource across all zones`},{id:`c3`,text:`The application always fails over to another region`},{id:`c4`,text:`The application cannot be affected by a zone outage`}]},"az-010":{title:`At which level should each setting be applied?`,objective:`Choose the scope suited to a governance need.`,statement:`Place each need at the **narrowest** scope level that satisfies it.`,hints:[`The narrower the scope, the fewer rights or constraints you grant.`,`Access to a single storage account does not justify a broader scope.`],explanation:`You apply the setting at the narrowest scope that meets the need: this is the logic of least privilege. The lower levels inherit what is defined above.`,commonMistakes:[`Assigning at the subscription level "to make it work".`,`Applying to a resource what should cover a whole group.`],items:[{id:`e1`,text:`An allowed regions policy for all the subscriptions of the organization`},{id:`e2`,text:`A Reader role for the audit team across the whole Production environment`},{id:`e3`,text:`A CanNotDelete lock on all the components of the Billing application`},{id:`e4`,text:`Read access to a single storage account`}],zones:[{id:`mg`,label:`Management group`},{id:`sub`,label:`Subscription`},{id:`rg`,label:`Resource group`},{id:`res`,label:`Resource`}]},"az-011":{title:`The journey of an Azure request`,objective:`Order how Azure Resource Manager processes a request.`,statement:`Put in order what happens when you send a resource creation request.`,hints:[`No service receives the request before it is checked.`,`The resource provider acts last.`],explanation:`ARM authenticates and authorizes first, then forwards to the relevant service. This is also the step where governance controls such as RBAC, locks and policies apply.`,commonMistakes:[`Placing the authorization after the creation.`,`Believing the portal contacts the provider directly.`],items:[{id:`o1`,text:`You send the request from the portal, the CLI or an API`},{id:`o2`,text:`Resource Manager authenticates and authorizes the request`},{id:`o3`,text:`Resource Manager forwards the request to the appropriate resource provider`},{id:`o4`,text:`The provider creates or modifies the resource`}]},"az-012":{title:`Design notes: find the errors`,objective:`Correct misconceptions about resource groups.`,statement:`A colleague wrote these design notes. **Some statements are wrong.** Spot them and choose the exact correction.`,hints:[`Three statements are wrong, two are right.`,`A group's tags are not applied to the resources it contains.`],explanation:`A resource exists in only one group, but you can add it to the group, remove it from it or move it. The group's tags are not inherited. A group's region can differ from that of its resources, even though the same location is recommended.`,commonMistakes:[`Relying on tag inheritance for billing.`,`Believing the group's region constrains that of the resources.`],lines:[{id:`l1`,text:`A resource can belong to several resource groups at the same time.`,faulty:{remedies:[{id:`r1-1`,text:`Each resource exists in a single resource group`},{id:`r1-2`,text:`A resource belongs to one group per subscription`},{id:`r1-3`,text:`It depends on the resource type`}]}},{id:`l2`,text:`Deleting a resource group deletes all the resources it contains.`},{id:`l3`,text:`The resources of a group automatically inherit the tags of that group.`,faulty:{remedies:[{id:`r3-1`,text:`Resources do not inherit the group's tags`},{id:`r3-2`,text:`Only virtual machines inherit tags`},{id:`r3-3`,text:`Tags are inherited after 24 hours`}]}},{id:`l4`,text:`You can move a resource from one resource group to another.`},{id:`l5`,text:`A resource must be in the same region as its resource group.`,faulty:{remedies:[{id:`r5-1`,text:`Regions can differ, but the same location is recommended`},{id:`r5-2`,text:`The group's region is ignored`},{id:`r5-3`,text:`You need two groups per region`}]}}]},"az-013":{title:`Each tool and what it offers`,objective:`Match an Azure tool to its nature.`,statement:`Match each tool to its description.`,hints:["`New-AzResourceGroup` is a PowerShell cmdlet.",`The management endpoint is management.azure.com.`],explanation:`All the portal functions are also available through PowerShell, CLI, REST API and SDKs, because they go through Resource Manager.`,commonMistakes:[`Confusing CLI and PowerShell.`,`Thinking Bicep is a command-line tool rather than a language.`],items:[{id:`m1`,text:`Azure portal`},{id:`m2`,text:`Azure CLI`},{id:`m3`,text:`Azure PowerShell`},{id:`m4`,text:`REST API`},{id:`m5`,text:`Bicep`}],options:[{id:`p1`,text:`Web graphical interface`},{id:`p2`,text:"Command-line commands, of the form `az ...`"},{id:`p3`,text:"PowerShell cmdlets, of the form `New-AzResourceGroup`"},{id:`p4`,text:`HTTP requests to the management.azure.com endpoint`},{id:`p5`,text:`Declarative language for infrastructure as code`}]},"az-014":{title:`Declarative syntaxes`,objective:`Distinguish declarative syntax from imperative scripts.`,statement:`Which of these use a **declarative syntax** ("here is what I want to get")? Several answers are possible.`,hints:[`In a declarative approach, you describe the final state.`,`A chain of commands describes the sequence, not the desired state.`],explanation:`ARM templates and Bicep files are declarative: you describe the properties of the infrastructure and Resource Manager determines how to get there, handling the order through dependencies.`,commonMistakes:[`Considering a command script to be declarative.`,`Forgetting that Bicep is declarative.`],choices:[{id:`c1`,text:`An ARM template in JSON`},{id:`c2`,text:`A Bicep file`},{id:`c3`,text:"A PowerShell script that chains `New-Az...` commands in a loop"},{id:`c4`,text:"A series of `az` commands run by hand"}]},"az-015":{title:`What does this command do?`,objective:`Read common Azure CLI commands.`,statement:`Match each command to its effect.`,hints:["The verbs `create`, `delete`, `set` are explicit.",`Deleting a group deletes its content.`],explanation:`Knowing how to read a command before running it is a security skill: you check the active subscription and the targeted group, especially for a deletion.`,commonMistakes:["Forgetting that `az account set` changes nothing in Azure, only the local context.",`Ignoring that the deletion is permanent.`],items:[{id:`m1`,text:`az login`},{id:`m2`,text:`az account set --subscription "Sub-Production"`},{id:`m3`,text:`az group create --name rg-test --location canadacentral`},{id:`m4`,text:`az group delete --name rg-test --yes`}],options:[{id:`p1`,text:`Authenticates the user to Azure`},{id:`p2`,text:`Sets the active subscription for the following commands`},{id:`p3`,text:`Creates a resource group`},{id:`p4`,text:`Deletes a resource group and all its resources`},{id:`p5`,text:`Displays the month's bill`}]},"az-016":{title:`Who is responsible: you or Microsoft?`,objective:`Distinguish the responsibilities between zonal and zone-redundant resources.`,statement:`Place each task on the side of whoever is responsible for it.`,hints:[`A zonal resource is pinned to a single zone.`,`A zone-redundant resource is spread by the service.`],explanation:`With zonal resources, you combine several deployments in different zones and manage replication and failover. With zone-redundant resources, Microsoft manages distribution, replication and failover.`,commonMistakes:[`Confusing the isolation of a zone with resilience.`,`Believing "zonal" means "replicated".`],items:[{id:`e1`,text:`Fail traffic over to another zone during a zone outage`},{id:`e2`,text:`Replicate data between zones`},{id:`e3`,text:`Spread requests between zones`},{id:`e4`,text:`Replicate data between zones automatically`},{id:`e5`,text:`Fail over automatically when a zone goes down`},{id:`e6`,text:`Distribute requests between zones`}],zones:[{id:`vous`,label:`You (zonal resource)`,description:`You manage the resilience`},{id:`ms`,label:`Microsoft (zone-redundant resource)`,description:`The service manages the resilience`}]},"az-017":{title:`What we know about management groups`,objective:`Remember the structural rules of management groups.`,statement:`Which of these statements about management groups is **correct**?`,hints:[`Think of the tree: each node has a single parent.`,`The depth is limited.`],explanation:`Management groups form a tree hierarchy: each group has a single parent and the depth is limited to 6 levels. They contain subscriptions (and other groups), not resources.`,commonMistakes:[`Imagining a graph with several parents.`,`Believing there is no depth limit.`],choices:[{id:`c1`,text:`A management group can only have one parent, and the hierarchy has at most 6 levels of depth`},{id:`c2`,text:`A management group can have several parents to share policies`},{id:`c3`,text:`Management groups directly contain resources`},{id:`c4`,text:`The management group hierarchy has unlimited depth`}]},"az-018":{title:`Assessment: design the Nordlys hierarchy`,objective:`Combine scope, lifecycle and governance in a single design.`,statement:`Nordlys Technologies must apply its governance rules. Place each need at the **narrowest** level that fits.`,hints:[`For each need, ask yourself which smallest container covers it.`,`Billing is separated at the subscription level.`],explanation:`The narrowest scope that meets the need limits the impact of mistakes. Cross-cutting governance: management group. Billing isolation: subscription. Shared lifecycle: resource group. One-off case: resource.`,commonMistakes:[`Systematically choosing the broadest level.`,`Forgetting that locks and roles are inherited downward.`],items:[{id:`e1`,text:`Forbid deployment outside the approved regions for the whole organization`},{id:`e2`,text:`Separate the billing and limits of the lab from those of production`},{id:`e3`,text:`Delete in a single operation everything that belongs to the Billing application`},{id:`e4`,text:`Prevent the modification of one specific shared virtual network`},{id:`e5`,text:`Apply a CanNotDelete lock to the whole rg-securite group`},{id:`e6`,text:`Give the Reader role to the audit team on all the production subscriptions`},{id:`e7`,text:`Assign an operator role on a single key vault`},{id:`e8`,text:`Isolate the costs of the test environments in a separate billing container`}],zones:[{id:`mg`,label:`Management group`},{id:`sub`,label:`Subscription`},{id:`rg`,label:`Resource group`},{id:`res`,label:`Resource`}]},"az-019":{title:`The default rules of a network security group`,objective:`Know which traffic an NSG allows or denies with no custom rule.`,statement:`A brand-new NSG contains six default rules. Place each one in the right column according to what it does.`,hints:[`Inbound traffic from the Internet is denied by default.`,`Outbound traffic to the Internet is allowed by default.`],explanation:`An unmodified NSG is not a complete "deny by default": it allows traffic inside the virtual network and outbound traffic to the Internet, and denies the rest. The default rules have the lowest priorities (highest numbers) so that custom rules are processed first.`,commonMistakes:[`Believing all outbound traffic is blocked by default.`,`Forgetting that traffic internal to the virtual network is allowed.`],items:[{id:`e1`,text:`AllowVNetInBound (priority 65000)`},{id:`e2`,text:`AllowAzureLoadBalancerInBound (priority 65001)`},{id:`e3`,text:`DenyAllInbound (priority 65500)`},{id:`e4`,text:`AllowVnetOutBound (priority 65000)`},{id:`e5`,text:`AllowInternetOutBound (priority 65001)`},{id:`e6`,text:`DenyAllOutBound (priority 65500)`}],zones:[{id:`allow`,label:`Allows`,description:`Allow action`},{id:`deny`,label:`Denies`,description:`Deny action`}]},"az-020":{title:`Who wins: priority 200 or 300?`,objective:`Apply the NSG "first match wins" rule.`,statement:`An NSG contains two rules for the same inbound traffic on port 3389: a **Deny** rule with priority **200** and an **Allow** rule with priority **300**. What happens?`,hints:[`The lowest numbers are processed first.`,`Once a rule matches, processing stops.`],explanation:`Rules are processed in ascending priority order: a small number has a higher priority. As soon as a rule matches, the following ones are no longer evaluated.`,commonMistakes:[`Reading "priority 300" as more important than "priority 200".`,`Believing all matching rules apply.`],choices:[{id:`c1`,text:`The traffic is denied: the priority 200 rule is evaluated first and processing stops`},{id:`c2`,text:`The traffic is allowed: the rule with the highest number wins`},{id:`c3`,text:`The traffic is allowed then denied: both rules apply`},{id:`c4`,text:`Azure refuses to create the second rule`}]},"az-021":{title:`NSG rule: RDP access open to the whole Internet`,objective:`Spot and fix an NSG rule that exposes an administration port.`,statement:`This NSG rule was created to allow the administration of a server. **Spot the dangerous lines** and choose the right fix. The Azure Bastion subnet is 10.0.1.0/26.`,hints:[`Who should be able to reach port 3389?`,`Azure Bastion connects from its own subnet.`],explanation:`Allowing port 3389 from "*" exposes the RDP service to the Internet, which is a target for brute force attacks. You must limit the source to the Bastion subnet (or a VPN) and never open 22 or 3389 from 0.0.0.0/0.`,commonMistakes:["Replacing `*` with `Internet`: it is equivalent in terms of risk.",`Only changing the priority: the rule would remain too permissive.`],lines:[{id:`l1`,text:`"name": "Autoriser-RDP",`},{id:`l2`,text:`"priority": 100,`},{id:`l3`,text:`"direction": "Inbound",`},{id:`l4`,text:`"protocol": "Tcp",`},{id:`l5`,text:`"sourceAddressPrefix": "*",`,faulty:{remedies:[{id:`r5-1`,text:`"sourceAddressPrefix": "10.0.1.0/26",`},{id:`r5-2`,text:`"sourceAddressPrefix": "Internet",`},{id:`r5-3`,text:`"sourceAddressPrefix": "0.0.0.0/0",`}]}},{id:`l6`,text:`"destinationPortRange": "3389",`},{id:`l7`,text:`"access": "Allow"`}]},"az-022":{title:`Sharing a VPN gateway in a hub-and-spoke`,objective:`Order the gateway transit configuration.`,statement:`Put the steps in order so that the spoke networks use the hub's VPN gateway.`,hints:[`The gateway must exist before it is shared.`,`Verification comes last.`],explanation:`The hub side allows transit through its gateway, the spoke side agrees to use the remote gateway. A spoke can only use one remote gateway, and transit is not available with Basic-tier VPN gateways.`,commonMistakes:[`Enabling "Use remote gateways" before the gateway exists.`,`Using a Basic gateway.`],items:[{id:`o1`,text:`Deploy the VPN gateway in the hub's GatewaySubnet`},{id:`o2`,text:`On the hub-to-spoke peering: enable "Allow gateway transit"`},{id:`o3`,text:`On the spoke-to-hub peering: enable "Use remote gateways"`},{id:`o4`,text:`Verify the effective routes on the network interface of a spoke VM`}]},"az-023":{title:`The settings of a hub-and-spoke peering`,objective:`Match a peering setting to its role.`,statement:`Match each item to its role in a hub-and-spoke topology.`,hints:[`Each setting lives on a specific side of the peering.`,`One of the gateway tiers is excluded from transit.`],explanation:`Transit avoids deploying a gateway in each spoke. It is configured on both sides of the peering and requires the gateway to exist first.`,commonMistakes:[`Reversing the two settings.`,`Thinking peering alone enables transit.`],items:[{id:`m1`,text:`Allow gateway transit (hub side)`},{id:`m2`,text:`Use remote gateways (spoke side)`},{id:`m3`,text:`GatewaySubnet`},{id:`m4`,text:`Basic-tier VPN gateway`}],options:[{id:`p1`,text:`Lets the peered networks use the hub's gateway`},{id:`p2`,text:`Makes the spoke use the peered network's gateway`},{id:`p3`,text:`Hub subnet that hosts the VPN or ExpressRoute gateway`},{id:`p4`,text:`Does not support gateway transit`},{id:`p5`,text:`Automatically encrypts all the peering traffic`}]},"az-024":{title:`Why go through Azure Bastion`,objective:`Recognize the benefits of Bastion for administration.`,statement:`What are the advantages of Azure Bastion for administering virtual machines? Several answers are possible.`,hints:[`Bastion is deployed in the virtual network and connects through a private address.`,`No agent or special client software is required on the VM.`],explanation:`Bastion offers RDP/SSH over TLS (443) without exposing administration ports to the Internet and without a public IP on the VM, or an agent. It is deployed per virtual network and also serves peered networks. It needs an AzureBastionSubnet of at least /26 for the Basic tier and above.`,commonMistakes:[`Believing an agent is necessary.`,`Keeping the VM's public IP "just in case".`],choices:[{id:`c1`,text:`VMs do not need a public IP address`},{id:`c2`,text:`The RDP or SSH connection goes through TLS on port 443`},{id:`c3`,text:`An agent must be installed on each VM`},{id:`c4`,text:`VMs are protected against port scanning`}]},"az-025":{title:`Service endpoint or private endpoint`,objective:`Distinguish service endpoint and private endpoint.`,statement:`Place each characteristic in the right column.`,hints:[`One of the two creates a private address in your network.`,`The one that targets an instance limits the risk of data leakage.`],explanation:`A private endpoint brings the service into your virtual network with a private address, targets a specific resource and is preferred for production and sensitive data. A service endpoint is simpler and free but keeps a public address.`,commonMistakes:[`Believing both create a private IP.`,`Forgetting DNS for a private endpoint.`],items:[{id:`e1`,text:`Remains a publicly routable IP address`},{id:`e2`,text:`Free`},{id:`e3`,text:`The PaaS service sees the virtual network as the traffic source`},{id:`e4`,text:`Creates a network interface with a private IP in your virtual network`},{id:`e5`,text:`Targets a specific instance of the PaaS resource`},{id:`e6`,text:`Requires additional DNS configuration`}],zones:[{id:`se`,label:`Service endpoint`,description:`Service Endpoint`},{id:`pe`,label:`Private endpoint`,description:`Private Endpoint / Private Link`}]},"az-026":{title:`Storage redundancy levels`,objective:`Match a redundancy option to how it works.`,statement:`Match each Azure Storage redundancy option to its description.`,hints:[`The "G" stands for geo-redundant: there is a secondary region.`,`The "Z" stands for availability zones.`],explanation:`Redundancy in the primary region is chosen between LRS (the least costly and least durable) and ZRS (recommended for high availability). The GRS/GZRS options add a secondary region; RA-* adds read access in that region.`,commonMistakes:[`Believing GRS allows reading in the secondary region.`,`Thinking LRS withstands the loss of a datacenter.`],items:[{id:`m1`,text:`LRS`},{id:`m2`,text:`ZRS`},{id:`m3`,text:`GRS`},{id:`m4`,text:`GZRS`},{id:`m5`,text:`RA-GRS`}],options:[{id:`p1`,text:`Three copies in a single datacenter of the primary region`},{id:`p2`,text:`Synchronous copies in three or more availability zones of the primary region`},{id:`p3`,text:`LRS in the primary region, then asynchronous copy to a secondary region`},{id:`p4`,text:`ZRS in the primary region, then asynchronous copy to a secondary region`},{id:`p5`,text:`GRS with read access possible in the secondary region`}]},"az-027":{title:`Do we survive a regional outage?`,objective:`Choose a redundancy according to the outage scenario.`,statement:`In the event of an **outage of the entire primary region**, does the data remain durable and recoverable (with an account failover if necessary)? Classify each option.`,hints:[`Only the options with a secondary region protect against a regional outage.`,`ZRS stays within a single region.`],explanation:`LRS and ZRS stay in the primary region: ZRS survives the loss of a datacenter or a zone, not that of the region. GRS and GZRS copy to a secondary region; an account failover may be required to restore writes.`,commonMistakes:[`Believing ZRS protects against a regional outage.`,`Forgetting the account failover to regain write access.`],items:[{id:`e1`,text:`LRS`},{id:`e2`,text:`ZRS`},{id:`e3`,text:`GRS`},{id:`e4`,text:`GZRS`}],zones:[{id:`oui`,label:`Survives the regional outage`},{id:`non`,label:`Does not survive the regional outage`}]},"az-028":{title:`Does redundancy protect against deletion?`,objective:`Distinguish hardware redundancy from protection against data changes.`,statement:`An administrator mistakenly deletes data from a storage account configured with GZRS. What can we say about the redundancy?`,hints:[`All the copies reflect the same current state.`,`Redundancy is for failures, not for human errors.`],explanation:`Redundancy protects against a hardware or infrastructure failure. Deletions and overwrites are replicated to all the copies: you need other mechanisms (backup, deletion protections, locks).`,commonMistakes:[`Confusing redundancy and backup.`,`Believing the secondary region keeps the old version.`],choices:[{id:`c1`,text:`It does not protect: deletions and overwrites are applied simultaneously to all the copies`},{id:`c2`,text:`It automatically restores the data from the secondary region`},{id:`c3`,text:`It keeps an intact copy in each zone`},{id:`c4`,text:`It prevents the deletion until replication is complete`}]},"az-029":{title:`In which order Azure Policy evaluates its effects`,objective:`Remember the evaluation order of Azure Policy effects.`,statement:`Put the effects in the order in which Azure Policy evaluates them for a create or update request.`,hints:[`A disabled effect is checked first.`,`deny is evaluated before audit to avoid double logging.`],explanation:"`disabled` is checked first. `append` and `modify` come next because they can alter the request and prevent a deny or an audit. `deny` precedes `audit` to avoid logging an unwanted resource twice.",commonMistakes:[`Believing audit precedes deny.`,`Forgetting that modify can change the result of a deny.`],items:[{id:`o1`,text:`disabled`},{id:`o2`,text:`append and modify`},{id:`o3`,text:`deny`},{id:`o4`,text:`audit`},{id:`o5`,text:`auditIfNotExists`}]},"az-030":{title:`Azure Policy effects`,objective:`Match an effect to its behavior.`,statement:`Match each Azure Policy effect to what it does.`,hints:[`Only one effect blocks the resource.`,`deployIfNotExists needs an identity to deploy.`],explanation:"Each policy definition has a single effect. You often start with `audit` to measure the impact before moving to an effect that applies changes.",commonMistakes:[`Confusing audit and deny.`,`Forgetting the managed identity of deployIfNotExists and modify.`],items:[{id:`m1`,text:`audit`},{id:`m2`,text:`deny`},{id:`m3`,text:`modify`},{id:`m4`,text:`deployIfNotExists`},{id:`m5`,text:`disabled`}],options:[{id:`p1`,text:`Flags the noncompliant resource without blocking it`},{id:`p2`,text:`Blocks the creation or update of a noncompliant resource`},{id:`p3`,text:`Adds, updates or removes properties (such as tags) during the request`},{id:`p4`,text:`Deploys a template if the related resource does not exist, with a managed identity`},{id:`p5`,text:`Turns off the evaluation of the rule`}]},"az-031":{title:`First deployment of a new policy`,objective:`Choose a cautious effect to introduce a policy.`,statement:`You are introducing a new policy in an existing production environment. What is the recommended approach?`,hints:[`An effect that blocks can break existing automations.`,`You want to measure first.`],explanation:`Starting with an observation effect shows which resources would be affected without breaking anything. Enforcement (deny, modify, deployIfNotExists) can disrupt scripts or autoscaling already in place.`,commonMistakes:[`Applying deny without testing.`,`Thinking audit is useless.`],choices:[{id:`c1`,text:`Start with audit or auditIfNotExists to observe the impact before applying deny, modify or deployIfNotExists`},{id:`c2`,text:`Apply deny right away to force compliance`},{id:`c3`,text:`Apply deployIfNotExists without a managed identity`},{id:`c4`,text:`Never use audit: it has no effect`}]},"az-032":{title:`Policy deployment plan: the errors`,objective:`Correct erroneous statements about Azure Policy deployment.`,statement:`A deployment plan contains statements. **Some are false.** Spot them and choose the exact correction.`,hints:[`Two statements are false.`,`Existing resources are not fixed by the assignment alone.`],explanation:"Automatic remediation only concerns resources that are created or updated; for existing ones, you launch a remediation task. The `DoNotEnforce` mode lets you evaluate without applying the effect, useful for testing a new assignment.",commonMistakes:[`Believing the assignment fixes the existing resources by itself.`,`Confusing DoNotEnforce and deletion.`],lines:[{id:`l1`,text:`For a deployIfNotExists policy, existing resources are fixed automatically as soon as it is assigned.`,faulty:{remedies:[{id:`r1-1`,text:`Existing resources are fixed with a remediation task`},{id:`r1-2`,text:`They can never be fixed`},{id:`r1-3`,text:`They must be recreated`}]}},{id:`l2`,text:`An assignment with a deployIfNotExists or modify effect requires a managed identity with the necessary roles.`},{id:`l3`,text:`The DoNotEnforce mode applies the policy effect but does not log it.`,faulty:{remedies:[{id:`r3-1`,text:`DoNotEnforce does not apply the effect on creation or update`},{id:`r3-2`,text:`DoNotEnforce deletes the policy`},{id:`r3-3`,text:`DoNotEnforce only disables the audit`}]}},{id:`l4`,text:`The excluded scopes (notScopes) of an assignment are neither evaluated nor counted in compliance.`}]},"az-033":{title:`Exclusion, exemption, remediation and enforcement`,objective:`Distinguish the Azure Policy scope mechanisms.`,statement:`Match each concept to its definition.`,hints:[`An exemption remains visible in the reports.`,`An exclusion removes the resource from the calculation.`],explanation:"An exclusion takes a resource out of the scope, an exemption waives it while keeping it visible. Remediation handles existing resources for the `modify` and `deployIfNotExists` effects.",commonMistakes:[`Confusing exclusion and exemption.`,`Believing a remediation task runs at every evaluation.`],items:[{id:`m1`,text:`Exclusion (notScopes)`},{id:`m2`,text:`Exemption`},{id:`m3`,text:`Remediation task`},{id:`m4`,text:`enforcementMode = DoNotEnforce`}],options:[{id:`p1`,text:`Some resources of the scope are neither evaluated nor counted`},{id:`p2`,text:`Evaluated but waived, visible as "Exempted", with possible expiration`},{id:`p3`,text:`Applies the template or operations to existing noncompliant resources`},{id:`p4`,text:`Evaluates the assignment without applying the effect on creation or update`}]},"az-034":{title:`Resource locks`,objective:`Match a lock to its effect.`,statement:`Match each item to what it means for resource locks.`,hints:[`ReadOnly is more restrictive than CanNotDelete.`,`A lock applies to management (ARM), not to the content of a storage account.`],explanation:`Locks apply to the management plane, are inherited by child resources and, in case of conflict, the most restrictive wins. They protect against mistakes, including those of administrators.`,commonMistakes:[`Believing a lock protects the data itself.`,`Using ReadOnly when modifications are expected.`],items:[{id:`m1`,text:`CanNotDelete`},{id:`m2`,text:`ReadOnly`},{id:`m3`,text:`Lock placed on a resource group`},{id:`m4`,text:`Locking and the data plane`}],options:[{id:`p1`,text:`Authorized users can read and modify, but not delete`},{id:`p2`,text:`Authorized users can read, but neither modify nor delete`},{id:`p3`,text:`Inherited by all the resources of the group, including those added later`},{id:`p4`,text:`Locks target management operations, not data operations`}]},"az-035":{title:`Production lock: two errors`,objective:`Fix a script that places the wrong lock type on the wrong group.`,statement:"Goal: **prevent the deletion of the `rg-prod` group without blocking the modifications** of the applications. **Spot the faulty lines** and choose the fixes.",hints:[`Is the targeted group the one in the goal?`,`ReadOnly also blocks modifications: is that intended?`],explanation:"The first lock protects `rg-test` instead of `rg-prod`. The second uses `ReadOnly`, which also forbids modifications, whereas the goal is only to prevent deletion: you need `CanNotDelete`.",commonMistakes:[`Using ReadOnly "to be safe".`,`Forgetting to check the targeted group before running.`],lines:[{id:`l1`,text:`az account set --subscription "Sub-Production"`},{id:`l2`,text:`az lock create --name verrou-prod --resource-group rg-test --lock-type CanNotDelete`,faulty:{remedies:[{id:`r2-1`,text:`Replace rg-test with rg-prod`},{id:`r2-2`,text:`Add --lock-type ReadOnly`},{id:`r2-3`,text:`Remove --resource-group`}]}},{id:`l3`,text:`az lock create --name verrou-secu --resource-group rg-securite --lock-type ReadOnly`,faulty:{remedies:[{id:`r3-1`,text:`Replace ReadOnly with CanNotDelete`},{id:`r3-2`,text:`Replace ReadOnly with Delete`},{id:`r3-3`,text:`Remove --lock-type`}]}}]},"az-036":{title:`Mission: which governance tool for which need?`,objective:`Choose between lock, policy and RBAC to meet a governance need.`,statement:`Nordlys is setting up its governance. For each need, choose the most appropriate tool.`,hints:[`Who has the right: RBAC. What must be complied with: policy. What must be protected against error: lock.`,`A rule that applies even to administrators is a lock.`],explanation:`RBAC answers "who can act". Azure Policy answers "what must be complied with" (and can audit or remediate). A lock answers "what must be protected against an accidental action", even for owners.`,commonMistakes:[`Using a role to enforce a configuration.`,`Relying on a policy to prevent a deletion.`],items:[{id:`e1`,text:`Prevent the accidental deletion of the rg-securite group`},{id:`e2`,text:`Deny any resource created outside the approved regions`},{id:`e3`,text:`Let the audit team read without modifying`},{id:`e4`,text:`Automatically add the Env tag inherited from the resource group`},{id:`e5`,text:`Prevent any modification of a shared virtual network`},{id:`e6`,text:`Let an operator manage the VMs of a single group`},{id:`e7`,text:`Flag the storage accounts that have no logging`},{id:`e8`,text:`Give a platform administrator the right to create resource groups`}],zones:[{id:`lock`,label:`Resource lock`,description:`Prevents deletion or modification`},{id:`policy`,label:`Azure Policy`,description:`Enforces or audits a configuration`},{id:`rbac`,label:`RBAC`,description:`Controls who can do what`}]}},o={"id-001":{title:`The three elements of a role assignment`,objective:`Break down an Azure RBAC role assignment.`,statement:`A role assignment combines three elements. Match each element to its role.`,hints:[`Who, what, where.`,`The scope is hierarchical.`],explanation:`A role assignment associates a principal, a role definition and a scope. Assignments are inherited down the hierarchy: a role assigned to a subscription applies to all its resource groups.`,commonMistakes:[`Confusing the role definition and the assignment.`,`Forgetting that the scope is inherited.`],items:[{id:`m1`,text:`Security principal`},{id:`m2`,text:`Role definition`},{id:`m3`,text:`Scope`}],options:[{id:`p1`,text:`Who receives the access: user, group, service principal or managed identity`},{id:`p2`,text:`What is allowed: the set of permitted actions`},{id:`p3`,text:`Where the access applies: management group, subscription, resource group or resource`}]},"id-002":{title:`Owner, Contributor, Reader`,objective:`Know the reach of the three fundamental roles.`,statement:`Match each built-in role to what it allows.`,hints:[`A single basic role cannot give access to others.`,`One role only manages access.`],explanation:`Contributor is often assigned by default, but it cannot grant access to others. Only Owner and User Access Administrator can. This separation limits the risk of privilege escalation.`,commonMistakes:[`Believing Contributor can assign roles.`,`Giving Owner for convenience.`],items:[{id:`m1`,text:`Owner`},{id:`m2`,text:`Contributor`},{id:`m3`,text:`Reader`},{id:`m4`,text:`User Access Administrator`}],options:[{id:`p1`,text:`Manages everything, including assigning roles to others`},{id:`p2`,text:`Creates and manages resources, but cannot assign roles`},{id:`p3`,text:`Views the resources without modifying anything`},{id:`p4`,text:`Manages user access to resources, without managing the resources themselves`}]},"id-003":{title:`Which role for the audit team?`,objective:`Apply least privilege to a read need.`,statement:"The audit team must view all the resources of the `Sub-Production` subscription without modifying anything. Which assignment is the most appropriate?",hints:[`The need is read-only.`,`An assignment at the subscription scope covers all the resources.`],explanation:`Reader at the subscription scope gives exactly the access needed. Assigning resource by resource is unmanageable and fragile; Contributor and Owner give far more than necessary.`,commonMistakes:[`Giving Contributor "just in case".`,`Assigning at a broader scope than necessary.`],choices:[{id:`c1`,text:`Reader, at the subscription scope`},{id:`c2`,text:`Contributor, at the subscription scope`},{id:`c3`,text:`Owner, at the root management group scope`},{id:`c4`,text:`Reader, at the scope of each resource, one by one`}]},"id-004":{title:`Assigning a role: the steps`,objective:`Order the steps to assign a role.`,statement:`Put the steps to assign an Azure role in order.`,hints:[`You decide before acting.`,`The assignment is the last step.`],explanation:`The recommended approach follows: the principal, the role, the scope, then the assignment. You must also have the right to assign roles yourself (Owner or User Access Administrator, for example).`,commonMistakes:[`Choosing the scope before knowing the need.`,`Forgetting to check your own permissions.`],items:[{id:`o1`,text:`Determine who needs access`},{id:`o2`,text:`Choose the appropriate role`},{id:`o3`,text:`Identify the necessary scope`},{id:`o4`,text:`Verify your own assignment rights`},{id:`o5`,text:`Assign the role`}]},"id-005":{title:`The smallest scope that is enough`,objective:`Choose the minimum scope for each need.`,statement:`For each need, place it at the narrowest assignment scope that covers it.`,hints:[`The narrower the scope, the more limited the risk.`,`A single resource calls for an assignment on that resource.`],explanation:`Least privilege also applies to the scope: you assign at the lowest level that meets the need, because the assignment is inherited downward.`,commonMistakes:[`Assigning at the subscription "to simplify".`,`Forgetting inheritance.`],items:[{id:`e1`,text:`Read one specific key vault`},{id:`e2`,text:`Manage all the VMs of the rg-app group`},{id:`e3`,text:`View all the subscriptions of the organization for compliance`},{id:`e4`,text:`Manage all the resource groups of a test subscription`}],zones:[{id:`mg`,label:`Management group`},{id:`sub`,label:`Subscription`},{id:`rg`,label:`Resource group`},{id:`res`,label:`Resource`}]},"id-006":{title:`Groups rather than individual users`,objective:`Justify assigning roles to groups.`,statement:`Why do we preferably assign roles to security groups rather than to individual users? Several answers are possible.`,hints:[`A group does not change the scope.`,`Think about the employee lifecycle.`],explanation:`Managing access by group simplifies staff movements, reduces the number of assignments and makes reviews easier. The group does not change the scope of the assignment in any way.`,commonMistakes:[`Believing a group widens or bypasses the scope.`],choices:[{id:`c1`,text:`Joiners and leavers are handled through group membership, without touching the assignments`},{id:`c2`,text:`The number of role assignments to manage stays low`},{id:`c3`,text:`A group bypasses the limits of the scope`},{id:`c4`,text:`The access audit is more readable`}]},"id-007":{title:`Over-broad assignment: spot and fix`,objective:`Fix an assignment command that violates least privilege.`,statement:"The `app-factures` application must only **read the blobs** of the `stfacturesprod` account. **Spot the faulty line** and choose the fix.",hints:[`What is the real need?`,`A data role exists for reading blobs.`],explanation:`Owner on the subscription gives total control over everything. The need is limited to reading the blobs of one account: a data role such as Storage Blob Data Reader, at the account scope, is enough.`,commonMistakes:[`Choosing Reader: it does not give access to the blob data.`,`Choosing Contributor: too broad.`],lines:[{id:`l1`,text:`az login --identity`},{id:`l2`,text:`az role assignment create --assignee $APP_ID --role "Owner" --scope "/subscriptions/$SUB"`,faulty:{remedies:[{id:`r2-1`,text:`--role "Storage Blob Data Reader" with the scope of the stfacturesprod account`},{id:`r2-2`,text:`--role "Contributor" with the same scope`},{id:`r2-3`,text:`--role "Reader" on the subscription`}]}},{id:`l3`,text:`az role assignment list --assignee $APP_ID --output table`}]},"id-008":{title:`Security platform roles`,objective:`Match a Sentinel role to an analyst profile.`,statement:`Match each profile to the most suitable Microsoft Sentinel role.`,hints:[`Reader reads, Responder acts on incidents, Contributor builds.`,`One role is dedicated to playbooks.`],explanation:`Sentinel separates reading, incident response and detection engineering. Tier 1 analysts get the Responder role, and detection engineers get Contributor, rather than Owner or Azure Contributor.`,commonMistakes:[`Giving Contributor to all the analysts.`,`Forgetting Playbook Operator to run a playbook.`],items:[{id:`m1`,text:`Analyst who views incidents and data, without changing anything`},{id:`m2`,text:`Analyst who manages incidents (assign, close, comment)`},{id:`m3`,text:`Engineer who creates and modifies analytics rules and workbooks`},{id:`m4`,text:`Person who manually runs playbooks`}],options:[{id:`p1`,text:`Microsoft Sentinel Reader`},{id:`p2`,text:`Microsoft Sentinel Responder`},{id:`p3`,text:`Microsoft Sentinel Contributor`},{id:`p4`,text:`Microsoft Sentinel Playbook Operator`}]},"id-009":{title:`Role to run a playbook`,objective:`Choose the minimum role to run a playbook manually.`,statement:`An analyst must manually run a playbook on an incident. Which minimum role does she need for this specific action, in addition to her incident response rights?`,hints:[`A Sentinel role is designed for this.`,`Contributor on Logic Apps allows modifying the playbook.`],explanation:`Playbook Operator allows running a playbook without modifying it. Logic App Contributor allows modifying or managing playbooks, which goes beyond the need.`,commonMistakes:[`Giving Logic App Contributor to an analyst who only needs to run.`],choices:[{id:`c1`,text:`Microsoft Sentinel Playbook Operator on the playbook's resource group`},{id:`c2`,text:`Logic App Contributor on the whole subscription`},{id:`c3`,text:`Owner on the workspace`},{id:`c4`,text:`No additional role: Responder is always enough`}]},"id-010":{title:`Deploying a conditional access policy safely`,objective:`Order a cautious conditional access deployment.`,statement:`Put the steps of a cautious deployment of a new conditional access policy in order.`,hints:[`You observe before enforcing.`,`Emergency accounts are excluded from the definition.`],explanation:`Report-only mode evaluates the policy without enforcing it. You validate the impact before enabling, and you exclude the emergency accounts to avoid locking yourself out of the tenant.`,commonMistakes:[`Enabling directly.`,`Forgetting to exclude the emergency accounts.`],items:[{id:`o1`,text:`Define the policy and its exclusions for the emergency accounts`},{id:`o2`,text:`Enable the policy in report-only mode`},{id:`o3`,text:`Analyze the impact in the reports`},{id:`o4`,text:`Enable the policy`}]},"id-011":{title:`Emergency accounts and conditional access`,objective:`Justify excluding the emergency accounts.`,statement:`Why do we exclude at least one emergency (break-glass) account from the conditional access policies?`,hints:[`Think of a configuration error that blocks all the administrators.`,`Such an account must stay rarely used and monitored.`],explanation:`An emergency account is the last escape hatch. It must be excluded from the policies that could block access, be strongly protected, rarely used, and its use must trigger an alert.`,commonMistakes:[`Using the emergency account day to day.`,`Not monitoring its sign-in.`],choices:[{id:`c1`,text:`To keep an administrator access if a misconfigured policy locks everyone out`},{id:`c2`,text:`So that this account is used day to day`},{id:`c3`,text:`To disable its audit`},{id:`c4`,text:`Because these accounts do not need a password`}]},"id-012":{title:`Blocking policy: three traps`,objective:`Fix a dangerous conditional access policy.`,statement:`This policy must **block access from outside Canada** without any risk of lockout. **Spot the faulty lines** and choose the fixes.`,hints:[`Who keeps access if the policy is misconfigured?`,`How do you validate before enforcing?`],explanation:`A blocking policy on all users with no exclusion exposes you to lockout. You exclude the emergency accounts and start in report-only mode, then enable after analysis.`,commonMistakes:[`Excluding all the administrators: it opens the door to the most targeted accounts.`,`Enabling without validation.`],lines:[{id:`l1`,text:`Name: Block outside Canada`},{id:`l2`,text:`Included users: All users`},{id:`l3`,text:`Excluded users: none`,faulty:{remedies:[{id:`r3-1`,text:`Exclude the emergency account`},{id:`r3-2`,text:`Exclude all the administrators`},{id:`r3-3`,text:`Exclude the guests`}]}},{id:`l4`,text:`Target applications: All cloud apps`},{id:`l5`,text:`Conditions: location = any location except Canada`},{id:`l6`,text:`Access control: Block`},{id:`l7`,text:`State: Enabled`,faulty:{remedies:[{id:`r7-1`,text:`State: Report-only, then enable after validation`},{id:`r7-2`,text:`State: Disabled permanently`},{id:`r7-3`,text:`State: Enabled, without validation`}]}}]},"id-013":{title:`Workload identities`,objective:`Know which objects classic conditional access does not cover.`,statement:`Does a conditional access policy targeting "All users" also protect service principals (workload identities)?`,hints:[`A service principal is not a user.`,`A dedicated variant exists.`],explanation:`User policies do not apply to service principals. Conditional access for workload identities is a separate feature, with its own licensing requirements.`,commonMistakes:[`Assuming user policies also cover applications.`],choices:[{id:`c1`,text:`No: service principals require conditional access for workload identities`},{id:`c2`,text:`Yes: all identity types are covered automatically`},{id:`c3`,text:`Yes, but only outside Canada`},{id:`c4`,text:`No: they are never covered, whatever you configure`}]},"id-014":{title:`PIM: eligible or active`,objective:`Distinguish the assignment types in PIM.`,statement:`Match each Privileged Identity Management concept to its definition.`,hints:[`Eligible means "can request".`,`Activation is time-limited.`],explanation:`PIM turns a permanent privilege into an on-demand privilege: the role becomes active only for the necessary duration. PIM requires Microsoft Entra ID P2 or ID Governance.`,commonMistakes:[`Confusing eligible and active.`,`Forgetting the required license.`],items:[{id:`m1`,text:`Eligible assignment`},{id:`m2`,text:`Active assignment`},{id:`m3`,text:`Activation`},{id:`m4`,text:`Time-bound assignment`}],options:[{id:`p1`,text:`The user can activate the role as needed, with possible conditions`},{id:`p2`,text:`The role is available without activation`},{id:`p3`,text:`Temporary request for the role, which may require MFA, justification or approval`},{id:`p4`,text:`Has a start and end date`}]},"id-015":{title:`Why PIM reduces risk`,objective:`Explain the value of just-in-time access.`,statement:`What are the advantages of an eligible administrator access rather than a permanent one? Several answers are possible.`,hints:[`The privilege only exists during the activation.`,`PIM adds controls, it does not remove any.`],explanation:`Just-in-time access limits the attack surface over time, logs the activations and lets you add MFA, justification and approval.`,commonMistakes:[`Believing PIM removes the authentication controls.`],choices:[{id:`c1`,text:`The window during which a compromised account is powerful is reduced`},{id:`c2`,text:`Activations leave an audit trail`},{id:`c3`,text:`The administrator never needs MFA again`},{id:`c4`,text:`You can require an approval or a justification before getting the role`}]},"id-016":{title:`Who can manage Azure roles in PIM?`,objective:`Know the prerequisite for managing Azure resource roles in PIM.`,statement:`Who can manage Azure resource role assignments in PIM?`,hints:[`Only certain roles can assign access.`,`Contributor cannot assign roles.`],explanation:`For Azure resources, only Owner and User Access Administrator can manage assignments in PIM, which reflects the general RBAC rule on role assignment.`,commonMistakes:[`Believing Contributor is enough.`],choices:[{id:`c1`,text:`Users with the Owner or User Access Administrator role on the resource`},{id:`c2`,text:`Any Contributor`},{id:`c3`,text:`Only Readers`},{id:`c4`,text:`Only a tenant administrator, unrelated to Azure roles`}]},"id-017":{title:`Mission: harden Nordlys administrator access`,objective:`Choose the appropriate control for each privileged access risk.`,statement:`Nordlys is reviewing its administrator access. For each situation, choose the most appropriate control.`,hints:[`When: PIM. Under which conditions: conditional access. What and where: RBAC. And if everything fails: emergency account.`,`An emergency account is not managed through PIM.`],explanation:`These controls complement each other: RBAC sets the perimeter, PIM limits it in time, conditional access frames the sign-in, and the emergency account guarantees a recourse.`,commonMistakes:[`Using conditional access to set the scope of a role.`,`Replacing the emergency account with an eligible administrator in PIM.`],items:[{id:`e1`,text:`An administrator should only be Owner for a few hours during a change`},{id:`e2`,text:`Require a compliant device to access the Azure portal`},{id:`e3`,text:`An operator only manages the VMs of one resource group`},{id:`e4`,text:`Keep an access if a policy locks out all the administrators`},{id:`e5`,text:`Require a justification and an approval before activating a role`},{id:`e6`,text:`Block administrator access from an unauthorized country`}],zones:[{id:`pim`,label:`PIM`,description:`On-demand, time-limited access`},{id:`ca`,label:`Conditional access`,description:`Access conditions at sign-in`},{id:`rbac`,label:`RBAC and scope`,description:`Suitable role and perimeter`},{id:`bg`,label:`Emergency account`,description:`Monitored last resort`}]},"id-018":{title:`Assessment: review of a role assignment`,objective:`Fix the gaps in a privileged assignment.`,statement:"During a review, you are handed this access description for the account `a.gagnon`, who must only **manage the VMs of rg-app** a few hours per week. **Spot the two gaps** and choose the fixes.",hints:[`The role and the scope are both too broad.`,`The assignment type is already suitable.`],explanation:"Owner on the subscription far exceeds the need. Virtual Machine Contributor on `rg-app` respects least privilege, and PIM eligibility with MFA is already a good control to keep.",commonMistakes:[`Fixing the role but not the scope.`,`Removing PIM, which was correct.`],lines:[{id:`l1`,text:`Principal: a.gagnon@nordlys.example`},{id:`l2`,text:`Role: Owner`,faulty:{remedies:[{id:`r2-1`,text:`Role: Virtual Machine Contributor`},{id:`r2-2`,text:`Role: Reader`},{id:`r2-3`,text:`Role: User Access Administrator`}]}},{id:`l3`,text:`Scope: Sub-Production subscription`,faulty:{remedies:[{id:`r3-1`,text:`Scope: rg-app resource group`},{id:`r3-2`,text:`Scope: root management group`},{id:`r3-3`,text:`Scope: a random single resource`}]}},{id:`l4`,text:`Type: eligible in PIM, 4-hour activation with MFA`}]}},s={"obs-001":{title:`The three types of Azure logs`,objective:`Distinguish the activity log, resource logs and Entra logs.`,statement:`Match each log to what it records.`,hints:[`The first concerns what is done to resources, the second what resources do.`,`The third concerns identity.`],explanation:`Each source answers a different question: who modified a resource, what the resource did, who authenticated. Detection relies on all three.`,commonMistakes:[`Believing the activity log contains data operations.`],items:[{id:`m1`,text:`Azure Activity log`},{id:`m2`,text:`Resource logs`},{id:`m3`,text:`Microsoft Entra sign-in logs (SigninLogs)`}],options:[{id:`p1`,text:`Operations on the management plane of a subscription's resources`},{id:`p2`,text:`Internal operations of a resource, collected through a diagnostic setting`},{id:`p3`,text:`Authentications of users and applications`}]},"obs-002":{title:`Where to send a diagnostic setting`,objective:`Know the destinations of a diagnostic setting.`,statement:`To which destinations can a diagnostic setting send logs? Several answers are possible.`,hints:[`Three main destinations exist, plus partner solutions.`,`GitHub is not one of them.`],explanation:`Log Analytics is for analysis and KQL queries, storage for archiving, Event Hubs for streaming to external systems. Partner solutions are also supported.`,commonMistakes:[`Forgetting that resource logs are not collected until a setting exists.`],choices:[{id:`c1`,text:`A Log Analytics workspace`},{id:`c2`,text:`A storage account`},{id:`c3`,text:`An Event Hub`},{id:`c4`,text:`A GitHub repository`}]},"obs-003":{title:`Choose the destination according to the need`,objective:`Match a need to the suitable destination.`,statement:`Place each need in the most appropriate destination.`,hints:[`KQL implies Log Analytics.`,`An external SIEM receives the events as a stream.`],explanation:`You choose the destination according to the use: querying and detection in Log Analytics, archiving in storage, continuous streaming outward through Event Hubs.`,commonMistakes:[`Sending everything to storage hoping to do detection.`],items:[{id:`e1`,text:`Hunt a threat with KQL`},{id:`e2`,text:`Trigger a Sentinel analytics rule`},{id:`e3`,text:`Keep logs for a retention obligation without querying them`},{id:`e4`,text:`Continuously send the events to a third-party SIEM`}],zones:[{id:`law`,label:`Log Analytics`,description:`Queries, alerts, Sentinel`},{id:`sa`,label:`Storage account`,description:`Low-cost archiving`},{id:`eh`,label:`Event Hub`,description:`Streaming to an external tool`}]},"obs-004":{title:`Azure Monitor Agent and collection rule`,objective:`Match the components of modern collection.`,statement:`Match each component to its role.`,hints:[`The rule only applies to the associated machines.`,`The agent executes, the rule decides.`],explanation:`AMA replaces the older agents. The rule (DCR) centralizes the configuration, which lets you reuse it for many machines through associations.`,commonMistakes:[`Installing the agent without associating a rule: nothing is collected.`],items:[{id:`m1`,text:`Azure Monitor Agent (AMA)`},{id:`m2`,text:`Data collection rule (DCR)`},{id:`m3`,text:`Data collection rule association (DCRA)`},{id:`m4`,text:`Log Analytics workspace`}],options:[{id:`p1`,text:`Collects the data on the virtual machine or server`},{id:`p2`,text:`Describes which data to collect, how to transform it and where to send it`},{id:`p3`,text:`Links a collection rule to a machine`},{id:`p4`,text:`Destination where the data is stored and queried`}]},"obs-005":{title:`Collect the security events of a Windows server`,objective:`Order the setup of collection with AMA.`,statement:`Put the steps to collect the Windows events of a server into Sentinel in order.`,hints:[`The destination exists before the rule.`,`You verify before querying.`],explanation:`The Heartbeat table confirms that the agent is communicating. Then SecurityEvent should fill up. An absence of data after the association is a classic troubleshooting case.`,commonMistakes:[`Querying before checking the agent connection.`],items:[{id:`o1`,text:`Create or choose the Log Analytics workspace with Sentinel`},{id:`o2`,text:`Create a collection rule with the Windows Events source`},{id:`o3`,text:`Associate the rule with the server`},{id:`o4`,text:`Verify that the agent sends heartbeats (Heartbeat)`},{id:`o5`,text:`Query the SecurityEvent table`}]},"obs-006":{title:`No data after the association`,objective:`Diagnose a silent collection.`,statement:"A server has been associated with a collection rule for an hour, but `SecurityEvent` remains empty for this machine. What is the most relevant first check?",hints:[`A simple test confirms whether the agent is communicating.`,`Start with the simplest thing.`],explanation:`Heartbeat is the agent's proof of life. Without a heartbeat, the problem is connectivity or the agent; with a heartbeat, you need to check the rule, its filters and the association.`,commonMistakes:[`Changing several things at once.`],choices:[{id:`c1`,text:`Look in Heartbeat to see whether the machine sends heartbeats`},{id:`c2`,text:`Delete the workspace and recreate it`},{id:`c3`,text:`Disable Sentinel`},{id:`c4`,text:`Change the time zone of the workspace`}]},"obs-007":{title:`A collection rule that is too chatty`,objective:`Reduce the ingested volume by filtering at the source.`,statement:`This rule collects **all** the events of the Security log, which is expensive. You only want the failed (4625) and successful (4624) logons. **Spot the line to fix.**`,hints:[`XPath queries filter at the source.`,`You need to name the wanted event IDs.`],explanation:`An XPath filter limits the collection to the wanted event IDs, which reduces the ingestion cost. A filter that is too broad could hide detections: you choose it along with the detection needs.`,commonMistakes:[`Filtering by severity level, which does not match the goal.`],lines:[{id:`l1`,text:`"dataSources": {`},{id:`l2`,text:`  "windowsEventLogs": [{`},{id:`l3`,text:`    "name": "securite",`},{id:`l4`,text:`    "streams": ["Microsoft-SecurityEvent"],`},{id:`l5`,text:`    "xPathQueries": ["Security!*"]`,faulty:{remedies:[{id:`r5-1`,text:`"Security!*[System[(EventID=4624 or EventID=4625)]]"`},{id:`r5-2`,text:`"Security!*[System[(Level=1)]]"`},{id:`r5-3`,text:`"System!*"`}]}},{id:`l6`,text:`  }]`},{id:`l7`,text:`}`}]},"obs-008":{title:`Ingestion-time transformation`,objective:`Know what an ingestion transformation allows.`,statement:`What are typical uses of a collection rule transformation? Several answers are possible.`,hints:[`The transformation acts during ingestion.`,`It does not rewrite the past.`],explanation:`A transformation applies to incoming data, before it is written to the table. It lets you reduce costs and limit sensitive data, but does not change what is already stored.`,commonMistakes:[`Believing a transformation fixes the history.`],choices:[{id:`c1`,text:`Filter out useless rows before storage`},{id:`c2`,text:`Remove or mask sensitive columns`},{id:`c3`,text:`Enrich or normalize data on arrival`},{id:`c4`,text:`Retroactively modify data that is already stored`}]},"obs-009":{title:`Table plans`,objective:`Match a table plan to its uses.`,statement:`Match each Log Analytics table plan to its description.`,hints:[`Detections require the most complete plan.`,`One plan rules out alerts.`],explanation:`The plan is chosen table by table according to the value of the data. The tables that feed detection rules must stay on Analytics.`,commonMistakes:[`Moving to Basic a table used by an analytics rule.`],items:[{id:`m1`,text:`Analytics`},{id:`m2`,text:`Basic`},{id:`m3`,text:`Auxiliary`}],options:[{id:`p1`,text:`Full analysis, unlimited queries, alerts and detections`},{id:`p2`,text:`High-volume logs at reduced cost, limited queries`},{id:`p3`,text:`Low-value data to keep at very low cost; alerts do not work on it`}]},"obs-010":{title:`Which table to switch to Auxiliary?`,objective:`Choose a candidate table for a cheaper plan.`,statement:`Which of these tables is the best candidate for a cheaper plan, given that no rule uses it?`,hints:[`A cheaper plan limits alerts.`,`Keep Analytics for what feeds detections.`],explanation:`The detection tables stay on Analytics. A bulky log that is rarely consulted and has no associated rule is a good candidate. The plan change is limited to once a week per table.`,commonMistakes:[`Switching a detection table to save money.`],choices:[{id:`c1`,text:`Very high-volume network flow logs rarely consulted for investigations`},{id:`c2`,text:`SigninLogs, used by several detection rules`},{id:`c3`,text:`SecurityEvent, used for brute force detection`},{id:`c4`,text:`AuditLogs, basis of privilege rules`}]},"obs-011":{title:`Interactive and total retention`,objective:`Match the retention concepts to their bounds.`,statement:`Match each concept to its description.`,hints:[`Sentinel raises the default to 90 days.`,`Long-term data cannot be queried like interactive data.`],explanation:`You need to plan the retention duration according to investigation and compliance needs. Beyond interactive retention, a search job makes the data accessible.`,commonMistakes:[`Believing total retention is interactive.`],items:[{id:`m1`,text:`Interactive retention (Analytics)`},{id:`m2`,text:`Total retention`},{id:`m3`,text:`Default value of a workspace`},{id:`m4`,text:`Search job`}],options:[{id:`p1`,text:`From 4 to 730 days, full queries`},{id:`p2`,text:`Up to 12 years, the part beyond interactive is long-term`},{id:`p3`,text:`30 days (90 days with Sentinel)`},{id:`p4`,text:`Lets you search the long-term data`}]},"obs-012":{title:`A 2-year retention requirement`,objective:`Size interactive and total retention.`,statement:"Nordlys's policy requires 90 days of fast searches and 2 years of total retention for `SigninLogs`. Which configuration meets the requirement at the lowest reasonable cost?",hints:[`Two years equal 730 days.`,`Interactive retention costs more than long-term retention.`],explanation:`The 90-day interactive retention covers the frequent searches. The remaining 640 days are kept long-term, cheaper, and remain accessible through search.`,commonMistakes:[`Keeping 730 days interactive without need.`],choices:[{id:`c1`,text:`Interactive retention of 90 days, total retention of 730 days`},{id:`c2`,text:`Interactive retention of 730 days, total retention of 730 days`},{id:`c3`,text:`Interactive retention of 30 days, total retention of 90 days`},{id:`c4`,text:`Interactive retention of 90 days, total retention of 90 days`}]},"obs-013":{title:`One workspace or several?`,objective:`Reason about workspace design.`,statement:`Which criteria justify separating logs into several workspaces? Several answers are possible.`,hints:[`Separating adds complexity for queries and detections.`,`Some differences are handled per table or through table-level access.`],explanation:`A single workspace simplifies detection and hunting. You separate for data residency, access separation or governance reasons, not out of habit or because there are several subscriptions.`,commonMistakes:[`Creating one workspace per subscription as a reflex.`],choices:[{id:`c1`,text:`Data residency requirements in a specific region`},{id:`c2`,text:`Strict access separation between teams that must not see the same data`},{id:`c3`,text:`The mere fact of having several subscriptions`},{id:`c4`,text:`Very different retention constraints that cannot be handled per table`}]},"obs-014":{title:`Enabling an alert on a table`,objective:`Order the checks before basing a rule on a table.`,statement:`Put in order what you check before building an analytics rule on a table.`,hints:[`The data before the query.`,`You test before enabling.`],explanation:`A rule produces nothing without data, does not run on an Auxiliary table, and cannot look back further than the available retention.`,commonMistakes:[`Writing the query before checking the data.`],items:[{id:`o1`,text:`Confirm that the data arrives in the table`},{id:`o2`,text:`Verify that the table is on the Analytics plan`},{id:`o3`,text:`Confirm that retention covers the rule's lookback period`},{id:`o4`,text:`Write and test the query`},{id:`o5`,text:`Enable the rule`}]},"obs-015":{title:`Diagnosing a silent table in KQL`,objective:`Fix a query that detects silent machines.`,statement:`This query must list the machines that have not sent a heartbeat for **more than 30 minutes**. **Spot the faulty line.**`,hints:[`Silent means the last heartbeat is old.`,`Older than 30 minutes is expressed as "less than ago(30m)".`],explanation:"A machine is silent if its last heartbeat is older than the threshold. The comparison `LastBeat < ago(30m)` expresses it, after summarizing per machine.",commonMistakes:[`Reversing the direction of the comparison.`,`Filtering before the summary and losing the silent machines.`],lines:[{id:`l1`,text:`Heartbeat`},{id:`l2`,text:`| summarize LastBeat = max(TimeGenerated) by Computer`},{id:`l3`,text:`| where LastBeat > ago(30m)`,faulty:{remedies:[{id:`r3-1`,text:`| where LastBeat < ago(30m)`},{id:`r3-2`,text:`| where LastBeat == ago(30m)`},{id:`r3-3`,text:`| where TimeGenerated < ago(30m)`}]}},{id:`l4`,text:`| order by LastBeat asc`}]},"obs-016":{title:`Which measure for which need?`,objective:`Match a signal to the log source that provides it.`,statement:`For each investigation question, place the log source that contains the answer.`,hints:[`Configuration changes are in the activity log.`,`What a resource does is in its resource logs.`],explanation:`Knowing the source avoids querying the wrong tables: management in the activity log, identity in the sign-ins, internal behavior in the resource logs.`,commonMistakes:[`Looking for a configuration deletion in SigninLogs.`],items:[{id:`e1`,text:`Who deleted the diagnostic setting of rg-sec?`},{id:`e2`,text:`From which IP address did the user authenticate?`},{id:`e3`,text:`Which requests did the firewall deny?`},{id:`e4`,text:`Which VM was created in rg-prod?`},{id:`e5`,text:`Which application obtained a token for this user?`}],zones:[{id:`act`,label:`Azure Activity log`},{id:`sign`,label:`Entra sign-in logs`},{id:`res`,label:`Resource logs`}]},"obs-017":{title:`A deleted diagnostic setting`,objective:`Recognize the risk of a logging blind spot.`,statement:"In the Nordlys incident, the account `svc-backup2` deletes a diagnostic setting. Why is this worrying from a detection standpoint?",hints:[`The setting controls the sending of logs, not their past storage.`,`An attacker may try to stay invisible.`],explanation:`Deleting a diagnostic setting cuts future collection and is used to hide actions. It is a defense evasion technique: you create an alert on deletion operations in the activity log.`,commonMistakes:[`Believing the past logs disappear.`],choices:[{id:`c1`,text:`The resource stops sending its logs, which creates a blind spot for the following actions`},{id:`c2`,text:`It deletes the logs already stored`},{id:`c3`,text:`It disables multifactor authentication`},{id:`c4`,text:`It changes the region of the workspace`}]},"obs-018":{title:`Assessment: monitor diagnostic deletions`,objective:`Fix a query that detects diagnostic setting deletions.`,statement:`This query must find the **deletions** of diagnostic settings in the last 24 hours. **Spot the faulty line.**`,hints:[`The first line is already correct.`,`Which operation corresponds to a deletion?`],explanation:"The 24-hour window is correct. The operation to look for is `DIAGNOSTICSETTINGS/DELETE`, not WRITE. In our dataset, `svc-backup2` produces one in rg-sec.",commonMistakes:[`Confusing WRITE (creation or modification) and DELETE.`],lines:[{id:`l1`,text:`AzureActivity`},{id:`l2`,text:`| where TimeGenerated > ago(24h)`},{id:`l3`,text:`| where OperationNameValue has "DIAGNOSTICSETTINGS/WRITE"`,faulty:{remedies:[{id:`r3-1`,text:`| where OperationNameValue has "DIAGNOSTICSETTINGS/DELETE"`},{id:`r3-2`,text:`| where OperationNameValue has "DIAGNOSTICSETTINGS/READ"`},{id:`r3-3`,text:`| where OperationNameValue == "DELETE"`}]}},{id:`l4`,text:`| project TimeGenerated, Caller, ResourceGroup, OperationNameValue`}]}},c={"sen-001":{title:`The components of Microsoft Sentinel`,objective:`Match each component to its role in a SOC.`,statement:`Match each Sentinel component to its role.`,hints:[`The connector is upstream, the incident downstream.`,`Two components automate, at different levels.`],explanation:`The Sentinel cycle: collection (connector), detection (rule), investigation (incident), response (automation and playbook).`,commonMistakes:[`Confusing automation rule and playbook.`],items:[{id:`m1`,text:`Data connector`},{id:`m2`,text:`Analytics rule`},{id:`m3`,text:`Incident`},{id:`m4`,text:`Automation rule`},{id:`m5`,text:`Playbook`}],options:[{id:`p1`,text:`Brings the logs of a source into the workspace`},{id:`p2`,text:`Runs a query and generates alerts when it finds something`},{id:`p3`,text:`Groups alerts and entities to investigate`},{id:`p4`,text:`Applies simple actions to incidents (tag, severity, assignment)`},{id:`p5`,text:`Logic Apps flow for more complex responses`}]},"sen-002":{title:`Setting up Sentinel`,objective:`Order the steps of a first setup.`,statement:`Put the steps of a Sentinel setup in order.`,hints:[`The workspace comes before Sentinel.`,`Without data, the rules are useless.`],explanation:`You start with the highest-value sources (identity, Azure activity) then add rules. The final validation confirms that the whole chain works.`,commonMistakes:[`Enabling rules before having data.`],items:[{id:`o1`,text:`Choose or create the Log Analytics workspace`},{id:`o2`,text:`Enable Microsoft Sentinel on this workspace`},{id:`o3`,text:`Connect the priority sources (identity, Azure activity)`},{id:`o4`,text:`Enable rules from the templates`},{id:`o5`,text:`Validate that alerts and incidents are created`}]},"sen-003":{title:`Types of analytics rules`,objective:`Distinguish two families of rules.`,statement:`Match each rule type to its description.`,hints:[`One is written in KQL by you.`,`The other turns existing alerts into incidents.`],explanation:`Scheduled rules are the core of detection engineering. Rules that create incidents from Microsoft alerts avoid losing alerts from other products.`,commonMistakes:[`Believing a rule deletes data.`],items:[{id:`m1`,text:`Scheduled rule`},{id:`m2`,text:`Microsoft Security rule`}],options:[{id:`p1`,text:`Runs a KQL query at regular intervals over a lookback period`},{id:`p2`,text:`Creates incidents from the alerts of other Microsoft security products`},{id:`p3`,text:`Automatically deletes the data of a table`}]},"sen-004":{title:`Lookback window and ingestion delay`,objective:`Size the lookback period of a scheduled rule.`,statement:`A scheduled rule runs every 5 minutes with a lookback period of 5 minutes. The documentation mentions an ingestion delay that can reach 5 minutes. What risk does this create and what is the fix?`,hints:[`An event timestamped 12:00 can arrive at 12:04.`,`A longer period creates overlaps.`],explanation:`Events are evaluated according to their timestamp but may arrive after the end of the window. A lookback period longer than the frequency compensates for the delay, at the price of overlaps that grouping alerts into incidents absorbs.`,commonMistakes:[`Setting the lookback period equal to the frequency with no margin.`],choices:[{id:`c1`,text:`Late-arriving events may be covered by no run; lengthen the lookback period (for example 10 minutes) while handling duplicates`},{id:`c2`,text:`None: the 5-minute window always covers everything`},{id:`c3`,text:`Alerts are duplicated; you must reduce the period to 1 minute`},{id:`c4`,text:`The rule is rejected by Sentinel`}]},"sen-005":{title:`Poorly configured brute force rule`,objective:`Spot the configuration line that creates a blind spot.`,statement:"This rule must detect a brute force on `SigninLogs`. Given the ingestion delay, **spot the faulty line** and choose the fix.",hints:[`What gap is there between the frequency and the lookback period?`,`A margin covers the late events.`],explanation:`With a period equal to the frequency, late events escape the rule. An extra margin of 5 minutes, with grouping into incidents to avoid noise, is a common compromise.`,commonMistakes:[`Reducing the period to "go faster".`],lines:[{id:`l1`,text:`Name: Entra ID brute force`},{id:`l2`,text:`Run frequency: 5 minutes`},{id:`l3`,text:`Lookback period: 5 minutes`,faulty:{remedies:[{id:`r3-1`,text:`Lookback period: 10 minutes`},{id:`r3-2`,text:`Lookback period: 1 minute`},{id:`r3-3`,text:`Frequency: 14 days`}]}},{id:`l4`,text:`Threshold: more than 20 failures per IP address`},{id:`l5`,text:`Grouping alerts into incidents: enabled`}]},"sen-006":{title:`Rule: brute force by IP address`,objective:`Write the query of a scheduled brute force rule.`,statement:'Write the query of a rule that returns, for `SigninLogs`, the IP addresses (`IPAddress`) with **at least 20 failures** (`ResultType != "0"`), with the columns `IPAddress` and `Echecs`.',hints:[`Filter the failures, then group by address.`,"The threshold applies after the `summarize`."],explanation:`A scheduled rule returns one row per entity to flag. Here the IP address will become an IP address entity in the incident.`,commonMistakes:["Placing the threshold before the `summarize`.",`Forgetting to restrict to failures.`]},"sen-007":{title:`Rule: deleting a diagnostic setting`,objective:`Detect an attempt to evade logging.`,statement:"In `AzureActivity`, return the deletions of diagnostic settings (`OperationNameValue` containing `DIAGNOSTICSETTINGS/DELETE`) with `TimeGenerated`, `Caller`, `ResourceGroup` and `OperationNameValue`.",hints:["Filter on the operation with `has`.",`Keep only the four requested columns.`],explanation:`This simple detection is very useful: an attacker who cuts logging is trying to hide their following actions.`,commonMistakes:[`Looking for WRITE instead of DELETE.`]},"sen-008":{title:`Automation rule or playbook?`,objective:`Choose the suitable automation tool.`,statement:`Place each action in the most suitable tool.`,hints:[`Automation rules work on the incident itself.`,`As soon as an external system is involved, think playbook.`],explanation:`An automation rule can also launch a playbook: it serves as the trigger, the playbook does the complex work.`,commonMistakes:[`Creating a playbook for a simple assignment.`],items:[{id:`e1`,text:`Assign the incident to the tier 1 team`},{id:`e2`,text:`Add a tag according to the rule name`},{id:`e3`,text:`Change the severity of the incidents of a test environment`},{id:`e4`,text:`Query an external reputation API and comment on the incident`},{id:`e5`,text:`Send a message in a team channel with an approval button`},{id:`e6`,text:`Disable an account after approval`}],zones:[{id:`rule`,label:`Automation rule`,description:`Simple actions on incidents`},{id:`pb`,label:`Playbook`,description:`Logic Apps flow`}]},"sen-009":{title:`Trigger of an automation rule`,objective:`Prefer the incident trigger.`,statement:`Which trigger is recommended for an automation rule and why?`,hints:[`Alerts are grouped into incidents.`,`The incident carries more context.`],explanation:`The incident trigger is preferred: the rule sees the grouped context and can modify the incident. The alert trigger remains useful for specific cases.`,commonMistakes:[`Triggering on every alert and multiplying the actions.`],choices:[{id:`c1`,text:`Incident creation: the incident groups the alerts and offers more actions`},{id:`c2`,text:`Alert creation: always preferable`},{id:`c3`,text:`Deleting a table`},{id:`c4`,text:`None, everything must be automated through playbooks`}]},"sen-010":{title:`Temporary muting`,objective:`Use the expiration date of an automation rule.`,statement:`A server is under maintenance until Friday and generates noisy incidents. How do you avoid losing the detection after Friday?`,hints:[`An automation rule can expire.`,`Disabling the detection is risky if you forget to re-enable it.`],explanation:`The expiration date prevents a temporary exception from becoming permanent. Automation rules run in the defined order, which lets you place the exception before the others.`,commonMistakes:[`Disabling a detection without a return date.`],choices:[{id:`c1`,text:`Create an automation rule that closes these incidents with an expiration date on Friday`},{id:`c2`,text:`Disable the analytics rule with no time limit`},{id:`c3`,text:`Delete the analytics rule`},{id:`c4`,text:`Manually ignore the incidents until the end of the month`}]},"sen-011":{title:`Watchlists: facts and limits`,objective:`Match facts about watchlists.`,statement:`Match each element of Sentinel watchlists to its description.`,hints:[`Think about the join key.`,`It is not a telemetry store.`],explanation:`Watchlists enrich queries with reference data. They do not replace a telemetry table.`,commonMistakes:[`Loading high-volume telemetry into one.`],items:[{id:`m1`,text:`_GetWatchlist('alias')`},{id:`m2`,text:`SearchKey`},{id:`m3`,text:`Recommended use`},{id:`m4`,text:`Maximum size`}],options:[{id:`p1`,text:`KQL function that returns the content of a watchlist`},{id:`p2`,text:`Column used to optimize joins with the list`},{id:`p3`,text:`Reference data (VIPs, critical assets, known IP ranges)`},{id:`p4`,text:`Up to 10 million items`}]},"sen-012":{title:`Join with a VIP list`,objective:`Fix a join with a watchlist.`,statement:"This query must find the failed sign-ins of accounts present in the `VIP` list. **Spot the faulty line.**",hints:[`You want the accounts that are in the list.`,`The negation returns the other accounts.`],explanation:"`!in` returns the accounts absent from the list, which is the opposite of the need. `in (vip)` keeps the VIPs.",commonMistakes:["Swapping `in` and `!in`."],lines:[{id:`l1`,text:`let vip = _GetWatchlist('VIP') | project SearchKey;`},{id:`l2`,text:`SigninLogs`},{id:`l3`,text:`| where UserPrincipalName !in (vip)`,faulty:{remedies:[{id:`r3-1`,text:`| where UserPrincipalName in (vip)`},{id:`r3-2`,text:`| where UserPrincipalName == vip`},{id:`r3-3`,text:`| where UserPrincipalName has "vip"`}]}},{id:`l4`,text:`| where ResultType != "0"`},{id:`l5`,text:`| project TimeGenerated, UserPrincipalName, IPAddress, ResultType`}]},"sen-013":{title:`When to use a watchlist`,objective:`Recognize a good use case.`,statement:`Which of these needs suits a watchlist?`,hints:[`Think reference data.`,`A list is not designed for telemetry volume.`],explanation:`Watchlists are for enriching or filtering: VIPs, critical assets, allowed addresses. They refresh on a schedule and do not replace the log tables.`,commonMistakes:[`Using a list as a database.`],choices:[{id:`c1`,text:`A list of 300 VIP accounts to watch more closely`},{id:`c2`,text:`Storing millions of firewall log rows every day`},{id:`c3`,text:`Replacing the Log Analytics workspace`},{id:`c4`,text:`Archiving closed incidents`}]},"sen-014":{title:`Rule: silent machines`,objective:`Detect the sources that stopped logging.`,statement:"In `Heartbeat`, return the machines (`Computer`) whose **last heartbeat** is older than **30 minutes**, with `Computer` and `DernierePulsation`.",hints:[`Summarize per machine first.`,"Then compare the date to `ago(30m)`."],explanation:"A silent source is a blind spot: it may be down or have been disabled by an attacker. You filter after the `summarize`, otherwise you would lose the silent machines.",commonMistakes:[`Filtering before the summary.`,`Reversing the comparison.`]},"sen-015":{title:`Defender portal: the time column`,objective:`Distinguish the Log Analytics and Advanced Hunting schemas.`,statement:`This Advanced Hunting (Defender XDR) query fails: it uses a column from the other context. **Spot the faulty line.**`,hints:[`Defender XDR tables do not have the same time column as Log Analytics.`,`The last line hints at it.`],explanation:"In the Advanced Hunting tables, the time column is `Timestamp`. In Log Analytics and Sentinel, it is `TimeGenerated`. The Defender portal shows both contexts, so you need to know which table you are querying.",commonMistakes:[`Using TimeGenerated on a Defender XDR table.`],lines:[{id:`l1`,text:`DeviceProcessEvents`},{id:`l2`,text:`| where TimeGenerated > ago(1d)`,faulty:{remedies:[{id:`r2-1`,text:`| where Timestamp > ago(1d)`},{id:`r2-2`,text:`| where TimeGenerated < ago(1d)`},{id:`r2-3`,text:`| where Time > ago(1d)`}]}},{id:`l3`,text:`| where FileName =~ "powershell.exe"`},{id:`l4`,text:`| project Timestamp, DeviceName, ProcessCommandLine`}]},"sen-016":{title:`Triaging an incident`,objective:`Order a triage approach.`,statement:`Put a reasonable approach to triaging a Sentinel incident in order.`,hints:[`Understand before deciding.`,`Closing is the last step.`],explanation:`A good triage goes from the overview to the evidence, then to the documented decision. The closing classification feeds the improvement of the rules.`,commonMistakes:[`Closing without a classification.`,`Deciding before establishing the timeline.`],items:[{id:`o1`,text:`Read the severity, tactics and grouped alerts`},{id:`o2`,text:`Examine the entities (accounts, IP addresses, machines)`},{id:`o3`,text:`Query the logs to establish the timeline`},{id:`o4`,text:`Decide whether the activity is malicious`},{id:`o5`,text:`Apply the response then close with the right classification`}]},"sen-017":{title:`Classifying an incident closure`,objective:`Choose the right closing classification.`,statement:`Match each situation to the appropriate closing classification.`,hints:[`An authorized test is real but harmless.`,`A false positive comes from a flaw in the rule.`],explanation:`These classifications guide tuning: too many false positives signal a rule to fix, benign positives call for a documented exception.`,commonMistakes:[`Classifying as a false positive what is a benign positive.`],items:[{id:`m1`,text:`The successful spray compromised the user l.bouchard`},{id:`m2`,text:`A planned penetration test triggered the rule`},{id:`m3`,text:`The rule fired because of a logic error in the query`},{id:`m4`,text:`The evidence does not allow a conclusion`}],options:[{id:`p1`,text:`True positive`},{id:`p2`,text:`Benign positive`},{id:`p3`,text:`False positive`},{id:`p4`,text:`Undetermined`}]},"sen-018":{title:`Assessment: scheduled rule to fix`,objective:`Fix two logic flaws in a detection rule.`,statement:`This rule should detect the successful sign-ins of VIPs from an address that carried out a spray. **Spot the two faulty lines.**`,hints:[`You are looking for successes.`,`You are looking for VIP accounts.`],explanation:'The `!= "0"` filter selects the failures whereas the detection targets the successes, and `!in` excludes the VIPs instead of keeping them.',commonMistakes:[`Fixing only one of the two errors.`],lines:[{id:`l1`,text:`let vip = _GetWatchlist('VIP') | project SearchKey;`},{id:`l2`,text:`let sources = SigninLogs | where ResultType == "50126" | summarize Comptes = dcount(UserPrincipalName) by IPAddress | where Comptes > 10 | project IPAddress;`},{id:`l3`,text:`SigninLogs`},{id:`l4`,text:`| where ResultType != "0"`,faulty:{remedies:[{id:`r4-1`,text:`| where ResultType == "0"`},{id:`r4-2`,text:`| where ResultType == "50126"`},{id:`r4-3`,text:`| where ResultType > 0`}]}},{id:`l5`,text:`| where IPAddress in (sources)`},{id:`l6`,text:`| where UserPrincipalName !in (vip)`,faulty:{remedies:[{id:`r6-1`,text:`| where UserPrincipalName in (vip)`},{id:`r6-2`,text:`| where UserPrincipalName == "vip"`},{id:`r6-3`,text:`| where UserPrincipalName has_any (vip)`}]}},{id:`l7`,text:`| project TimeGenerated, UserPrincipalName, IPAddress`}]}},l={"soc-001":{title:`Encoded PowerShell`,objective:`Spot an encoded PowerShell command line.`,statement:"In `DeviceProcessEvents`, return the executions of `powershell.exe` whose command line contains `-enc` or `-EncodedCommand`. Columns: `Timestamp`, `DeviceName`, `ProcessCommandLine`, `InitiatingProcessFileName`.",hints:["`has_any` tests several terms at once.",`Compare the file name without case sensitivity.`],explanation:"Base64-encoded PowerShell is common among attackers **and** among some legitimate administration tools (for example the management client). The parent process (`InitiatingProcessFileName`) is often what separates the legitimate from the suspicious.",commonMistakes:[`Concluding a compromise without looking at the parent process.`,"Comparing with `==`: the name may be in uppercase depending on the source."]},"soc-002":{title:`Investigation: does a password spray succeed?`,objective:`Confirm a spray, identify the affected account and choose the first response.`,statement:"A detection rule flags a burst of failures from `203.0.113.45`. You triage the incident: is the spray real, is an account compromised, and what do you do first?",hints:[`A spray hits many accounts with few attempts each.`,`Check whether the same address also has a success.`],explanation:`The approach: measure the scale, look for the success, contain the affected account, then widen. Blocking the address alone does not repair an account that is already compromised.`,commonMistakes:[`Settling for blocking the IP address.`,`Not looking for a success among the failures.`],scenario:'Alert "Sign-in failures from a single address" on the Nordlys tenant. The data is in `SigninLogs`. Code `50126` means "invalid username or password".',steps:[{id:`s1`,prompt:"How many distinct accounts did this address target with code `50126`?",explanation:`Fourteen accounts for 28 failures: about two attempts per account. This is the signature of a spray, which avoids lockout by limiting the attempts per account.`,evidence:[{title:`Address activity by result code`}]},{id:`s2`,prompt:"Write the query that returns the **successful** sign-ins from this address, with `TimeGenerated`, `UserPrincipalName`, `AppDisplayName` and `Location`.",explanation:`A single successful sign-in, at 02:43:12 UTC, to Exchange Online, from Russia: a success after a spray means a password was guessed.`},{id:`s3`,prompt:`Which account is probably compromised?`,explanation:`The success concerns l.bouchard. s.roy was also targeted by the spray but without a success from this address. svc-backup2 does not exist yet at that moment.`,choices:[{id:`c1`,text:`s.roy@nordlys.example`},{id:`c2`,text:`l.bouchard@nordlys.example`},{id:`c3`,text:`c.tremblay@nordlys.example`},{id:`c4`,text:`svc-backup2@nordlys.example`}]},{id:`s4`,prompt:`What is the best first containment action?`,explanation:`You must cut off the attacker's access (password, sessions) and check what they did next. Deleting the account destroys evidence; blocking the address alone leaves the sessions active.`,choices:[{id:`c1`,text:`Only block the IP address and close the incident`},{id:`c2`,text:`Reset l.bouchard's password, revoke their sessions and review their activity after 02:43`},{id:`c3`,text:`Delete the l.bouchard account`},{id:`c4`,text:`Wait for a second alert before acting`}]}]},"soc-003":{title:`Investigation: the attacker grants themselves privileges`,objective:`Follow the privilege escalation in AuditLogs then in AzureActivity.`,statement:"The `l.bouchard` account is compromised. You look for what it modified in Entra ID and then what followed in Azure.",hints:["AuditLogs: `InitiatedBy` is a dynamic object, `has` works well on it.",`Link the two sources with the attacker's IP address.`],explanation:`The attacker creates a discreet service account, gives it the Global Administrator role, tries to elevate their own account, then acts on the Azure resources from the same address.`,commonMistakes:[`Only looking at SigninLogs.`,`Forgetting the failed attempt, which indicates intent.`],scenario:"Directory operations are in `AuditLogs`, Azure operations in `AzureActivity`. The attacker's address is `203.0.113.45`.",steps:[{id:`s1`,prompt:"List the directory operations initiated by `l.bouchard`: `TimeGenerated`, `OperationName` and `Result`.",explanation:`Three operations: creation of an account, addition of that account to a role, then an attempt to add l.bouchard themselves to a role, which fails.`},{id:`s2`,prompt:"Which role did the new account `svc-backup2` receive?",explanation:`Global Administrator is the most powerful role in the tenant. A "backup" account created a few minutes after a compromise and elevated to this role is a strong persistence signal.`,choices:[{id:`c1`,text:`Reader`},{id:`c2`,text:`Contributor`},{id:`c3`,text:`Global Administrator`},{id:`c4`,text:`Security Reader`}],evidence:[{title:`Role addition detail`}]},{id:`s3`,prompt:`Which operation **failed**, and what does it reveal?`,explanation:`The failed attempt shows the intent to elevate the stolen account. A failure is information: it indicates what the attacker wanted to do and what the protection stopped.`,choices:[{id:`c1`,text:`An addition of l.bouchard to the Privileged Role Administrator role: the attacker was trying to elevate themselves`},{id:`c2`,text:`A deletion of svc-backup2: the attacker was erasing their tracks`},{id:`c3`,text:`A password reset: the administrator was reacting`},{id:`c4`,text:`A change of the workspace region`}]},{id:`s4`,prompt:"List the Azure operations made from the attacker's address: `TimeGenerated`, `OperationNameValue` and `ResourceGroup`.",explanation:`The same address acts in Azure: role assignment, four virtual machine writes in rg-prod, then deletion of a diagnostic setting in rg-sec. The address links the two sources.`},{id:`s5`,prompt:`Which containment and remediation actions are appropriate? Several answers.`,explanation:`You cut the accesses created by the attacker, examine their infrastructure changes and restore logging. Deleting the workspace would destroy the evidence.`,choices:[{id:`c1`,text:`Disable svc-backup2 and remove its Global Administrator role`},{id:`c2`,text:`Revoke l.bouchard's sessions and reset their password`},{id:`c3`,text:`Examine the virtual machines written in rg-prod`},{id:`c4`,text:`Restore the diagnostic setting deleted in rg-sec`},{id:`c5`,text:`Delete the Log Analytics workspace to start from scratch`}]}]},"soc-004":{title:`Investigation: RDP brute force on the file server`,objective:`Qualify a successful RDP brute force and its aftermath on Windows.`,statement:"An alert reports many sign-in failures on `SRV-FILE01`. You determine whether the attack succeeded and what followed.",hints:[`Compare the time of the success to that of the failures.`,`Look at the account management events on the same machine.`],explanation:`A brute force followed by a success, then by the creation of an account and its addition to a local group, is a classic persistence sequence.`,commonMistakes:[`Stopping at the number of failures.`,`Ignoring events 4720 and 4732.`],scenario:"The Windows events are in `SecurityEvent`: 4625 sign-in failure, 4624 success, 4672 special privileges, 4720 account creation, 4732 addition to a local group.",steps:[{id:`s1`,prompt:"How many failures (4625) come from `198.51.100.23` on `SRV-FILE01`?",explanation:`Sixty failures from a single address: a classic brute force, not a user's password mistake.`},{id:`s2`,prompt:"Return the successful sign-ins (4624) from this address on `SRV-FILE01`: `TimeGenerated`, `Account`, `IpAddress`.",explanation:`A success exists after the failures: the attack succeeded. The time of the success, compared to the last failure, confirms it.`},{id:`s3`,prompt:"Return the account creations (4720) and additions to a local group (4732) on `SRV-FILE01`: `TimeGenerated`, `EventID`, `Account`.",explanation:`Two events two minutes apart, performed by the Administrator account: an account is created then added to a local group. This is persistence.`},{id:`s4`,prompt:`What conclusion and which action do you prioritize?`,explanation:`A success after a brute force plus the creation of a local privileged account is a compromise. You must also fix the RDP exposure (see the lesson on Bastion and NSGs).`,choices:[{id:`c1`,text:`Confirmed compromise: isolate the server, disable the new account, reset the local credentials and close the RDP exposure`},{id:`c2`,text:`False positive: a scheduled administration task`},{id:`c3`,text:`Harmless noise: close the incident`},{id:`c4`,text:`Restart the server and monitor`}]}]},"soc-005":{title:`Investigation: SSH dictionary attack on a Linux server`,objective:`Read Syslog logs and conclude a root compromise.`,statement:"Massive SSH attempts target `LNX-APP01`. You establish whether the attacker got in and under which account.",hints:["The failure messages contain `Failed password`.","A success contains `Accepted password`."],explanation:`Forty-two failures then an accepted authentication for root: a remote root access by password succeeded.`,commonMistakes:[`Forgetting to look for the success message.`,`Not noting that root accepts a password over SSH.`],scenario:"The sshd logs are in `Syslog` (`Computer`, `ProcessName`, `SyslogMessage`). The suspicious address is `203.0.113.99`.",steps:[{id:`s1`,prompt:"How many `Failed password` messages mention `203.0.113.99` on `LNX-APP01`?",explanation:`Forty-two failed attempts: a password dictionary attack.`},{id:`s2`,prompt:"Return the accepted authentications on this machine: `TimeGenerated`, `Computer`, `SyslogMessage`.",explanation:`A message "Accepted password for root from 203.0.113.99" at 01:26:03: the attacker got in with the root account.`},{id:`s3`,prompt:`Which measures are relevant? Several answers.`,explanation:`You contain, preserve the evidence and fix the cause: direct exposure and weak authentication. The time of an access does not make it legitimate.`,choices:[{id:`c1`,text:`Isolate the machine and keep a copy for analysis`},{id:`c2`,text:`Disable direct SSH login for root and password authentication`},{id:`c3`,text:`Restrict SSH access to a managed jump point`},{id:`c4`,text:`Ignore: the access only took place outside office hours`}]}]},"soc-006":{title:`Investigation: large outbound transfer`,objective:`Quantify an exfiltration from firewall logs.`,statement:`An alert about an abnormal outbound volume on the firewall reaches you. You measure the transfer, identify the source and destination, and decide on the next steps.`,hints:[`Summarize by source and destination.`,`Observe the evolution of the volume over time.`],explanation:`Twelve increasingly large transfers to the same destination, from a single internal workstation: the profile of an organized transfer, not a one-off upload.`,commonMistakes:[`Looking at a single event instead of the trend.`,`Not identifying the internal source.`],scenario:"The firewall logs are in `CommonSecurityLog` (`SourceIP`, `DestinationIP`, `SentBytes`, `DeviceAction`). The suspicious destination is `203.0.113.200`.",steps:[{id:`s1`,prompt:"What is the largest `SentBytes` value to `203.0.113.200`?",explanation:`About 43 million bytes in a single transfer, and the volumes increase with each attempt.`},{id:`s2`,prompt:"Return, per source address, the number of transfers (`Transferts`) and the total volume (`Total`) to `203.0.113.200`.",explanation:`A single internal source, 10.20.1.15, performed twelve transfers for about 439 MB in total.`},{id:`s3`,prompt:`Which reading is the most defensible?`,explanation:`Regularity, growth and the uniqueness of the destination are clues. You must confirm by examining the source workstation and the nature of the data before concluding.`,choices:[{id:`c1`,text:`Regular and growing transfers to a single external destination: probable exfiltration, to be confirmed on the source workstation`},{id:`c2`,text:`Usual nightly backup with no stakes`},{id:`c3`,text:`Operating system update`},{id:`c4`,text:`Normal web browsing traffic`}]},{id:`s4`,prompt:`What do you do next? Several answers.`,explanation:`You contain the source, cut the destination and look for the extent. In the Nordlys data, the same destination also appears in a phishing incident: see the next investigation.`,choices:[{id:`c1`,text:`Identify the workstation 10.20.1.15 and isolate it`},{id:`c2`,text:`Block 203.0.113.200 at the firewall`},{id:`c3`,text:`Search for other hosts that contacted 203.0.113.200`},{id:`c4`,text:`Wait for the next monthly report cycle`}]}]},"soc-007":{title:`Investigation: phishing and encoded PowerShell`,objective:`Link email, process and network in Defender XDR.`,statement:"Emails from the host `n0rdlys-login.example` were blocked, but a workstation runs encoded PowerShell launched by Word. You reconstruct the chain.",hints:[`A child process of WINWORD.EXE is rarely legitimate.`,"Join by `DeviceName` and time."],explanation:`The phishing email was blocked for two recipients, but a document reached a workstation (by another path) and launched PowerShell, which contacts an external domain.`,commonMistakes:[`Concluding that blocking the email settles everything.`,`Confusing the legitimate PowerShell of ccmexec.exe with that of Word.`],scenario:"Defender XDR context (Advanced Hunting): `EmailEvents`, `DeviceProcessEvents`, `DeviceNetworkEvents`. The time column is `Timestamp`.",steps:[{id:`s1`,prompt:"How many emails from `n0rdlys-login.example` were blocked as phishing?",explanation:`Two blocked emails, targeting executives. The block is a success of the protection, but says nothing about the rest.`},{id:`s2`,prompt:"Find the PowerShell processes launched by `WINWORD.EXE`: `Timestamp`, `DeviceName`, `AccountName`, `ProcessCommandLine`.",explanation:"A single result: hidden PowerShell (`-w hidden`), without profile (`-nop`), with an encoded command (`-enc`), launched by Word on PC-017."},{id:`s3`,prompt:"Which network connection did PowerShell establish afterwards? Return `Timestamp`, `DeviceName`, `RemoteUrl` and `RemoteIP` for the URL containing `exfil-demo`.",explanation:"One minute after the launch, PowerShell contacts `cdn.exfil-demo.example`, whose address is 203.0.113.200, the same as the destination of the large transfer seen in the previous investigation."},{id:`s4`,prompt:"Another workstation, PC-003, also runs encoded PowerShell, but launched by `ccmexec.exe`. What do you conclude?",explanation:`Context distinguishes the two cases: a configuration management parent is expected, a Word parent is not. You still confirm, without presuming.`,choices:[{id:`c1`,text:`Probably legitimate (configuration management agent), to be confirmed with the script owner, unlike PC-017`},{id:`c2`,text:`Compromised in the same way as PC-017`},{id:`c3`,text:`Unimportant because PowerShell is always legitimate`},{id:`c4`,text:`The whole fleet must be isolated`}]},{id:`s5`,prompt:`Which actions are appropriate? Several answers.`,explanation:`You contain the workstation, cut the outbound communication and protect the credentials. Disabling PowerShell everywhere is disproportionate and breaks legitimate administration.`,choices:[{id:`c1`,text:`Isolate PC-017 through the detection platform`},{id:`c2`,text:`Block the destination domain and address`},{id:`c3`,text:`Reset the credentials of the workstation's user`},{id:`c4`,text:`Immediately disable PowerShell across the whole fleet`}]}]},"soc-008":{title:`Investigation: impossible travel of s.roy`,objective:`Qualify an impossible travel alert without jumping to conclusions.`,statement:"An alert reports two sign-ins by `s.roy` from two countries in a short time. You check the facts before concluding.",hints:[`Look for sign-ins outside Canada.`,`A VPN or a proxy can explain unexpected countries.`],explanation:`An impossible travel alert is a signal, not a verdict. You look for corroborating elements before containing.`,commonMistakes:[`Concluding a compromise without corroboration.`,`Ignoring the failed attempts tied to the same user.`],scenario:"Source: `SigninLogs`. The user usually signs in from Canada.",steps:[{id:`s1`,prompt:"Return the sign-ins of `s.roy@nordlys.example` from outside Canada: `TimeGenerated`, `IPAddress`, `Location`, `ResultType`.",explanation:`Three rows: two failures from Russia (the spray address, on March 10) and a success from Brazil on March 11 at 14:40 UTC, 35 minutes after a Canadian sign-in.`},{id:`s2`,prompt:`How many distinct countries do we see for this user (without a filter)?`,explanation:`Three countries: Canada, Russia, Brazil. Canada is the user's norm.`},{id:`s3`,prompt:`What is the best next step?`,explanation:`Corroborate first: a 35-minute move is physically impossible, but a corporate VPN can explain it. Containment follows if the explanation is missing.`,choices:[{id:`c1`,text:`Check with the user (VPN, travel, device), examine the detail of the Brazilian session and contain if nothing explains it`},{id:`c2`,text:`Close as a false positive without checking`},{id:`c3`,text:`Delete the account immediately`},{id:`c4`,text:`Block all of Brazil for all users`}]}]},"soc-009":{title:`Final mission: the Nordlys incident end to end`,objective:`Reconstruct a complete incident: initial access, privileges, impact, exfiltration, response.`,statement:`Final mission. The March 10 incident at Nordlys left traces in six sources. You reconstruct it and write the key decisions.`,hints:[`Follow the chronological order.`,`Link the sources with the attacker's address and the created account.`],explanation:`The chain: spray, compromise of an account, persistence through a privileged account, actions in Azure, disabling of logging, then exfiltration. Each link could have been detected.`,commonMistakes:[`Treating each alert as a separate incident.`,`Closing the incident after containing the first account.`],scenario:"You have `SigninLogs`, `AuditLogs`, `AzureActivity` and `CommonSecurityLog`. Times are in UTC. The first sign is a successful Russian sign-in.",steps:[{id:`s1`,prompt:"What is the attacker's first successful sign-in (address 203.0.113.45)? Return `TimeGenerated` and `UserPrincipalName`.",explanation:`l.bouchard at 02:43:12: this is the initial access.`},{id:`s2`,prompt:"In AzureActivity, how many distinct operations (`OperationNameValue`) did `svc-backup2` perform?",explanation:`Three types of operations: role assignment, virtual machine writes, deletion of a diagnostic setting.`},{id:`s3`,prompt:`Which action was used to reduce the security team's visibility?`,explanation:`Deleting the diagnostic setting is a defense evasion: it cuts the sending of logs from the targeted resource.`,choices:[{id:`c1`,text:`The deletion of a diagnostic setting in rg-sec`},{id:`c2`,text:`The writing of virtual machines in rg-prod`},{id:`c3`,text:`The addition of a user in the directory`},{id:`c4`,text:`The sign-in from Russia`}]},{id:`s4`,prompt:"What is the maximum volume of a transfer to `203.0.113.200`?",explanation:`About 43 million bytes in one transfer, with a growing trend.`},{id:`s5`,prompt:`Classify the incident at closure.`,explanation:`Compromise of an account, privilege escalation, impact on the infrastructure and exfiltration: a true positive, to be documented to improve the detections.`,choices:[{id:`c1`,text:`False positive`},{id:`c2`,text:`Benign positive`},{id:`c3`,text:`True positive`},{id:`c4`,text:`Undetermined`}]},{id:`s6`,prompt:`Which detections would you add to cut the chain earlier? Several answers.`,explanation:`Each link has a targeted low-noise detection. Alerting on every individual failure would drown the team without helping.`,choices:[{id:`c1`,text:`A sign-in success from an address that failed on many accounts`},{id:`c2`,text:`A Global Administrator role assignment outside a PIM activation`},{id:`c3`,text:`The deletion of a diagnostic setting`},{id:`c4`,text:`A growing outbound volume to a rare destination`},{id:`c5`,text:`An alert for every individual sign-in failure`}]}]}},u={exercises:{...i,...a,...o,...s,...c,...l},lessons:r,labs:n,paths:e,competencies:t};export{u as EN};